export const introQuestions: IntroQuestion[] = [{"id":"p001-01","examId":"p001","number":1,"stem":"Dentre as afirmativas listadas abaixo, podemos apontar como característica dos queloides:","options":{"A":"Independe da raça, local e idade; e não possuem componente genético","B":"São lesões elevadas, mas que respeitam os limites da cicatriz","C":"Podem ocorrer em regiões de pouca tensão da pele, como região pré-esternal","D":"Aparecem após 4 semanas, mas regridem com o tempo"},"answer":"C","explanation":"O gabarito marca o queloide como lesão que pode surgir mesmo em área de pouca tensão, e a região pré-esternal é sítio clássico. Respeitar o limite da cicatriz e regredir com o tempo descrevem a cicatriz hipertrófica. Há componente genético e influência de raça e local."},{"id":"p001-02","examId":"p001","number":2,"stem":"O tipo de curativo mais indicado em uma ferida, onde se deseja evitar ao máximo a infecção, desde que a ferida esteja limpa e pouco exsudativa, é o curativo:","options":{"A":"Com hidrocolóide","B":"Com alginato","C":"Absorvente","D":"Oclusivo"},"answer":"D","explanation":"Ferida limpa e pouco exsudativa se beneficia do curativo oclusivo, que isola a ferida do meio externo e reduz o risco de contaminação. Alginato e absorvente são para exsudato abundante."},{"id":"p001-03","examId":"p001","number":3,"stem":"Uma das primeiras técnicas de cirurgia para obesidade consistia em um procedimento que alterava a forma e a função do estômago, de modo a reduzir seu volume. Neste procedimento não havia retirada de parte do estômago (a figura mostra grampeamento/banda vertical, sem ressecção). Este procedimento podemos chamar, de forma resumida, de uma:","options":{"A":"Gastroplastia","B":"Gastroanastomose","C":"Gastropexia","D":"Gastrectomia"},"answer":"A","explanation":"Plastia = remodelação. A gastroplastia reduz o volume sem retirar o órgão. Gastrectomia removeria parte do estômago; pexia é fixação; anastomose é união de segmentos."},{"id":"p001-04","examId":"p001","number":4,"stem":"O tipo de colágeno responsável pela formação da cicatriz imatura, e que vai sendo substituído pelo colágeno definitivo, mais firme, é do tipo:","options":{"A":"II","B":"I","C":"IV","D":"III"},"answer":"D","explanation":"A cicatriz imatura é rica em colágeno tipo III, depois substituído pelo tipo I, mais firme e organizado, na remodelação."},{"id":"p001-05","examId":"p001","number":5,"stem":"A colocação de campos cirúrgicos estéreis logo antes da incisão cirúrgica faz parte de que princípio de prevenção de infecção de sítio cirúrgico?","options":{"A":"Degermação","B":"Assepsia","C":"Esterilização","D":"Antissepsia"},"answer":"B","explanation":"Assepsia é o conjunto de medidas para impedir a entrada de microrganismos no campo (campos, luvas, material estéril). Antissepsia age sobre tecidos vivos; esterilização destrói toda forma de vida em objetos; degermação é a redução da flora da pele com detergente."},{"id":"p001-06","examId":"p001","number":6,"stem":"Durante a resposta orgânica frente a uma agressão cirúrgica, especialmente na chamada fase flow inicial, esperamos encontrar:","options":{"A":"Diminuição da gliconeogênese","B":"Aumento da diurese","C":"Aumento da excreção do potássio","D":"Balanço nitrogenado positivo"},"answer":"C","explanation":"Na fase flow há hipermetabolismo, balanço nitrogenado negativo e aumento da excreção de potássio. A gliconeogênese aumenta, e a diurese não é o achado típico dessa fase inicial catabólica."},{"id":"p001-07","examId":"p001","number":7,"stem":"Paciente apresentando cicatriz hipertrófica em local de sutura de incisão de portal utilizado para correção de hérnia inguinal laparoscópica há um mês. Ao exame temos cicatriz de cerca de 2 cm, de bordos elevados, que respeitam os limites da cicatriz em fossa ilíaca direita. Qual das terapias abaixo é melhor indicada como primeira linha neste caso para reduzir a alteração de relevo na cicatriz, e com melhores resultados quanto à recidiva quando aplicada isoladamente?","options":{"A":"Injeção de corticoides","B":"Radioterapia","C":"Ressecção cirúrgica","D":"Tratamento com compressão"},"answer":"D","explanation":"Cicatriz hipertrófica recente, dentro dos limites da ferida: a banca indica compressão isolada como primeira linha, com melhor perfil de recidiva. Ressecção isolada e radioterapia não são o primeiro passo; corticoide é opção, mas não a marcada."},{"id":"p001-08","examId":"p001","number":8,"stem":"Paciente de 35 anos, apresentando quadro de dor pélvica aguda e febre. Realizou ultrassonografia que mostrou imagem compatível com abscesso na trompa uterina direita, sendo encaminhada para cirurgia de urgência. Durante o procedimento, o cirurgião retirou cirurgicamente a trompa uterina direita. Este procedimento tem como nomenclatura:","options":{"A":"Ooforectomia","B":"Salpingectomia","C":"Histerotomia","D":"Trompoplastia"},"answer":"B","explanation":"Salpinge = trompa; ectomia = retirada. Ooforectomia retira ovário; histerotomia é incisão do útero."},{"id":"p001-09","examId":"p001","number":9,"stem":"Assinale na coluna abaixo com a letra I para fios Inabsorvíveis e A para fios Absorvíveis; e assinale dentre as alternativas a sequência correta: ( ) Categute ( ) Nylon ( ) Polipropileno ( ) Ácido poligalactico ( ) Poliodioxanona","options":{"A":"A, I, I, A, A","B":"I, I, A, A, I","C":"A, A, I, I, I","D":"A, I, A, A, I"},"answer":"A","explanation":"Absorvíveis: categute, ácido poliglicólico (poligalálico) e polidioxanona (PDS). Inabsorvíveis: nylon e polipropileno."},{"id":"p001-10","examId":"p001","number":10,"stem":"Na chamada fase ebb (até 3 dias) da resposta orgânica ao trauma, principalmente uma agressão de maior magnitude, normalmente encontramos:","options":{"A":"Retenção de sódio","B":"Hipoglicemia","C":"Diminuição da frequência cardíaca","D":"Vasodilatação"},"answer":"A","explanation":"A fase ebb é de hipovolemia relativa: retenção de sódio e água, vasoconstrição, taquicardia e hiperglicemia — não hipoglicemia."},{"id":"p001-11","examId":"p001","number":11,"stem":"Sobre as soluções utilizadas no processo de antissepsia, é correto afirmar que:","options":{"A":"O álcool etílico promove desnaturação de proteínas da membrana com lise celular","B":"Os iodóforos, como a iodopovidona, apresentam boa ação contra bactérias na forma de esporos","C":"A tintura de iodo é uma ótima opção para se utilizar em feridas abertas, pois irrita pouco a pele","D":"A clorexidina apresenta melhor ação contra germes gram-negativos"},"answer":"A","explanation":"O álcool desnatura proteínas e lisa a célula. Iodóforos são fracos contra esporos; a tintura de iodo irrita feridas; a clorexidina é mais ativa contra gram-positivos."},{"id":"p001-12","examId":"p001","number":12,"stem":"Paciente submetida a tireoidectomia parcial através de incisão transversa, na região anterior do pescoço. A síntese da pele foi realizada com pontos simples, sem tensão, com fio nylon 4-0. O período mais adequado para a retirada dos pontos, dentre os abaixo, seria após:","options":{"A":"5 dias","B":"10 dias","C":"7 dias","D":"14 dias"},"answer":"C","explanation":"Pele do pescoço, sem tensão: a banca indica retirada em 7 dias. Face costuma ser mais cedo; tronco e membros, mais tarde."},{"id":"p001-13","examId":"p001","number":13,"stem":"A suplementação de uma determinada vitamina pode melhorar a cicatrização e, especialmente no diabetes e na radioterapia, além de reverter os efeitos de corticosteroides. Estamos falando da:","options":{"A":"Vitamina D","B":"Vitamina K","C":"Vitamina C","D":"Vitamina A"},"answer":"D","explanation":"A vitamina A melhora a cicatrização, ajuda no diabetes e na área irradiada e reverte o efeito inibitório dos corticoides sobre a reparação. A vitamina C é cofator do colágeno, mas não é a que reverte corticoide."},{"id":"p001-14","examId":"p001","number":14,"stem":"Paciente submetido à laparotomia por diverticulite perfurada com peritonite grave. Devido à intensa contaminação da cavidade abdominal, decidiu-se deixá-la aberta (peritoneostomia). Após 14 dias, notou-se que o processo infeccioso já estava sanado, com formação de tecido de granulação. Sendo assim, decidiu-se pelo fechamento definitivo da parede abdominal e pele. Este tipo de fechamento é conhecido como cicatrização por:","options":{"A":"Segunda intenção","B":"Necessidade","C":"Terceira intenção","D":"Primeira intenção"},"answer":"C","explanation":"Terceira intenção (fechamento primário tardio): a ferida fica aberta pela contaminação e só é suturada depois de controlada a infecção e formado tecido de granulação."},{"id":"p001-15","examId":"p001","number":15,"stem":"Paciente com úlcera crônica em membro inferior esquerdo, próxima ao tornozelo, indolor, de fundo úmido, bordos pouco edemaciados, mas sem sinais de infecção. Ao exame clínico observa-se hiperpigmentação da perna do mesmo lado da úlcera, sem alteração de sensibilidade, mas com prurido na pele escurecida. Foi realizada uma biópsia que deu negativo para malignidade. Dentre os diagnósticos abaixo, qual o mais provável desta úlcera?","options":{"A":"Úlcera de Marjolin","B":"Úlcera venosa","C":"Úlcera arterial","D":"Úlcera diabética"},"answer":"B","explanation":"Úlcera perimaleolar, indolente, exsudativa, com hiperpigmentação e prurido (dermatite ocre / lipodermatosclerose) é o quadro clássico de úlcera venosa. Marjolin é malignização de úlcera crônica — a biópsia foi negativa."},{"id":"p001-16","examId":"p001","number":16,"stem":"A principal célula presente na fase inflamatória da cicatrização, que além de função fagocitária, libera uma série de mediadores inflamatórios é o:","options":{"A":"Fibroblasto","B":"Neutrófilo","C":"Monócito","D":"Macrófago"},"answer":"D","explanation":"O macrófago é a célula central da fase inflamatória: fagocita debris e secreta citocinas que orquestram a passagem para a proliferação. O neutrófilo chega antes, mas não é o maestro dos mediadores."},{"id":"p001-17","examId":"p001","number":17,"stem":"No ambiente cirúrgico, temos vários locais com níveis de potencial de contaminação distintos. O expurgo é o local onde são lavados os instrumentos utilizados durante a cirurgia, é feito o descarte de materiais que tiveram contato com secreções e fluidos dos pacientes, bem como o preparo de peças cirúrgicas que serão encaminhadas ao serviço de Anatomia Patológica. Este local fica em uma zona chamada de:","options":{"A":"Proteção","B":"Crítica","C":"Limpa","D":"Estéril"},"answer":"A","explanation":"Pelo gabarito desta prova, o expurgo situa-se na zona de proteção (área de circulação controlada, fora do campo estéril). Zona limpa/estéril é o centro cirúrgico propriamente dito."},{"id":"p001-18","examId":"p001","number":18,"stem":"Durante a confecção de uma colostomia, o cirurgião decidiu realizá-la através do músculo reto abdominal. Para a passagem do cólon pela parede abdominal, o cirurgião afastou as fibras do músculo, sem cortá-las, com o auxílio de uma pinça de Kelly e de afastadores. Se tratando de um método de diérese mecânica, este é denominado como:","options":{"A":"Divulsão","B":"Dilatação","C":"Secção","D":"Descolamento"},"answer":"A","explanation":"Divulsão é a separação romba das fibras, sem cortá-las. Secção corta; dilatação amplia um ducto ou orifício; descolamento separa planos por planos de clivagem."},{"id":"p001-19","examId":"p001","number":19,"stem":"Na resposta orgânica a uma agressão cirúrgica, também chamada de resposta endócrina metabólica e imune ao trauma (REMIT), os órgãos mais afetados são:","options":{"A":"Pulmões e rins","B":"Fígado e coração","C":"Fígado e músculos","D":"Rins e músculos"},"answer":"C","explanation":"Nesta prova, os órgãos mais atingidos pelo catabolismo da REMIT são fígado (gliconeogênese, proteínas de fase aguda) e musculatura esquelética (proteólise)."},{"id":"p001-20","examId":"p001","number":20,"stem":"Paciente foi submetido a uma sutura de pele no antebraço por conta de um ferimento superficial, que foi suturado com fio nylon 4-0 em pontos simples, sem tensão. Após 14 dias de evolução favorável, decidiu-se tirar os pontos no ambulatório, mas após dois meses, o paciente notou que a cicatriz apresenta coloração discretamente mais clara que a pele, bordos elevados, mas respeitando a linha da cicatriz. Essa diferença de relevo da cicatriz é explicada por:","options":{"A":"Excesso de contração na fase de maturação","B":"Superabundância de fibroblastos no processo de cura da derme","C":"Escolha inadequada do fio e do tipo de sutura","D":"Predominância de colágeno tipo III na cicatriz"},"answer":"B","explanation":"Relevo elevado dentro da linha da cicatriz traduz excesso de fibroblastos e de matriz na derme (cicatriz hipertrófica). Aos dois meses o colágeno III já está sendo substituído; fio e ponto estavam adequados."},{"id":"p108-01","examId":"p108","number":1,"stem":"Durante um plantão como acadêmico no HUV você é chamado pra entrar como auxiliar em uma cirurgia de emergência, uma provável apendicite. Com relação as técnicas de assepsia e antissepsia, qual deveria ser a ordem correta das ações apresentadas abaixo?","options":{"A":"Colocação capote, toca e máscara, escovação das mãos e colocação das luvas.","B":"Colocação de toca e máscara, escovação das mãos, colocação luvas e colocação do capote.","C":"Colocação de toca e máscara, escovação das mãos, colocação capote e colocação luvas.","D":"Escovação das mãos, colocação de luvas, colocação capote, colocação de máscara e toca."},"answer":"C","explanation":"Primeiro toca e máscara, depois escovação, em seguida o capote estéril e por último as luvas."},{"id":"p108-02","examId":"p108","number":2,"stem":"Em relação a nomenclatura cirúrgica , marque a alternativa que apresenta o conceito correto a respeito desta.","options":{"A":"Ureterografia indica que foi realizada uma sutura no ureter do paciente.","B":"O termo clise determina lavagem.","C":"O principal processo de formação de termos cirúrgicos é a pré fixação.","D":"No processo de sufixação , temos a raiz do termo que significa a ação efetuada e o sufixo que determina o órgão onde se efetua tal ação."},"answer":"B","explanation":"Clise = lavagem. Ureterografia é estudo contrastado. O processo principal é a sufixação: a raiz é o órgão e o sufixo é a ação."},{"id":"p108-03","examId":"p108","number":3,"stem":"J.P.A., 39 anos, sexo feminino, sem comorbidades, iniciou quadro há 2 anos de dor abdominal em hipocôndrio direito associado a náuseas e mal estar após ingesta de alimentação hipercalórica, sugestivo de colelitíase sintomática. Indicado cirurgia eletiva e durante procedimento cirúrgico eletivo foi confirmado quadro de calculose biliar, sem sinais de colecistite. Feita a colecistectomia por videolaparoscopia (procedimento sem intercorrências). No entanto qual a classificação intraoperatória do grau de contaminação e uso do antibiótico para esta cirurgia:","options":{"A":"Contaminada, devendo usar antibioticoprofilático.","B":"Infectada, devendo usar antibioticoterapia .","C":"Potencialmente contaminada, e não deve usar antibioticoprofilático ou antibioticoterapia.","D":"Limpa, e não deve usar antibiotico."},"answer":"C","explanation":"Gabarito desta prova: potencialmente contaminada (contato controlado com a flora biliar) e, no critério do texto, sem indicação rotineira de profilaxia ou terapia na ausência de fatores de risco. Não é ferida infectada nem limpa."},{"id":"p108-04","examId":"p108","number":4,"stem":"Paciente sofre um acidente de motocicleta, com corte profundo no braço direito, com perda de tecido impossibilitando a sutura. Alguns dias depois, tomando os devidos cuidados, a ferida vem apresentando bom aspecto de cicatrização. A ferida já não sangra, está sem edema, sem sinais de infecção e com formação de tecido de granulação. Com essas informações é correto afirmar:","options":{"A":"A ferida na fase maturação, os macrófago são ativados e formam novos vasos sanguíneos.","B":"A ferida está na fase inflamatória, os fibroblastos são ativados e formam novos vasos sanguíneos.","C":"A ferida está na fase proliferativa, as células endoteliais são ativadas para formar novos vasos sanguíneos.","D":"A ferida está na fase proliferativa, as células epiteliais são ativadas e formam novos vasos sanguíneos."},"answer":"C","explanation":"Tecido de granulação é a fase proliferativa. Quem forma os novos vasos são as células endoteliais, não epitélio, fibroblasto ou macrófago."},{"id":"p108-05","examId":"p108","number":5,"stem":"Do ponto de vista didático os componentes biológicos da agressão cirúrgica são divididos em três categorias: primeiros , secundários e associados. Tendo em vista os componentes secundários os dois principais órgãos que mais tem prejudicadas sua funções são :","options":{"A":"Rins e pulmões","B":"Supra-renal e mesencéfalo","C":"Vesícula biliar e pâncreas","D":"Tireoide e paratireoide"},"answer":"A","explanation":"Gabarito: rins e pulmões — são os que mais sofrem com as repercussões endócrinas e volêmicas da resposta ao trauma."},{"id":"p108-06","examId":"p108","number":6,"stem":"J.P.P, sexo masculino, 70 anos, portador de Diabetes Mellitus em uso de metformina, deu entrada no pronto socorro do HUV, apresentando lesão corto contusa em punho direito de aproximadamente 6cm com sangramento ativo da artéria radial associado a taquicardia e palidez cutânea. Aplicando o conhecimento sobre nomenclatura cirúrgica e tempos fundamentais da cirurgia, assinale a alternativa correta:","options":{"A":"Inicialmente a hemostasia temporária e cruenta poderia ser realizada com a compressão direta no ferimento, na topografia da artéria radial com compressas estéreis.","B":"Inicialmente a hemostasia temporária e cruenta poderia ser realizada com garroteamento do braço direito, na topografia da artéria braquial.","C":"A hemostasia definitiva e preventiva poderia realizada com angiotripsia da artéria radia, e depois ser realizada síntese da pele com nylon.","D":"A hemostasia temporária e corretiva poderia ser realizada com ligadura com fio de algodão ou linho 2-0 da artéria radial, e posteriomente realizado dermorrafia."},"answer":"A","explanation":"Compressão direta no ponto que sangra é hemostasia temporária e cruenta. Garrote é temporário, mas incruento. Ligadura e angiotripsia são definitivas e corretivas, não preventivas."},{"id":"p108-07","examId":"p108","number":7,"stem":"J.C.D., sexo masculino, 8 anos, morador da zona rural, procurou juntamente com seus pais o ambulatório do HUV, apresentando dificuldade de expor adequadamente a glande do pênis devido ao excesso de pele que cobre a região (prepúcio). E segundo informações dos familiares, foi realizado previamente tratamento clínico com uso de pomadas a base de corticóides e exercícios de retração do prepúcio, porém sem sucesso. Qual o nome do procedimento cirúrgico ideal para tratamento definitivo neste caso:","options":{"A":"Parafimose","B":"Postectomia","C":"Orquiectomia","D":"Ooforectomia"},"answer":"B","explanation":"Postectomia (circuncisão) remove o prepúcio. Parafimose é a complicação, não a cirurgia. Orquiectomia retira testículo; ooforectomia retira ovário."},{"id":"p108-08","examId":"p108","number":8,"stem":"Diante de um quadro de um paciente politraumatizado por acidente automobilístico, com fratura exposta de fêmur, sangramento importante e edema do membro fraturado. Paciente se encontra agitado e confuso, taquicárdico, taquipneico, ao aferir sua pressão, apresentava PA=70 x 40 mmHg. Qual resposta endócrina (hormonal) está ocorrendo para correção desse quadro de instabilidade hemodinâmica?","options":{"A":"Aumento do glucagon e GH.","B":"Elevação dos hormônios androgênicos e catecolaminas.","C":"Diminuição da insulina, aumento aldosterona e da testosterona.","D":"Aumento do hormônio antidiurético, catecolaminas e aldosterona."},"answer":"D","explanation":"ADH, catecolaminas e aldosterona sustentam a volemia: vasoconstrição, taquicardia, queda da diurese e retenção de sódio e água."},{"id":"p108-09","examId":"p108","number":9,"stem":"Paciente portador de hérnia inguinal direita, foi avaliado no ambulatório de cirurgia e realizado todo o pré operatório. Hoje o mesmo foi internado e será submetido à cirurgia eletiva. Realizado todo o preparo do mesmo, sendo encaminhado ao centro cirúrgico, onde o cirurgião o aguarda para realização do procedimento. Em relação ao ambiente cirúrgico, a partir de qual momento é obrigatório o uso de avental estéril pelo cirurgião?","options":{"A":"No momento do inicio da cirurgia","B":"Na condução do paciente a sala de recuperação","C":"A partir do vestiário","D":"Na entrada do bloco cirúrgico"},"answer":"A","explanation":"No vestiário trocam-se a roupa, gorro, máscara e propé. O avental estéril entra na paramentação, no início do ato cirúrgico — não na porta do bloco nem na recuperação."},{"id":"p108-10","examId":"p108","number":10,"stem":"Do ponto de vista da agressão cirúrgica, o tempo cirúrgico diretamente ligado aos componentes primários da resposta ao trauma é:","options":{"A":"Contração","B":"Diérese","C":"Síntese","D":"Hemostasia"},"answer":"B","explanation":"A diérese — a ação direta de cortar e separar tecidos — corresponde aos componentes primários da agressão. Não existe tempo cirúrgico chamado contração."},{"id":"p108-11","examId":"p108","number":11,"stem":"Conhecer as fases de cura de uma ferida e seus componentes nos permite determinar se a mesma esta evoluindo de maneira satisfatória. Assim, ao analisarmos a biópsia de uma ferida com prevalência de fibroblastos e celular endoteliais podemos dizer que a mesma se encontra na seguinte fase de cicatrização:","options":{"A":"Proliferativa","B":"Maturação","C":"Inflamatória","D":"Epitelização"},"answer":"A","explanation":"Fibroblasto (matriz) e célula endotelial (angiogênese) predominam na fase proliferativa. Inflamação é de polimorfonucleares; maturação é de colágeno organizado."},{"id":"p108-12","examId":"p108","number":12,"stem":"Sobre cicatrização de feridas é CORRETO afirmar:","options":{"A":"Na cicatrização por primeira intenção a ferida tem suas bordas aproximadas (suturadas primariamente).","B":"Na cicatrização por segunda intenção ocorre uma limpeza profunda, deiscência, e ressutura ou enxerto para restabelecer as condições de cicatrização.","C":"Em feridas contaminadas devemos preferir os fios multifilamentares.","D":"Na cicatrização por terceira intenção as bordas da ferida não estão aproximadas e existe infecção, ocorre nas grandes perdas teciduais."},"answer":"A","explanation":"Primeira intenção = bordas aproximadas. Segunda = deixa aberta para granulação. Terceira = fecha tardiamente depois de controlar a contaminação. Em ferida contaminada prefere-se monofilamento."},{"id":"p108-13","examId":"p108","number":13,"stem":"A utilização de lidocaína com adrenalina é contraindicada em qual das regiões anatômicas?","options":{"A":"Ombro.","B":"Couro cabeludo.","C":"Mama.","D":"Pododáctilo."},"answer":"D","explanation":"Vasoconstritor em extremidade terminal (dedo, pênis, nariz) pode causar isquemia. Em couro cabeludo, ombro e mama ele é útil para reduzir sangramento e dose."},{"id":"p108-14","examId":"p108","number":14,"stem":"No preparo do paciente para cirurgia , assinale o procedimento correto em relação a antissepsia e assepsia:","options":{"A":"A roupa do corpo será trocada apenas na sala cirúrgica para evitar translocação bacteriana","B":"Orienta-se o paciente ter realizado a tricotomia em casa antes de internar","C":"Recomenda-se a troca de roupa de cama do paciente antes de adentrar o centro cirúrgico","D":"Idealmente o banho no paciente será dado 10 min antes de ir ao centro cirúrgico"},"answer":"C","explanation":"Gabarito: trocar a roupa de cama antes de adentrar o centro cirúrgico. Tricotomia em casa e banho de última hora não são o preparo recomendado nesta prova."},{"id":"p108-15","examId":"p108","number":15,"stem":"J.A.B.,sexo feminino, 54 anos é submetida à retirada cirúrgica de uma lesão a esclarecer em região pré-esternal . A operação transcorre sem intercorrências e o fechamento da pele é realizado em condições adequadas. Não há tensão sobre as bordas da incisão. A evolução é favorável, porém ao redor do terceiro mês de pós-operatório a paciente refere prurido local e que houve piora da hiperemia. Aos 6 meses de pós-operatório a cicatriz é elevada, endurecida, e os sintomas se exacerbam. A cicatriz ultrapassa os limites originais da lesão. Acerca desta descrição clínica pode-se afirmar que:a) O diagnóstico é de cicatriz hipertrófica, que é mais comum em orientais. O tratamento com laser é o mais indicado.b) O diagnóstico mais provável é de queloide. Corrobora para o diagnóstico a localização anatômica, evolução clínica e ausência de tensão ao final do procedimento.c) O diagnóstico provável é de queloide. O tratamento com laser e infiltração de corticoide deve ser instituído imediatamente. A chance de recorrência é mínima se a ressecção for realizada isolada de outros tratamentos associados.d) O diagnóstico provável é de cicatriz hipertrófica, uma vez que a hiperemia observada aos 3 meses não é normal e aos 6 meses o aumento de volume da cicatriz é patognomônico.","options":{"A":"O diagnóstico é de cicatriz hipertrófica, que é mais comum em orientais. O tratamento com laser é o mais indicado.","B":"O diagnóstico provável é de queloide. O tratamento com laser e infiltração de corticoide deve ser instituído imediatamente. A chance de recorrência é mínima se a ressecção for realizada isolada de outros tratamentos associados.","C":"O diagnóstico provável é de cicatriz hipertrófica, uma vez que a hiperemia observada aos 3 meses não é normal e aos 6 meses o aumento de volume da cicatriz é patognomônico.","D":"O diagnóstico mais provável é de queloide. Corrobora para o diagnóstico a localização anatômica, evolução clínica e ausência de tensão ao final do procedimento."},"answer":"D","explanation":"Ultrapassar o limite original, surgir meses depois, em região pré-esternal e sem tensão na sutura, fecha o diagnóstico de queloide. Ressecção isolada recidiva muito."},{"id":"p108-16","examId":"p108","number":16,"stem":"Qual dos fios cirúrgicos abaixo tem as seguintes propriedades: origem sintética, configuração monofilamentar e ser inabsorvível?","options":{"A":"Polipropileno.","B":"Algodão com poliéster.","C":"Seda.","D":"Poliglactilina."},"answer":"A","explanation":"Polipropileno (Prolene) é sintético, monofilamento e inabsorvível. Seda é natural; poliglactina é absorvível e multifilamentar; algodão-poliéster é misto e trançado."},{"id":"p108-17","examId":"p108","number":17,"stem":"Paciente apresenta úlcera crônica em MI direito. Essa úlcera se localiza na região interna da perna, não é dolorosa, apresenta tecido de granulação, não há infecção associada, o membro é quente e apresenta pigmentação escurecida, em forma de bota. Com essas informações, dentre as afirmativas abaixo, qual está correta?","options":{"A":"Trata-se de úlcera crônica diabética, e essa lesão é causada por baixa imunidade devido à falha no funcionamento dos macrófagos.","B":"É uma úlcera de pressão. Ocasionada por isquemia microvascular por pressão contínua.","C":"Úlcera característica de insuficiência arterial causada pelo tabagismo que leva a inflamação e obstrução das arteriais.","D":"Sugestivo de úlcera venosa, causada por aumento da pressão venosa que leva a formação da lipodermatosclerose, por extravasamento de hemoglobina para subcutâneo."},"answer":"D","explanation":"Face medial da perna, indolor, quente, com pigmentação em bota, é úlcera venosa. A arterial é dolorosa e fria; pressão ocorre em proeminência óssea."},{"id":"p108-18","examId":"p108","number":18,"stem":"Mulher, 32 anos, dá entrada em pronto socorro com história de queda da própria altura na rua, com ferimento corto contuso extenso em antebraço, não atingindo a superfície articular, com sinais de sangramento. A melhor sutura a ser realizada e o fio mais adequado a ser utilizado são respectivamente:","options":{"A":"Chuleio simples, mononylon.","B":"Pontos simples, mononylon.","C":"Sutura intradérmica, catgut.","D":"Pontos simples, mononylon."},"answer":"D","explanation":"No antebraço, sem grande tensão articular, ponto simples com mononylon é a combinação indicada. Chuleio isquemiza; intradérmica com categute não é a escolha; Donati reserva-se a áreas de muita tensão (joelho, cotovelo). Na prova impressa as letras B e D aparecem repetidas; aqui as opções seguem a justificativa do gabarito, cuja resposta é pontos simples com mononylon."},{"id":"p108-19","examId":"p108","number":19,"stem":"Sabemos que quando um indivíduo é exposto a um trauma severo seu organismo apresenta uma serie de respostas endócrinas, metabólicas e imunológicas- REMIT, como hemostasia, estabilização pressão arterial, combate a infecção, cicatrização, manutenção da temperatura, entre outros. Para manter esse hiper metabolismo é necessária muita energia, porém, os reservatórios de carboidratos duram pouco tempo. Sendo assim, de que forma a energia é produzida nesses momentos de maior consumo, mas com baixas reservas energéticas?","options":{"A":"Através da glicólise (quebra glicose) e glicogenólise (quebra do glicogênio) para produção de energia, estimulado pelo glucagon, cortisol e GH.","B":"Por glicólise e glicogenólise, estimulados pela aldosterona, hormônio antidiurético e endorfinas.","C":"Pela gliconeogênese,onde ocorre a lipólise (quebra gorduras) e proteólise (quebra proteínas) para produção de energia, estimulados pela aldosterona, hormônio antidiurético e endorfinas.","D":"O aumento energético ocorre por gliconeogênese da lipólise e proteólise, estimulados pelo glucagon, cortisol e GH."},"answer":"D","explanation":"Acabado o glicogênio, a energia vem da gliconeogênese (lipólise e proteólise), estimulada sobretudo por glucagon, cortisol e GH — não por aldosterona ou ADH."},{"id":"p108-20","examId":"p108","number":20,"stem":"J.C.R., 34 anos, sexo masculino, sem comorbidades, no 7º dia de pós-operatório de apendicectomia por apendicite fase I (não complicada), ainda com pontos cirúrgicos, apresenta sinais flogísticos e saída de secreção purulenta pela incisão abdominal. Durante a anamnese e exame físico não foi observado manifestações sistêmicas ou outras queixas. A conduta mais apropriada para o caso é:","options":{"A":"Reduzir o distanciamento entre a sutura da pele com novos pontos, usando fio monofilamentar.","B":"Abertura da ferida cirúrgica para drenagem e limpeza da ferida operatória.","C":"Curativo 2 vezes ao dia, enfaixando e comprimindo todo o abdome do paciente.","D":"Antibioticoterapia de largo espectro isoladamente"},"answer":"B","explanation":"ISC superficial sem toxemia: abrir, drenar e limpar. Antibiótico isolado, compressão abdominal e novos pontos não tratam o pus retido."},{"id":"p109-01","examId":"p109","number":1,"stem":"O hormônio antidiurético (ADH) está elevado até o quarto ou quinto dia de pós-operatório. Caso grandes volumes de líquido sejam ofertados nesse período, a secreção de ADH é chamada de “inadequada” e pode acarretar:","options":{"A":"Hipocalemia e hipotonicidade","B":"Hipocalemia e hipertonicidade","C":"Hiponatremia e hipotonicidade","D":"Hiponatremia e hipertonicidade"},"answer":"C","explanation":"O ADH retém água e dilui o sódio: hiponatremia dilucional e hipotonicidade."},{"id":"p109-02","examId":"p109","number":2,"stem":"Paciente, sexo masculino, 28 anos, deu entrado no pronto socorro do HUV pelo SAMU vítima de acidente automobilístico grave com dificuldade de ventilação espontânea, e ao exame físico verifica-se a incapacidade de intubação orotraqueal, por traumatismo facial grave, com hemorragia traqueobrônquica persistente e distorção anatômica importante, indicado um acesso rápido das vias áreas, através da perfuração da membrana cricotireoidea, por um cateter agulhado de grosso calibre (jelco), comunicando a luz da via aérea a um sistema de ventilação a jato com fornecimento de O2. A este procedimento damos o nome de:","options":{"A":"Traqueotomia por punção de urgência","B":"Traqueostomia de urgência","C":"Cricotireoidostomia por punção","D":"Cricotireoidotomia cirúrgica de urgência"},"answer":"C","explanation":"Punção da membrana cricotireóidea que comunica a via aérea ao exterior usa o sufixo -stomia: cricotireoidostomia por punção. Não é uma traqueostomia."},{"id":"p109-03","examId":"p109","number":3,"stem":"Correlacione: 1. abertura direta do estômago para o exterior; 2. modificação do estômago para obesidade; 3. retirada de parte ou de todo o estômago; 4. fixação do estômago à parede; 5. incisão na parede do estômago. Termos: A gastrosquise, B gastrostomia, C gastrotomia, D gastropexia, E gastroplastia, F gastrectomia, G gastroparesia.","options":{"A":"1-B; 2-E; 3-F; 4-G; 5-A","B":"1-B; 2-E; 3-F; 4-D; 5-C","C":"1-C; 2-F; 3-C; 4-D; 5-E","D":"1-A; 2-F; 3-C; 4-G; 5-B"},"answer":"B","explanation":"Gastrostomia (1-B), gastroplastia (2-E), gastrectomia (3-F), gastropexia (4-D) e gastrotomia (5-C). Gastrosquise e gastroparesia não são esses procedimentos."},{"id":"p109-04","examId":"p109","number":4,"stem":"Paciente estava trabalhando na lavoura e sofreu corte em membro superior devido a acidente com foice. Chega ao pronto socorro após 3 horas do acidente. Ao ser examinado pelo plantonista ele constata que o corte é recente ainda com sangramento em atividade e edema local. Evidentemente trata-se da fase inflamatória da cicatrização. Marque a alternativa com as principais células dessa fase?","options":{"A":"Fibroblastos e células epiteliais.","B":"Plaquetas, macrófagos, mastócitos e neutrófilos.","C":"Matriz extra celular e colágeno.","D":"Células epiteliais e células endoteliais."},"answer":"B","explanation":"Na inflamação atuam plaquetas (hemostasia), neutrófilos, macrófagos e mastócitos. Fibroblasto e endotélio dominam a proliferação."},{"id":"p109-05","examId":"p109","number":5,"stem":"O ato operatório é organizado quanto aos tempos fundamentais da cirurgia. Referente a estes princípios, especificamente ao tempo denominado “diérese”, podemos afirmar que:","options":{"A":"Incisão transversal, incisão simples, combinada, longitudinais, oblíquas, craniocaudais, dorsoventrais, eletrocoagulação, bisturi de argônio, divulsão romba e descolamento são subdivisões da diérese física ou não cruenta.","B":"Punção, incisão, secção, divulsão, curetagem, dilatação, descolamento, desbridamento, escarificação e fratura são subdivisões da diérese mecânica ou cruenta.","C":"Incisão cirúrgica, bisturi ultrassônico, ligadura por laçada, eletrocoagulação, bisturi elétrico monopolar, divulsão romba e descolamento são subdivisões da diérese física ou não cruenta.","D":"Incisão simples, combinada, longitudinais, oblíquas, craniocaudais, dorsoventrais, eletrocoagulação, bisturi elétrico bipolar, divulsão romba e descolamento são subdivisões da diérese mecânica ou cruenta."},"answer":"B","explanation":"Diérese mecânica (cruenta) usa instrumento que separa ou corta: punção, incisão, secção, divulsão, curetagem, dilatação, descolamento, desbridamento, escarificação e fratura. Energia (eletrocautério, ultrassom) é diérese física."},{"id":"p109-06","examId":"p109","number":6,"stem":"As cicatrizes hipertróficas e queloides são cicatrizes proliferativas caracterizadas por deposição excessiva de colágeno. Em relação a este tema, analise as assertivas abaixo. I) Queloides crescem além das margens da ferida original e raramente regridem com o tempo, predominando em indivíduos de pele escura. II) Infecção, isquemia, diabetes melito, radiação ionizante, desnutrição, idade avançada e deficiências vitamínicas e de minerais são fatores que podem inibir a cicatrização de feridas. III) As cicatrizes hipertróficas são cicatrizes elevadas que permanecem nos limites da ferida original e, muitas vezes, regridem espontaneamente. IV) Inflamação prolongada e reepitelização insuficiente, como feridas por queimaduras, podem promover cicatrização hipertrófica. Estão corretas as assertivas:","options":{"A":"Todas estão corretas.","B":"Apenas as I e IV.","C":"Apenas a II e III.","D":"Apenas a I, II e III."},"answer":"A","explanation":"As quatro assertivas estão corretas segundo o gabarito: definição de queloide e de hipertrófica, fatores que inibem a cura e o papel da inflamação prolongada."},{"id":"p109-07","examId":"p109","number":7,"stem":"Paciente masculino, 70 anos, tabagista de longa data, apresenta úlcera em membro inferior direito com início aproximado há 6 meses. Essa úlcera,é muito dolorosa, piora com elevação do membro, a pele ao redor é fria. Com essas informações, dentre as afirmativas abaixo, qual o provável diagnóstico dessa úlcera?","options":{"A":"É uma úlcera de pressão.","B":"Sugestivo de úlcera venosa.","C":"Úlcera por insuficiência arterial.","D":"Trata-se de úlcera crônica diabética."},"answer":"C","explanation":"Dor intensa que piora ao elevar o membro e pele fria, em tabagista, caracterizam úlcera arterial. A venosa piora no fim do dia e melhora com a elevação."},{"id":"p109-08","examId":"p109","number":8,"stem":"As técnicas de assepsia, antissepsia e esterilização são fundamentais para evitar infecção em qualquer procedimento cirúrgico. Das alternativas abaixo qual podemos definir como um procedimento de antissepsia?","options":{"A":"Colocação de campos cirúrgicos.","B":"Autoclavar material metálico.","C":"Escovação das mãos com antissépticos.","D":"Colocação de luvas."},"answer":"C","explanation":"Antissepsia é o uso de antisséptico em tecido vivo, como a escovação das mãos. Campo, luva e autoclave são assepsia ou esterilização."},{"id":"p109-09","examId":"p109","number":9,"stem":"Paciente de 28 anos, sexo masculino, sem comorbidades, foi submetido a uma apendicectomia aberta devido a apendicite aguda não complicada. No sétimo dia de pós-operatório, ele desenvolve dor abdominal crescente na ferida operatória associado à drenagem de secreção purulenta sem odor fétido. O exame físico revela eritema e edema ao redor da incisão, e a avaliação laboratorial apresenta os leucócitos de 9.800 leucócitos por microlitro. Baseado no caso clínico responda o tratamento correto:","options":{"A":"Reabordagem cirúrgica.","B":"Antibioticoterapia oral com cefalexina de 1ª geração por 07 dias.","C":"Drenagem ampla, limpeza e cuidados locais da ferida operatória.","D":"Antibioticoterapia parenteral e revisão cirúrgica."},"answer":"C","explanation":"ISC superficial, sem toxemia e com leucograma normal: abrir, drenar e cuidar localmente. Antibiótico e reoperação ficam para infecção profunda ou sistêmica."},{"id":"p109-10","examId":"p109","number":10,"stem":"Em cirurgia, as classificações de feridas operatórias são importantes para determinar o risco de infecção e orientar o uso de antibióticos. Uma \"cirurgia limpa\" é aquela em que não há uma contaminação significativa do campo cirúrgico e o risco de infecção é baixo. Dentre as seguintes opções de cirurgias, qual é considerada uma cirurgia limpa?","options":{"A":"Laringectomia","B":"RTU de próstata","C":"Tireoidectomia total","D":"Traqueoplastia"},"answer":"C","explanation":"Tireoidectomia total não entra em trato contaminado: é cirurgia limpa. Via aérea, urinária endoscópica e traqueia não são feridas limpas."},{"id":"p109-11","examId":"p109","number":11,"stem":"Jovem 14 anos apresentando quadro de torção testicular a direita com isquemia do testiculo citado. O cirurgião procede com cirurgia de urgência realizando retirada do testiculo direito e fixação do testiculo esquerdo. A nomenclatura correta do procedimento realizado é:","options":{"A":"Orquidostomia e orquidotomia","B":"Testiculotomia e testiculodese","C":"Testiculocentese e testículoanastomose","D":"Orquiectomia e orquidopexia"},"answer":"D","explanation":"Retirada do testículo = orquiectomia. Fixação do contralateral = orquidopexia."},{"id":"p109-12","examId":"p109","number":12,"stem":"Aluno do internato da Universidade Severino Sombra ao adentrar no centro cirúrgico precisou passar pelo vestiário para retirar e guardar os adornos (brincos, relógios, etc), roupa usual e usar equipamentos de proteção individual (EPI’s). Qual o nome da zona do centro cirúrgco informada acima, e quais materiais (EPI’s) são usador nesta etapa:","options":{"A":"Zona asséptica - pijama cirúrgico estéril, gorro, óculos e máscara \"propé\".","B":"Zona de proteção - pijama cirúrgico, gorro, máscara e \"propé\".","C":"Zona de limpa - pijama cirúrgico estéril, gorro, óculos, máscara e \"propé\".","D":"Zona limpa - capote cirúrgico, gorro, máscara e \"propé\"."},"answer":"B","explanation":"Vestiário = zona de proteção. Ali se vestem pijama, gorro, máscara e propé. O capote estéril entra só na hora de paramentar."},{"id":"p109-13","examId":"p109","number":13,"stem":"A síntese cirúrgica, que consiste na aproximação das bordas dos tecidos seccionados ou ressecados, visa, pela manutenção da contiguidade dos tecidos, facilitar as fases iniciais da cicatrização. O fechamento da parede abdominal após uma apendicectomia por apendicite purulenta deve ser feita em planos, e as mais adequadas indicações de fios e suturas para o fechamento da pele são:","options":{"A":"Fio não absorvível, tipo seda, chuleio simples.","B":"Fio absorvível, tipo catgut, pontos em U.","C":"Fio absorvível, tipo nylon, pontos em X.","D":"Fio não absorvível, tipo nylon, pontos simples."},"answer":"D","explanation":"Nylon é inabsorvível (não absorvível) e o ponto simples é a síntese clássica da pele. Nylon não é absorvível; seda em chuleio e categute não são a escolha da banca."},{"id":"p109-14","examId":"p109","number":14,"stem":"Mulher de 20 anos sofreu lesão traumática cortante de 10 cm no couro cabeludo sem perda de substância, com sangramento abundante, edema local e uma certa tensão para aproximação dos bordos. O material e o tipo de sutura mais apropriados são, correta e respectivamente:","options":{"A":"Fio de nylon monofilamentar 2.0; donati.","B":"Fio de nylon monofilamentar 5.0; donati.","C":"Fio de nylon monofilamentar 5.0; intradérmica.","D":"Fio de nylon monofilamentar 2.0; intradérmica."},"answer":"A","explanation":"Couro cabeludo com tensão e sangramento pede fio mais calibroso (2-0) e ponto de Donati, que aproxima em dois planos e ajuda na hemostasia. 5-0 é fino demais; intradérmica não segura essa tensão nem estanca o sangramento."},{"id":"p109-15","examId":"p109","number":15,"stem":"Correlacione e assinale a sequência correta. Coluna 1: 1 fase inflamatória; 2 fase proliferativa; 3 fase de maturação; 4 úlcera venosa; 5 úlcera arterial. Coluna 2, na ordem impressa da prova: (f) migração de polimorfonucleares; (e) migração de fibroblastos e células endoteliais; (c) predomínio de colágeno tipo I; (b) dor que piora ao final do dia; (a) dor inclusive em repouso. As alternativas são sequências numéricas.","options":{"A":"3-2-1-4-5","B":"1-2-3-4-5","C":"4-5-2-1-3","D":"5-4-3-2-1"},"answer":"D","explanation":"O gabarito oficial marca D (5-4-3-2-1). Para estudar a fisiologia, guarde os pares: inflamação → polimorfonucleares; proliferação → fibroblastos e endotélio; maturação → colágeno I; úlcera venosa → dor no fim do dia; úlcera arterial → dor também em repouso."},{"id":"p109-16","examId":"p109","number":16,"stem":"Quando o organismo reage a uma agressão ele inicia uma série de eventos endócrinos, metabólicos e imunológicas. A maior parte da resposta endócrina vem do eixo hipotálamo hipófise-supra renal (H-H-SR). Porém, um dos hormônios não é estimulado por esse eixo mas sim pelo sistema nervoso simpático, e ele é produzido nas suprarrenais, e sua função é a manutenção da pressão sistêmica através de taquicardia e vasoconstricção. Qual dos hormônios abaixo o texto se refere?","options":{"A":"Catecolaminas.","B":"Cortisol","C":"Aldosterona.","D":"Hormônios androgênicos."},"answer":"A","explanation":"Adrenalina e noradrenalina (catecolaminas) vêm da medula adrenal sob comando simpático e causam taquicardia e vasoconstrição. Cortisol e aldosterona dependem do eixo HHS."},{"id":"p109-17","examId":"p109","number":17,"stem":"Infecções do sítio cirúrgicos constituem complicação frequente na prática cirúrgica e acabam aumentando a morbimortalidade do paciente tratado cirurgicamente. Em relação a este tema, analise as assertivas abaixo. I) A ocorrência de infecção de sítio cirúrgico aumenta o custo global do tratamento, porém não predispõe a formação de hérnias incisionais. II) A prevenção da infecção de sítio cirúrgico pode ser realizada com manipulação e hemostasia cuidadosa dos tecidos e preparação da pele com soluções antissépticas adequadas. III) A administração de antibióticos por longos períodos após o procedimento cirúrgico diminui a incidência de infecção de sítio cirúrgico e possui papel protetor relativo. IV) O tratamento das infecções de sítio cirúrgico superficiais envolve a abertura da ferida, remoção de todo o tecido não viável e irrigação da ferida com solução salina. Estão corretas as assertivas:","options":{"A":"Apenas as I e III.","B":"Apenas as II e IV.","C":"Todas estão corretas.","D":"Apenas as I, II e IV."},"answer":"B","explanation":"II e IV são verdadeiras. ISC favorece hérnia incisional (I é falsa) e antibiótico prolongado não reduz ISC — só seleciona resistência (III é falsa)."},{"id":"p109-18","examId":"p109","number":18,"stem":"As infecções cirúrgicas permanecem nos dias atuais como um dos principais riscos à segurança dos pacientes nos serviços de saúde no Brasil. E sempre foi um desafio para médicos e pacientes ao longo da história. Considerando a importância do tema, avalie os itens abaixo e marque a alternativa correta: I) Infecção do sítio cirúrgico pode acontecer até 1 ano após o ato cirúrgico em que se tenha implantado material protético. II) Se os pelos tiverem que ser removidos, deve-se fazer a tricotomia com lâmina de bisturi ou Gillette imediatamente antes da incisão cirúrgica. III) A infecção urinária é a infecção mais frequente em pacientes cirúrgicos. IV) O uso de propés é obrigatório em todo centro cirúrgico para o controle do risco de infecção de sítio cirúrgico. V) A fasciíte pós-operatória é exemplo de infecção do sítio cirúrgico profundo. Alternativas:","options":{"A":"Apenas os itens I, e V são verdadeiros.","B":"Apenas os itens II, III, e V são verdadeiros.","C":"Todos os itens são verdadeiros.","D":"Apenas os itens II, IV, e V são verdadeiros."},"answer":"A","explanation":"I e V são verdadeiros. Tricotomia com lâmina aumenta microlesões; ITU não é a infecção mais frequente nesse enunciado; propé não é medida obrigatória universal de controle de ISC."},{"id":"p109-19","examId":"p109","number":19,"stem":"O processo de cicatrização de feridas pode eventualmente ocorrer de forma inadequada, levando a resultados não satisfatórios. Em relação aos queloides e às cicatrizes, avalie os itens abaixo e marque a alternativa correta: I) A primeira opção terapêutica é a ressecção da lesão queloideana, para evitar o aumento da lesão. II) Os queloides nunca possuem aparecimento espontâneo, surgindo principalmente em traumas. III) As cicatrizes hipertróficas são cicatrizes elevadas dentro dos limites da ferida original e frequentemente regridem espontaneamente. IV) Não existe risco de suscetibilidade genética nem hereditariedade de cicatrizes queloides. V) Cicatrizes hipertróficas têm forma tumoral, que ultrapassam os limites das incisões ou traumas que o originaram.","options":{"A":"Apenas os itens II e III são verdadeiros.","B":"Apenas os itens II, IV, e V são verdadeiros.","C":"Apenas o item III é verdadeiro.","D":"Apenas os itens I, III e IV são verdadeiros."},"answer":"C","explanation":"Só III é verdadeiro. Queloide não se opera como primeira escolha, pode surgir sem trauma, tem base genética e quem ultrapassa a ferida é o queloide, não a hipertrófica."},{"id":"p109-20","examId":"p109","number":20,"stem":"Paciente politraumatizado em acidente de moto ocorrido há 7 dias, se encontra grave na UTI, em coma. O organismo se encontra em processo de restabelecer a homeostase através da resposta endócrino metabólica e imunológica- REMIT. Nessa fase de que forma é gerada energia para sustentar o hipermetabolismo necessário para corrigir os danos?","options":{"A":"Pela glicogenólise, degradando glicogênio em glicose.","B":"Mantendo o balanço nitrogenado positivo.","C":"Pela gliconeogênese, através de lipólise e proteólise.","D":"Através da glicólise, quebrando a glicose para gerar ATP."},"answer":"C","explanation":"No hipermetabolismo tardio as reservas de glicogênio já acabaram. A energia vem da gliconeogênese alimentada por lipólise e proteólise. O gabarito impresso abre com a letra “a”, mas o texto citado é exatamente esta alternativa (gliconeogênese)."},{"id":"p110-01","examId":"p110","number":1,"stem":"Durante o trauma cirúrgico, o corpo desencadeia uma série de respostas hormonais e metabólicas importantes para a recuperação e adaptação ao estresse. Assinale a alternativa que descreve corretamente as principais alterações hormonais e metabólicas observadas:","options":{"A":"Durante o trauma cirúrgico, há aumento da produção de insulina devido à maior oferta glicêmica, enquanto os hormônios catabólicos permanecem inalterados. A resposta metabólica consiste na estabilização dos níveis glicêmicos e aumento da síntese de proteínas musculares.","B":"O trauma cirúrgico provoca aumento dos hormônios catabólicos, como cortisol, adrenalina e glucagon, levando à hiperglicemia e aumento da degradação proteica. Além disso, ocorre ativação do eixo hipotálamo-hipófise-adrenal e aumento da liberação de hormônios contrarreguladores, enquanto a produção de insulina é prejudicada pela resistência periférica.","C":"O trauma cirúrgico resulta predominantemente na diminuição dos níveis de cortisol e adrenalina, promovendo hipoglicemia e aumento da síntese proteica. A resposta metabólica é caracterizada pela ativação de hormônios anabólicos e aumento da liberação de insulina.","D":"O corpo responde ao trauma cirúrgico diminuindo a produção de adrenalina e cortisol, com predomínio da atividade anabólica e redução da degradação proteica. A hipoglicemia é comum devido ao aumento da utilização de glicose pelos tecidos."},"answer":"B","explanation":"No trauma sobem cortisol, catecolaminas e glucagon: hiperglicemia, proteólise, lipólise e resistência à insulina. Não há predomínio anabólico."},{"id":"p110-02","examId":"p110","number":2,"stem":"Um paciente de 54 anos, sem comorbidades, é submetido a uma colecistectomia laparoscópica eletiva por colelitíase sintomática, sem colecistite aguda. O procedimento ocorre sem intercorrências, sem contaminação evidente do campo cirúrgico e sem necessidade de drenagem. Com base na classificação das feridas cirúrgicas quanto à contaminação, assinale a alternativa correta:","options":{"A":"A ferida operatória do paciente deve ser classificada como contaminada, pois envolve a manipulação do trato gastrointestinal, independentemente da presença de inflamação ou extravasamento de conteúdo biliar.","B":"A ferida cirúrgica deve ser considerada infectada, pois qualquer cirurgia envolvendo órgãos cavitários do trato digestivo apresenta risco elevado de infecção, independentemente da técnica empregada.","C":"O procedimento se enquadra na classificação de potencialmente contaminado (limpo-contaminado), pois houve abertura controlada do trato biliar, sem contaminação macroscópica do campo cirúrgico.","D":"A ferida cirúrgica deve ser classificada como limpa, pois a cirurgia foi realizada sem violar os tratos digestivo ou respiratório, sem sinais de infecção e sem contaminação evidente."},"answer":"C","explanation":"Abertura controlada da via biliar, sem inflamação aguda e sem extravasamento, classifica a ferida como limpa-contaminada (potencialmente contaminada)."},{"id":"p110-03","examId":"p110","number":3,"stem":"Paciente de 18 anos, sofre queda de bicicleta com um trauma corto-contuso profundo na testa, levando-o a pronto-socorro. Ao realizar o atendimento inicial, descobre-se ferimento delicado a presença sangramento ativo e muito material na ferida. Para garantir uma cicatrização adequada e minimizar o risco uma sequela, é correto os procedimentos cirúrgicos e para uma opção abaixo representa a sequência correta de cuidados cirúrgicos necessários com essa ferida aguda?","options":{"A":"Irrigação com SF, sutura, desbridamento, anestesia local, hemostasia e curativo.","B":"Sutura, irrigação com SF, desbridamento, anestesia local, hemostasia e curativo.","C":"Desbridamento, irrigação com SF, hemostasia, curativo, sutura e anestesiam local.","D":"Anestesia local, irrigação com SF, hemostasia, desbridamento, sutura e curativo."},"answer":"D","explanation":"Primeiro anestesia, depois irrigação copiosa com soro, controle do sangramento, desbridamento do tecido inviável, sutura e curativo."},{"id":"p110-04","examId":"p110","number":4,"stem":"Uma paciente de 35anos, diabética, hipertensa e tabagista, chega ao pronto-socorro após sofrer um acidente de moto apresentando ferimento grave em MI com perda de pele e musculatura. A ferida tem bordos irregulares e bastante contaminada por resíduos de terra e vegetação. O cirurgião realiza limpeza exaustiva e desbridamento no centro cirúrgico, mas não foi possível aproximação dos bordos e optou por deixar a ferida sem sutura até sua cicatrização completa. Com base nos conceitos de cicatrização, qual das alternativas abaixo descreve corretamente o tipo de cicatrização adotado para este paciente?","options":{"A":"Cicatrização por quarta intenção.","B":"Cicatrização por segunda intenção.","C":"Cicatrização por terceira intenção.","D":"Cicatrização por primeira intenção."},"answer":"B","explanation":"Ferida deixada aberta de propósito, fechando por granulação e contração, é segunda intenção. Não existe quarta intenção. Terceira seria suturar mais tarde."},{"id":"p110-05","examId":"p110","number":5,"stem":"Um paciente de 30 anos, foi encontrado desacordado e caído em via pública por ter sofrido trauma abdominal penetrante por faca. Ele chega ao pronto-socorro e logo é encaminhado ao centro cirúrgico para realização de uma laparotomia exploradora, onde é identificado uma perfuração no cólon transverso com extravasamento maciço de conteúdo fecal e secreção purulenta na cavidade peritoneal. Com base na classificação das feridas quanto à contaminação, qual é a melhor conduta em relação ao uso de antibióticos?","options":{"A":"A ferida é classificada como contaminada, sendo indicada antibioticoterapia profilática por 24 horas, sem necessidade de tratamento prolongado.","B":"A ferida é classificada como limpo-contaminada e requer apenas antibiótico profilático, pois não há evidência de infecção ativa.","C":"A ferida é classificada como contaminada e deve receber antibioticoterapia profilática estendida, já que ainda não tem infecção vigente.","D":"A ferida é classificada como infectada, sendo necessário antibiótico terapêutico."},"answer":"D","explanation":"Perfuração de cólon com fezes e pus na cavidade é ferida infectada (suja). O antibiótico é terapêutico, não apenas profilático."},{"id":"p110-06","examId":"p110","number":6,"stem":"Um paciente de 60 anos, tabagista e com histórico de úlcera gástrica perfurada, é submetido a um procedimento cirúrgico para remoção de parte do estômago. Com base na nomenclatura cirúrgica padronizada, qual das opções abaixo descreve corretamente esse procedimento?","options":{"A":"Gastrectomia","B":"Gastrorrafia","C":"Gastroplastia","D":"Gastrostomia"},"answer":"A","explanation":"Retirar parte do estômago é gastrectomia. Rafia seria só suturar; plastia remodela; estomia abre para o exterior."},{"id":"p110-07","examId":"p110","number":7,"stem":"As infecções de sítio cirúrgico (ISC) representam uma das principais causas de morbidade no pós- operatório, influenciadas por uma combinação de fatores inerentes ao paciente, ao procedimento e ao ambiente hospitalar. Sobre os fatores de risco e as estratégias de prevenção da ISC, analise as afirmações abaixo: I. A colonização bacteriana prévia por patógenos multirresistentes, a obesidade e o tabagismo são fatores intrínsecos ao paciente que aumentam o risco de ISC. II. A antibioticoprofilaxia administrada dentro de uma hora antes da incisão cirúrgica é fundamental para reduzir a taxa de ISC, especialmente em cirurgias classificadas como limpas-contaminadas. III. A utilização de clorexidina alcoólica para a antissepsia da pele pré-operatória mostrou ser superior ao uso de povinona-iodo em termos de redução da incidência de ISC. O reuso de dispositivos invasivos, como cateteres e drenos é considerado um fator de proteção contra ISC. IV. Em cirurgias com tempo de duração superior a duas horas, recomenda-se a reaplicação da antibioticoprofilaxia para manter níveis séricos adequados, especialmente em pacientes obesos ou com grandes perdas sanguíneas. Assinale a alternativa correta:","options":{"A":"Somente as afirmações I, II, III e IV estão corretas.","B":"Somente as afirmações I, II e III estão corretas.","C":"Todas as afirmações estão corretas.","D":"Somente as afirmações I, III e IV estão corretas."},"answer":"D","explanation":"Gabarito oficial: D. I e a redose em cirurgia longa (IV) estão corretas, e a banca considera III correta pela superioridade da clorexidina alcoólica. Atenção de estudo: reutilizar dispositivo invasivo não protege — aumenta o risco de ISC."},{"id":"p110-08","examId":"p110","number":8,"stem":"Paciente masculino, 62 anos, com histórico de hipertensão e diabetes mellitus tipo 2, apresenta quadro de apendicite aguda e é submetido a uma intervenção cirúrgica. Durante a cirurgia, é realizada a remoção do apêndice vermiforme, e o procedimento é descrito de acordo com a nomenclatura cirúrgica. Após a recuperação da cirurgia, o paciente também apresenta cálculos renais, sendo indicado um novo procedimento cirúrgico para remoção dos cálculos localizados nos rins. Com base na formação de termos cirúrgicos e no caso apresentado, analise as alternativas e assinale a opção correta:","options":{"A":"O termo nefrectomia refere-se à remoção do cálculo renal, sendo formado por \"nefro-\" (rim) + \"-ectomia\" (remoção).","B":"O procedimento para a remoção de cálculos renais é chamado nefrolitotomia, formado por \"nefro-\" (rim), \"lito-\" (cálculo) e \"-tomia\" (incisão).","C":"O termo apendicostomia seria utilizado para a realização de um orifício no apêndice, sendo formado por \"apêndic-\" (apêndice) + \"-ostomia\" (criação de abertura).","D":"O procedimento realizado para a remoção do apêndice é denominado apendectomia, formado pela raiz \"apendic-\" (apêndice) e sufixo \"-otomia\" (incisão)."},"answer":"B","explanation":"Nefrolitotomia = incisão do rim para retirar o cálculo. Nefrectomia retira o rim. Apendicectomia (não apendicostomia, nem sufixo -otomia) retira o apêndice."},{"id":"p110-09","examId":"p110","number":9,"stem":"J.X.A., masculino de 65 anos, diabético e hipertenso, foi submetido a uma cirurgia de revascularização de membro inferior esquerdo devido a uma insuficiência arterial periférica. No pós-operatório, apresentou uma ferida cirúrgica que evoluiu com sinais de infecção, incluindo hiperemia, edema e exsudato purulento. Diante disso, constatou-se também palidez cutânea e diminuição dos pulsos distais. Durante a anamnese, o paciente relatou tabagismo há mais de 40 anos e uso crônico de corticosteroides devido a uma doença pulmonar obstrutiva crônica (DPOC). Após 15 dias, observou-se atraso na cicatrização e a necessidade de tratamento com antibióticos de amplo espectro. Com base no quadro clínico apresentado, assinale a alternativa que melhor explica os fatores que interferem na cicatrização da ferida desse paciente:","options":{"A":"A idade avançada do paciente e o uso de antibióticos são os únicos fatores que retardam a cicatrização, enquanto o controle glicêmico e o uso de corticosteroides não interferem no processo.","B":"A cicatrização está prejudicada exclusivamente devido ao tabagismo, enquanto a infecção local e o uso de corticosteroides não têm impacto significativo.","C":"O diabetes mellitus é o único fator relevante para o atraso na cicatrização, e o uso de corticosteroides e o tabagismo não influenciam significativamente o processo.","D":"A presença de diabetes mellitus, uso crônico de corticosteroides, tabagismo e infecção local são fatores que prejudicam a cicatrização, assim como a insuficiência arterial, que compromete a perfusão tecidual e o aporte de nutrientes."},"answer":"D","explanation":"Todos esses fatores atrasam a reparação: hiperglicemia, corticoide, tabaco, infecção e má perfusão arterial."},{"id":"p110-10","examId":"p110","number":10,"stem":"Sobre a antissepsia da pele do paciente no preparo pré-operatório, assinale a alternativa correta:","options":{"A":"A clorexidina degermante deve ser utilizada pura, pois apresenta amplo espectro antimicrobiano e efeito residual prolongado, tornando-se uma das principais opções para a antissepsia da pele no pré-operatório.","B":"O iodo povidona tem excelente efeito antisséptico e residual, além de nenhum risco de irritação cutânea, sendo sempre superior à clorexidina em cirurgias limpas.","C":"A antissepsia da pele do paciente deve ser realizada com soluções antissépticas altamente concentradas, pois maiores concentrações sempre resultam em melhor eficácia e menor risco de irritação cutânea.","D":"O álcool 70% é o antisséptico de escolha para a pele do paciente em áreas com grande quantidade de gordura sebácea, pois, além de possuir ação residual prolongada, mantém sua eficácia mesmo na presença de matéria orgânica."},"answer":"A","explanation":"Clorexidina degermante tem amplo espectro e residual longo. Álcool perde efeito com matéria orgânica e tem residual curto; concentração alta não significa menos irritação."},{"id":"p110-11","examId":"p110","number":11,"stem":"O controle de sangramento é um dos tempos fundamentais da cirurgia, essencial para a precisão da técnica operatória e redução de complicações. Sobre as técnicas de hemostasia utilizadas no ambiente cirúrgico, assinale a alternativa correta:","options":{"A":"A hemostasia temporária utiliza exclusivamente agentes químicos para controle de sangramento, enquanto a definitiva é realizada apenas por compressão direta.","B":"A hemostasia preventiva é aplicada após o início do sangramento, enquanto a hemostasia cruenta visa controlar os vasos. A hemostasia cruenta sempre utiliza cauterização elétrica, enquanto a incruenta depende do uso de torniquetes.","C":"A hemostasia temporária consiste em realizar a ligadura definitiva dos vasos sangrantes, enquanto a definitiva inclui apenas o uso de compressão manual. A hemostasia preventiva é aplicada durante o ato cirúrgico, sendo a corretiva e hemostasia como profilaxia. A hemostasia cruenta é realizada por métodos não traumáticos, enquanto a incruenta inclui técnicas invasivas.","D":"A hemostasia temporária é realizada por métodos rápidos e provisórios, como a compressão com gaze ou o uso de torniquete, enquanto a hemostasia definitiva envolve intervenções permanentes, como a ligadura de vasos. A hemostasia preventiva é aplicada antes da lesão, buscando ocluir a área de vasos, enquanto a corretiva ocorre após a identificação do sangramento, como na cauterização de vasos abertos. A hemostasia cruenta atua diretamente no local do sangramento, como a sutura vascular, enquanto a incruenta utiliza métodos indiretos, como a aplicação de drogas hemostáticas."},"answer":"D","explanation":"A descrição completa e correta é a da alternativa D. O cabeçalho do PDF numera esta questão como 11-C, mas o texto da justificativa reproduz exatamente a alternativa D — que é o conceito certo."},{"id":"p110-12","examId":"p110","number":12,"stem":"Em relação às técnicas de assepsia e antissepsia no ambiente hospitalar, qual é a sequência correta para a realização da lavagem das mãos e paramentação antes de procedimentos cirúrgicos?","options":{"A":"Degerminação, escovação distal para proximal, secagem distal para proximal com compressa estéril, colocação do avental cirúrgico e, por último, colocação das luvas estéreis.","B":"Degerminação, escovação proximal para distal, secagem proximal para distal com compressa estéril, colocação do avental cirúrgico e, por último, colocação das luvas estéreis.","C":"Degerminação, escovação proximal para distal, secagem distal para proximal com toalha de papel, colocação do avental cirúrgico e, por último, colocação das luvas estéreis.","D":"Escovação distal para proximal, desinquinação, secagem proximal para distal com compressa estéril, colocação das luvas estéreis e, por último, colocação do avental cirúrgico."},"answer":"A","explanation":"Escova-se e seca-se das mãos para os antebraços (distal → proximal), com compressa estéril, depois o avental e por último as luvas."},{"id":"p110-13","examId":"p110","number":13,"stem":"Durante um procedimento cirúrgico, cada tempo operatório exige instrumentos específicos para garantir uma execução precisa e segura em cada ato cirúrgico. Analise as afirmativas abaixo e marque a alternativa correta em relação ao instrumental cirúrgico e o tempo operatório correspondente. I. Durante o tempo de diérese, o bisturi é indicado para incisões precisas. II. No tempo de hemostasia, podem ser utilizados pinças hemostáticas e eletrocautério para controlar sangramento e manter um campo cirúrgico adequado. III. Na exérese (diérese), afastadores são essenciais para manipular e visualizar a remoção do campo operatório. IV. Durante a sutura (síntese), são utilizados porta-agulhas, fios cirúrgicos e pinças dente de rato. Assinale a alternativa correta:","options":{"A":"Todas as afirmativas estão corretas.","B":"Apenas as afirmativas I e III estão corretas.","C":"Apenas as afirmativas II e IV estão corretas.","D":"Apenas as afirmativas I, II e IV estão corretas."},"answer":"A","explanation":"O gabarito considera as quatro afirmativas corretas: bisturi na diérese, pinça e cautério na hemostasia, afastadores para expor a exérese e porta-agulhas, fios e dente de rato na síntese."},{"id":"p110-14","examId":"p110","number":14,"stem":"Um paciente de 45 anos, masculino, sofreu tentativa de homicídio onde recebeu um disparo de arma de fogo na região abdominal. Foi submetido a cirurgia que evidenciou a necessidade de suturar o fígado e retirar um segmento de 10 cm do intestino delgado. No que diz respeito à nomenclatura médica quais os termos estão corretos em relação aos procedimentos realizados nessa cirurgia?","options":{"A":"Hepatoplastia e enterotomia.","B":"Hepatectomia e enterorrafia.","C":"Hepatostomia e enterostomia.","D":"Hepatorrafia e enterectomia."},"answer":"D","explanation":"Suturar o fígado = hepatorrafia. Retirar segmento de delgado = enterectomia."},{"id":"p110-15","examId":"p110","number":15,"stem":"Um paciente de 30 anos, sem comorbidades, foi submetido a uma apendicectomia por laparotomia. No acompanhamento pós-operatório, ele desenvolveu uma lesão elevada e eritematosa na cicatriz cirúrgica com crescimento progressivo além dos limites da incisão original. Com base nos mecanismos de cicatrização anormais, qual das alternativas abaixo descreve corretamente o tipo de lesão e seu manejo?","options":{"A":"A cicatriz hipertrófica e o queloide são variantes do mesmo processo fisiológico, diferenciando-se apenas pelo tempo de aparecimento e sem diferenças no tratamento.","B":"O tratamento de escolha para queloides e cicatrizes hipertróficas é sempre a infiltração de corticoides, independentemente do tamanho e da localização da lesão.","C":"A cicatriz hipertrófica resulta de uma produção excessiva de colágeno tipo I e pode ser tratada com excisão cirúrgica imediata para evitar crescimento adicional.","D":"O queloide apresenta proliferação descontrolada de fibroblastos e depósito excessivo de colágeno, ultrapassando os limites da ferida original, sendo mais comum em indivíduos geneticamente predispostos."},"answer":"D","explanation":"Crescer além da incisão define queloide: fibroblastos descontrolados, colágeno em excesso e forte componente genético."},{"id":"p110-16","examId":"p110","number":16,"stem":"Um paciente de 35 anos, sem comorbidades, sofreu um corte profundo na coxa por um objeto cortante. A avaliação clínica revela uma ferida linear, com bordas regulares e sem sinais de infecção. O cirurgião opta por um fechamento primário da ferida. Qual das seguintes técnicas de sutura é mais indicada para promover uma boa coaptação das bordas e minimizar a tensão na cicatriz?","options":{"A":"Sutura contínua intradérmica com fio absorvível monofilamentar, pois reduz a tensão da pele e proporciona melhor resultado estético.","B":"Sutura em X com fio inabsorvível multifilamentar, pois reforça a resistência do fechamento e reduz a formação de cicatriz hipertrófica.","C":"Sutura em U com fio inabsorvível monofilamentar, pois promove maior resistência mecânica e evita isquemia das bordas.","D":"Sutura simples interrompida com fio inabsorvível monofilamentar, pois distribui melhor a tensão ao longo da ferida e permite melhor cicatrização com menor risco de deiscência."},"answer":"D","explanation":"Na coxa, ferida profunda e móvel, o ponto simples interrompido com monofilamento inabsorvível distribui a tensão e permite ajuste ponto a ponto. Intradérmica não segura essa tensão; X e U podem isquemiar a borda."},{"id":"p110-17","examId":"p110","number":17,"stem":"Na prática cirúrgica, a escolha do método de esterilização adequado para cada material é fundamental para garantir a assepsia e evitar infecções. Considerando as características dos métodos de esterilização, qual das alternativas abaixo está CORRETA?","options":{"A":"A autoclavagem a vapor, sob pressão, é ineficaz para eliminar esporos bacterianos, sendo necessária sua complementação com agentes químicos.","B":"O óxido de etileno é um método eficaz para esterilização de materiais sensíveis ao calor, mas exige um tempo prolongado de aeração para eliminação de resíduos tóxicos.","C":"A esterilização por radiação ultravioleta (UV) é a melhor opção para materiais cirúrgicos reutilizáveis, pois elimina rapidamente vírus e bactérias.","D":"A esterilização por calor seco é o método mais eficiente para materiais termossensíveis, como instrumentos endoscópicos."},"answer":"B","explanation":"Óxido de etileno serve ao termossensível e precisa de aeração. Autoclave mata esporos; UV não esteriliza instrumental; calor seco danifica o que não tolera calor."},{"id":"p110-18","examId":"p110","number":18,"stem":"Um paciente de 25 anos, com histórico familiar de cicatrizes anômalas, sofreu um corte profundo no antebraço após um acidente doméstico. Dois meses após a lesão, ele percebeu que a cicatriz estava elevada, eritematosa e com prurido. Nos seis meses depois, a cicatriz continuava crescendo além dos limites da lesão inicial, sem sinais de regressão espontânea. Com base na fisiopatologia da cicatrização excessiva, assinale a alternativa correta:","options":{"A":"A cicatrização hipertrófica e o queloide são condições idênticas, ambas apresentando tendência à regressão espontânea com o tempo, sem necessidade de intervenção médica.","B":"O tratamento cirúrgico pode ser considerado no manejo do queloide sem necessidade de terapias adjuvantes, pois, uma vez que o paciente melhora, pode ser associado a terapias adjuvantes para reduzir o risco de recorrência, como infiltração com corticosteroides ou radioterapia superficial.","C":"O paciente provavelmente desenvolveu uma cicatriz hipertrófica, pois essa condição é caracterizada pelo crescimento progressivo do tecido cicatricial além dos limites da ferida, sem tendência à regressão espontânea.","D":"O quadro descrito sugere um queloide, que se diferencia da cicatriz hipertrófica por ultrapassar os limites da ferida original e não regredir espontaneamente, sendo mais comum em indivíduos com predisposição genética."},"answer":"D","explanation":"Crescimento contínuo além da ferida, sem regressão e com história familiar, é queloide. Cirurgia isolada recidiva com frequência e precisa de adjuvante."},{"id":"p110-19","examId":"p110","number":19,"stem":"Sobre a fisiologia da cicatrização das feridas, assinale a alternativa correta:","options":{"A":"A fase de hemostasia é a última fase da cicatrização e é caracterizada pela formação de uma crosta no local da lesão, sem envolvimento de plaquetas ou fatores de crescimento.","B":"A fase de maturação é caracterizada pela deposição inicial de colágeno, mas não envolve remodelamento do tecido cicatricial, nem reorganização das fibras colágenas, mantendo a força tênsil da cicatriz sempre baixa.","C":"A fase proliferativa é a fase em que a ferida permanece sem alterações visíveis, já que o processo de cicatrização é predominantemente de reepitelização, sem a necessidade de angiogênese.","D":"Durante a fase inflamatória, ocorre a ativação do sistema imunológico, com migração de leucócitos para a área da ferida."},"answer":"D","explanation":"A inflamação recruta leucócitos. Hemostasia é a primeira fase e depende de plaquetas; a proliferação inclui angiogênese; a maturação remodela o colágeno e aumenta a força tênsil."},{"id":"p110-20","examId":"p110","number":20,"stem":"Um paciente de 40 anos é submetido a uma laparotomia de urgência devido a um trauma abdominal contuso. No pós-operatório imediato, observa-se aumento da glicemia, retenção hídrica e mobilização de estoques energéticos. Essas alterações fisiológicas são mediadas principalmente por quais hormônios?","options":{"A":"Glucagon, hormônio do crescimento (GH) e insulina, pois promovem captação de glicose e armazenamento energético, evitando a hiperglicemia no trauma.","B":"Aldosterona, serotonina e insulina, pois reduzem a excreção de sódio, aumentam o tônus vascular e favorecem a captação de glicose pelos tecidos.","C":"Cortisol, catecolaminas e glucagon, pois estimulam gliconeogênese, lipólise e proteólise, aumentando a glicemia e favorecendo o estado hipermetabólico.","D":"Insulina, hormônio antidiurético (ADH) e peptídeo natriurético atrial (ANP), pois promovem homeostase glicêmica e balanço hidroeletrolítico adequado."},"answer":"C","explanation":"Cortisol, catecolaminas e glucagon sustentam o hipermetabolismo e a hiperglicemia do trauma. A insulina está relativamente bloqueada pela resistência periférica."},{"id":"p111-01","examId":"p111","number":1,"stem":"Em relação à técnica de escovação das mãos para procedimentos cirúrgicos, considera-se que um dos fatores mais críticos para a eﬁcácia da lavagem é o tempo de escovação. Qual das alternativas abaixo está de acordo com as recomendações mais recentes sobre o tempo ideal para a escovação das mãos com antisséptico antes de um procedimento cirúrgico?","options":{"A":"Entre 3 e 5 minutos","B":"10 minutos , independente do tipo de cirurgia.","C":"Menos de 1 minuto","D":"De 2 a 3 minutos, em média"},"answer":"A","explanation":"O gabarito recomenda 3 a 5 minutos. Menos de 3 minutos é insuficiente; 10 minutos irrita a pele sem ganho."},{"id":"p111-02","examId":"p111","number":2,"stem":"Um paciente do sexo masculino, 45 anos, chega à sala de emergência após um acidente de carro. O paciente apresenta múltiplos ferimentos no braço esquerdo, com sangramentos evidentes. Durante a avaliação inicial, é necessário interromper o sangramento de forma temporária para permitir a realização de outros procedimentos. Qual das alternativas abaixo descreve os métodos mais comuns para controle temporário do sangramento?","options":{"A":"Compressão direta, ligadura, hemostasia farmacológica","B":"Pinçamento, garroteamento, oclusão endovascular","C":"Sutura, grampeamento, cauterização","D":"Pinçamento, garroteamento, ligadura"},"answer":"B","explanation":"Pinçamento, garrote e oclusão endovascular controlam o sangramento de modo temporário. Ligadura, sutura e cauterização são hemostasia definitiva."},{"id":"p111-03","examId":"p111","number":3,"stem":"Um paciente jovem retorna ao consultório com queixa estética de uma cicatriz elevada na região torácica. O exame revela uma lesão avermelhada, ﬁrme e que ultrapassa os limites da incisão original. Qual é a terminologia médica mais apropriada para descrever este tipo de cicatriz?","options":{"A":"Cicatriz atróﬁca","B":"Cicatriz hipertróﬁca","C":"Deiscência","D":"Quelóide"},"answer":"D","explanation":"Ultrapassar a incisão original define quelóide. A hipertrófica permanece dentro da ferida; atrófica é deprimida; deiscência é abertura da sutura."},{"id":"p111-04","examId":"p111","number":4,"stem":"Paciente procura atendimento no ambulatório queixando-se de que a cicatriz de uma biópsia realizada está feia. Ao exame, é identiﬁcado queloide com cerca de 5 cm na região esternal. Considerando o diagnóstico, qual é a opção correta?","options":{"A":"O tronco não é local comum para ocorrência de queloide e deve ser tratado com injeções de corticoide na lesão","B":"O tronco é um local comum de ocorrência de queloide e tem pouca chance de recidiva após tratamento.","C":"O tronco é um local comum e seu tratamento de primeira linha é a ressecção da ferida apenas.","D":"O tronco é um local comum de ocorrência e, atualmente, não há método eﬁcaz de prevenção."},"answer":"D","explanation":"Tronco, região pré-esternal, deltoide e orelha são sítios comuns. Não há prevenção eficaz comprovada. Excisão isolada recidiva em 50–100%; a primeira linha costuma ser corticoide, silicone ou pressão — não a cirurgia sozinha."},{"id":"p111-05","examId":"p111","number":5,"stem":"Durante um plantão como acadêmico você é chamado pra auxiliar em uma cirurgia. Assim, precisa dominar as técnicas de assepsia e antissepsia para realizar a paramentação de forma correta e evitar uma possível contaminação no ambiente cirúrgico. Dessa forma qual deveria ser a ordem correta das ações apresentadas abaixo?","options":{"A":"Colocação capote, toca e máscara, escovação das mãos e colocação das luvas.","B":"Colocação de toca e máscara, escovação das mãos, colocação capote e colocação luvas.","C":"Colocação de toca e máscara, escovação das mãos, colocação luvas e colocação do capote.","D":"Escovação das mãos, colocação de luvas, colocação capote, colocação de máscara e toca."},"answer":"B","explanation":"Máscara e touca primeiro, depois a escovação, o capote estéril e, por último, as luvas."},{"id":"p111-06","examId":"p111","number":6,"stem":"Durante a preparação de uma cirurgia, a equipe percebe que um dos pacotes de instrumental esterilizado apresenta um pequeno rasgo na lateral da embalagem. O residente questiona se pode utilizar o material, já que aparentemente os instrumentos estão limpos.Qual deve ser a conduta correta diante dessa situação?","options":{"A":"Reforçar a embalagem com ﬁta adesiva estéril e prosseguir com a cirurgia.","B":"Pulverizar antisséptico sobre a embalagem e usar os instrumentos","C":"Devolver o material à Central de Material Esterilizado para reprocessamento.","D":"Utilizar o material normalmente, pois os instrumentos internos não tiveram contato direto com o ambiente externo."},"answer":"C","explanation":"Embalagem rasgada perde a barreira estéril. O material volta para reprocessamento. Fita, spray ou “parece limpo” não restauram a esterilização."},{"id":"p111-07","examId":"p111","number":7,"stem":"Uma paciente de 35 anos apresenta uma lesão cutânea profunda após acidente doméstico. Após a avaliação, a equipe médica decide realizar uma abordagem cirúrgica para acesso e reparo. Entre as opções abaixo, qual das técnicas faz parte dos tipos de diérese, ou seja, das técnicas que envolvem a separação ou divisão dos tecidos?","options":{"A":"Incisão, punção, serração, divulsão","B":"Secção, dilatação, divulsão, punção","C":"Incisão, divulsão, serração, dilatação","D":"Incisão, secção, síntese, serração"},"answer":null,"explanation":"Questão anulada pela banca. Não entra na pontuação do simulado."},{"id":"p111-08","examId":"p111","number":8,"stem":"Paciente apresenta úlcera crônica em MI direitohá mais de 3 anos, faz acompanhamento clínico regular, apresentando períodos de melhora e piora da lesão. Essa úlcera se localiza na região interna da perna, não é dolorosa, não há infecção associada,é superﬁcial, o membro é quente e edemaciado. E esse mesmo MI de uns meses para cá passou a apresentar pigmentação escurecida. O tratamento que vem sendo indicado é deambulação, elevação do membro e curativo compressivo. Com essas informações marque a alternativa correta?","options":{"A":"É uma úlcera de pressão. Ocasionada por isquemia microvascular por pressão contínua.","B":"Trata-se de úlcera crônica diabética, e essa lesão é causada por baixa imunidade devido a falha no funcionamento dos macrófagos..","C":"Úlcera característica de insuﬁciência arterial causada pelo tabagismo que leva a inﬂamação e obstrução das arteriais","D":"Sugestivo de úlcera venosa, causada por aumento da pressão venosa que leva a formação da lipodermatosclerose, por extravasamento de hemoglobina para subcutâneo."},"answer":"D","explanation":"Local medial, indolor, membro quente e edemaciado, pigmentação e resposta à compressão e à elevação definem úlcera venosa."},{"id":"p111-09","examId":"p111","number":9,"stem":"Em relação ao processo de cicatrização de uma ferida cirúrgica, um paciente apresenta sinais típicos de inﬂamação na ferida durante os primeiros dias após a cirurgia. Qual dessas alternativas descreve corretamente a fase da cicatrização observada?","options":{"A":"Fase inﬂamatória","B":"Fase de proliferação","C":"Fase de maturação","D":"Fase de remissão"},"answer":"A","explanation":"Calor, rubor, edema e exsudato nos primeiros dias são a fase inflamatória (cerca de 1 a 5 dias). Não existe fase de remissão na cicatrização."},{"id":"p111-10","examId":"p111","number":10,"stem":"Um paciente diabético, de 60 anos, apresenta uma úlcera no pé que não cicatriza após semanas de tratamento convencional. Durante a avaliação, a equipe médica nota sinais de inﬂamação prolongada e produção inadequada de colágeno. Quais dos fatores abaixo poderiam estar comprometendo o processo de cicatrização dessa ferida?","options":{"A":"A hipoxia pode comprometer a produção de colágeno na ferida.","B":"O uso de glicocorticoides estimula a síntese de colágeno e formação de tecido de granulação.","C":"A radiação ionizante não afeta a cicatrização de feridas, apenas causa dano ao tecido.","D":"Feridas crônicas são aquelas que falham em retornar à integridade após 30 dias."},"answer":"A","explanation":"Sem oxigênio a síntese de colágeno cai. Corticoide e radiação pioram a cura, não ajudam. O prazo de 30 dias não é a definição usada neste gabarito."},{"id":"p111-11","examId":"p111","number":11,"stem":"Uma adolescente de 16 anos chega à emergência com uma laceração de aproximadamente 3 cm na face após uma queda. Após a limpeza e avaliação inicial, o médico decide suturar a lesão para promover uma boa cicatrização estética. Qual seria o melhor tipo de ﬁo para essa sutura, levando em consideração a necessidade de pouca reação tecidual e boa estética na cicatrização?","options":{"A":"Nylon – origem biológica, causa pouca reação tecidual","B":"Nylon – sintético, causa muita reação tecidual e nós ﬁrmes","C":"Categute simples – origem biológica, causa muita reação tecidual","D":"Nylon – sintético, causa pouca reação tecidual"},"answer":"D","explanation":"Nylon é sintético e monofilamentar, com pouca reação tecidual — boa escolha na face. Não é de origem biológica. Categute reage muito."},{"id":"p111-12","examId":"p111","number":12,"stem":"Durante a preparação para uma artroplastia de joelho, o residente pergunta à enfermeira sobre o uso da clorexidina alcoólica na antissepsia da pele.Qual das alternativas abaixo descreve corretamente as características desse antisséptico?","options":{"A":"É volátil e evapora rapidamente, reduzindo sua eﬁcácia na pele.","B":"Rompe membranas celulares, atua melhor contra bactérias Gram-positivas e não é esporicida.","C":"Tem excelente ação residual, mas não é eﬁcaz contra fungos.","D":"É esporicida, o que garante destruição de todas as formas de vida microbiana."},"answer":"B","explanation":"A clorexidina rompe membrana, prefere gram-positivos, age também em gram-negativos e alguns fungos, e não é esporicida. Quem evapora rápido é o álcool."},{"id":"p111-13","examId":"p111","number":13,"stem":"Um paciente será submetido a uma herniorraﬁa inguinal eletiva. Foi realizada tricotomia da região na véspera com lâmina de barbear. No centro cirúrgico a equipe cirúrgica realizou a antissepsia da pele apenas com álcool 70%, sem degermação préviaQual das seguintes aﬁrmações está correta em relação ao preparo do paciente?","options":{"A":"A tricotomia com lâmina é segura e recomendada, pois remove pelos sem aumentar risco de infecção.","B":"O uso de álcool 70% diretamente é suﬁciente para garantir esterilidade da pele antes da incisão.","C":"A degermação é dispensável, já que o álcool 70% elimina toda a microbiota cutânea.","D":"O preparo foi inadequado, pois a lâmina causa microlesões e a ausência de degermação compromete a eﬁcácia da antissepsia."},"answer":"D","explanation":"Lâmina faz microcortes que aumentam ISC, e o álcool sem degermação prévia não remove bem a sujidade nem a flora transitória. Pele não fica estéril."},{"id":"p111-14","examId":"p111","number":14,"stem":"Paciente sofre um acidente por atropelamento e apresenta corte profundo em MI direito, com perda de tecido impossibilitando o fechamento por 1° intenção, optou-se pelo fechamento por 2° intenção. Após 10 dias, tomando os devidos cuidados, a ferida vem apresentando bom aspecto de cicatrização, já não sangra, está sem edema, sem sinais de infecção e com formação de um ótimo tecido de granulação. Com essas informações é correto aﬁrmar:","options":{"A":"Ferida está na fase proliferativa, as células epiteliais são ativadas e formam novos vasos sanguíneos","B":"Ferida na fase maturação, os macrófagos são ativados e formam novos vasos sanguíneos..","C":"Ferida está na fase proliferativa, as células endoteliais são ativadas para formar novos vasos sanguíneos","D":"Ferida está na fase inﬂamatória, os ﬁbroblastos são ativados e formam novos vasos sanguíneos."},"answer":"C","explanation":"Granulação = proliferação. A angiogênese é feita pelo endotélio. Fibroblasto não faz vaso; macrófago não domina a maturação dessa forma."},{"id":"p111-15","examId":"p111","number":15,"stem":"Um paciente de 78 anos, com disfagia grave pós-AVC e episódios de pneumonia aspirativa, precisa de via alternativa de alimentação.Qual procedimento cirúrgico é o mais indicado?","options":{"A":"Enterorraﬁa","B":"Enterotomia","C":"Enterectomia","D":"Jejunostomia"},"answer":"D","explanation":"Jejunostomia cria uma abertura no jejuno para sonda de alimentação. Enterectomia retira intestino; enterorrafia sutura; enterotomia só abre."},{"id":"p111-16","examId":"p111","number":16,"stem":"Diabético com úlcera de pressão estágio 3 e infecção profunda resistente a antimicrobianos tópicos. Qual abordagem local avançada é prioritária?","options":{"A":"Curativos hidrocoloides isolados","B":"Terapia por pressão negativa e desbridamento cirúrgico","C":"Aplicação contínua de antibióticos tópicos","D":"Compressão e curativos absorventes"},"answer":"B","explanation":"Infecção profunda que não responde ao tópico pede desbridamento cirúrgico associado a terapia por pressão negativa. Hidrocoloide sozinho e antibiótico tópico contínuo não resolvem."},{"id":"p111-17","examId":"p111","number":17,"stem":"Paciente sofreu lesão cortante em região torácica devido a acidente com faca. Chega ao pronto socorro algumas horas após o acidente. Ao ser examinado constata-se que o corte é recente ainda com sangramento em atividade e edema local. Evidentemente trata-se da fase inﬂamatória da cicatrização. Marque a alternativa que cita as células que predominam nessa fase?","options":{"A":"Fibroblastos, proteoglicanos e glicosaminoglicanos.","B":"Macrófagos, mastócitos e matriz extra celular","C":"Plaquetas, macrófagos, mastócitos e neutróﬁlos","D":"Células epiteliais, células endoteliais e plaquetas."},"answer":"C","explanation":"A inflamação começa com plaquetas e segue com neutrófilos, macrófagos e mastócitos. Fibroblasto e endotélio vêm na proliferação."},{"id":"p111-18","examId":"p111","number":18,"stem":"As técnicas de assepsia, antissepsia e esterilização são fundamentais para evitar infecção em qualquer procedimento cirúrgico. Não dominar essas técnicas pode gerar danos irreparáveis a saúde desses pacientes. Dessa forma, das alternativas abaixo qual podemos deﬁnir como um procedimento de antissepsia?","options":{"A":"Autoclavar material metálico.","B":"Colocação de campos cirúrgicos estéreis","C":"Escovação/degermação do sítio cirúrgico com antissépticos.","D":"Colocação de máscara e gorro."},"answer":"C","explanation":"Antissepsia é agente químico em tecido vivo — aqui, degermação do campo com antisséptico. Autoclave é esterilização; campo, máscara e gorro são assepsia/barreira."},{"id":"p111-19","examId":"p111","number":19,"stem":"Em um procedimento de colecistectomia videolaparoscópica, o termo “-ectomia” é utilizado para descrever a remoção de um órgão ou estrutura. Sabendo disso, qual dos seguintes termos médicos também faz referência à remoção cirúrgica de uma estrutura especíﬁca?","options":{"A":"Ureterectomia","B":"Neumectomia","C":"Vasectomia","D":"Histerectomia"},"answer":"D","explanation":"O gabarito marca histerectomia: retirada do útero, com o sufixo -ectomia aplicado a um órgão. A banca descarta vasectomia (não é um órgão), “neumectomia” (grafia incorreta de pneumectomia) e ureterectomia neste enunciado."},{"id":"p111-20","examId":"p111","number":20,"stem":"Um homem de 45 anos, com dor abdominal súbita e intensa no epigástrio, foi diagnosticado com úlcera péptica perfurada. O cirurgião optou por suturar diretamente a perfuração gástrica. Qual o termo cirúrgico correto para esse procedimento?","options":{"A":"Gastrorraﬁa","B":"Gastrectomia","C":"Gastrostomia","D":"Gastrotomia"},"answer":"A","explanation":"Suturar o estômago = gastrorrafia. Gastrectomia retira; gastrostomia abre para fora; gastrotomia só incisa a parede."},{"id":"p112-01","examId":"p112","number":1,"stem":"O domínio das técnicas de assepsia, antissepsia e esterilização são fundamentais para a segurança do paciente cirúrgico, pois tem a finalidade de evitar infecção no sítio operatório e consequentemente evitar todas as complicações relacionadas. No que diz respeito aos principais antissépticos utilizados na prática clínica, analise as afirmativas e marque a correta:","options":{"A":"Clorexidina não causa reações alérgicas cutâneas.","B":"O álcool a 70% tem função bactericida excelente e ótimo efeito residual.","C":"Clorexidina tem efeito residual muito curto e por isso é pouco utilizada.","D":"O povidine (iodopirrolidona) tem efeito bactericida e bacteriostático fraco e não provoca alergias cutâneas."},"answer":"A","explanation":"Pelo gabarito (texto da prova): a clorexidina não é considerada alergênica, não mancha e tem boa ação residual. O álcool não tem efeito residual importante; a clorexidina é muito usada justamente pelo residual; o iodóforo não é de ação fraca."},{"id":"p112-02","examId":"p112","number":2,"stem":"Paciente vítima de acidente automobilístico é submetido à laparotomia. Durante o procedimento são realizadas: I. Incisão mediana; II. Ligadura de vasos sangrantes; III. Ressecção de segmento intestinal inviável; IV. Fechamento da parede abdominal. A sequência correta dos tempos fundamentais é:","options":{"A":"Hemostasia – diérese – síntese – exérese","B":"Exérese – diérese – hemostasia – síntese","C":"Diérese – exérese – hemostasia – síntese","D":"Diérese – hemostasia – exérese – síntese"},"answer":"D","explanation":"A ordem do caso é abertura (diérese), controle do sangramento (hemostasia), retirada do segmento (exérese) e fechamento (síntese)."},{"id":"p112-03","examId":"p112","number":3,"stem":"O óxido de etileno é amplamente utilizado na esterilização de materiais hospitalares. Em relação ao seu uso, assinale a alternativa correta:","options":{"A":"É utilizado para esterilização de materiais termossensíveis, atuando em baixa temperatura e com alta capacidade de penetração","B":"É indicado principalmente para materiais metálicos resistentes ao calor, devido à sua alta temperatura de ação","C":"Atua apenas contra bactérias vegetativas, não sendo eficaz contra esporos","D":"Não requer cuidados especiais após o processo, podendo o material ser utilizado imediatamente"},"answer":"A","explanation":"Óxido de etileno esteriliza a baixa temperatura, penetra bem e serve para termossensíveis. É esporicida e exige aeração, porque o gás é tóxico."},{"id":"p112-04","examId":"p112","number":4,"stem":"Paciente no 6º dia pós-operatório de apendicectomia. Apresenta dor na ferida operatória, hiperemia local e saída de secreção purulenta. Ao exame: PA 120 x 80 mmHg, FR 14 irpm, FC 80 bpm, temperatura axilar 36,5 ºC. Qual a melhor conduta inicial?","options":{"A":"Drenagem da ferida","B":"Antibioticoterapia imediata","C":"Alta hospitalar","D":"Apenas observação"},"answer":"A","explanation":"Infecção incisional superficial, sem repercussão sistêmica: a conduta inicial é abrir e drenar a ferida. Antibiótico não é obrigatório na ausência de sinais sistêmicos."},{"id":"p112-05","examId":"p112","number":5,"stem":"Complete a frase a seguir com as opções abaixo respectivamente “A ________ é a organização tecidual com a substituição das células mortas ou lesadas por novas células, idênticas às originais, promovendo a restituição total e a funcionalidade do tecido ou do órgão afetado” “Na _______ ocorre o restabelecimento da homeostasia dos tecidos, com perda ou não de sua atividade funcional pela formação de um tecido mais parecido ao original”","options":{"A":"Reorganização / proliferação","B":"Reconstrução / inflamação","C":"Regeneração /cicatrização","D":"Cicatrização / reorganização"},"answer":"C","explanation":"Regeneração repõe células iguais às originais e devolve a função. Cicatrização restaura a homeostase com um tecido de reparo, que pode não recuperar a função original."},{"id":"p112-06","examId":"p112","number":6,"stem":"Paciente de 25 anos evolui após cirurgia com cicatriz elevada, eritematosa, restrita aos limites da incisão, com regressão parcial ao longo dos meses. Assinale a alternativa correta:","options":{"A":"Trata-se de cicatriz hipertrófica e pode regredir espontaneamente","B":"Trata-se de queloide e não ultrapassa os limites da ferida","C":"Trata-se de cicatriz hipertrófica e sempre necessita cirurgia","D":"Trata-se de queloide e o tratamento padrão é excisão isolada"},"answer":"A","explanation":"Cicatriz elevada que permanece dentro da incisão e regride com o tempo é hipertrófica. Queloide ultrapassa os limites e não regride sozinho; excisão isolada não é o padrão."},{"id":"p112-07","examId":"p112","number":7,"stem":"Paciente feminina, 67 anos. Apresenta úlcera em MI direito, na altura do maléolo externo. Início aproximadamente 1 ano. A úlcera é dolorosa e profunda, ao redor da lesão é frio. Foi solicitado doppler de Mis que constatou semi oclusão da artéria fibular, caracterizando úlcera crônica arterial. Além da úlcera, ela apresenta obesidade, diabetes, hipertensão arterial, é tabagista e acamada por sequela de AVC. Das comorbidades abaixo, qual tem relação direta com úlceras arteriais?","options":{"A":"Imobilização prolongada.","B":"Diabetes.","C":"Tabagismo.","D":"Obesidade."},"answer":"C","explanation":"O gabarito aponta o tabagismo como fator diretamente ligado à doença arterial periférica e, portanto, à úlcera arterial. Imobilização relaciona-se mais a úlcera de pressão e estase."},{"id":"p112-08","examId":"p112","number":8,"stem":"Após cerca de 24 h de jejum no trauma cirúrgico, o organismo passa a:","options":{"A":"Utilizar proteínas e lipídios como fonte energética","B":"Utilizar exclusivamente glicogênio hepático","C":"Interromper a produção de energia","D":"Manter consumo apenas de glicose"},"answer":"A","explanation":"Esgotado o glicogênio, entram proteólise e lipólise (e gliconeogênese) para sustentar o estado catabólico."},{"id":"p112-09","examId":"p112","number":9,"stem":"O exercício da cirurgia exige o conhecimento básico dos três fundamentos da técnica operatória: diérese, hemostasia e síntese. Toda habilidade e conhecimento da equipe cirúrgica, favorecem as tomadas de decisões no intuito de obter os melhores resultados em cada procedimento cirúrgico. Sendo assim, diante dessas situações cirúrgicas, classifique os procedimentos realizados de acordo com os tempos fundamentais: “ .. a equipe cirúrgica envolveu o membro inferior direito do paciente com faixa elástica com a finalidade de diminuir o sangramento na cirurgia.” “ ... em um determinado momento o cirurgião utilizou afastadores manuais para abrir espaço no sítio cirúrgico afastando a musculatura sem a necessidade de seccionar. “ “ ... utilizando o ultrassom foi localizado um nódulo na mama e realizado biópsia para coleta de material.”","options":{"A":"Garroteamento, divulsão e punção.","B":"Tamponamento, incisão, exérese","C":"Obturação, dilatação e punção","D":"Compressão, compressão e incisão."},"answer":"A","explanation":"Faixa de Esmarch = garroteamento (hemostasia temporária). Afastar sem cortar = divulsão. Biópsia por agulha = punção."},{"id":"p112-10","examId":"p112","number":10,"stem":"Paciente de 64 anos, diabético, dá entrada com dor em fossa ilíaca direita há 48h, febre e leucocitose. TC mostra apêndice perfurado com abscesso periapendicular. Submetido à laparotomia com drenagem de abscesso e retirada do apêndice. No 6º PO evolui com hiperemia, calor, dor local e secreção purulenta superficial na ferida operatória. Assinale a alternativa CORRETA:","options":{"A":"O procedimento é laparotomia exploradora e a infecção é sistêmica","B":"O procedimento é apendicectomia e a infecção é incisional profunda","C":"O procedimento realizado é denominado apendicostomia e a infecção é órgão/espaço","D":"O procedimento é apendicectomia e a infecção é incisional superficial"},"answer":"D","explanation":"Retirada do apêndice = apendicectomia. Sinais restritos à pele e ao subcutâneo, com pus superficial, definem ISC incisional superficial."},{"id":"p112-11","examId":"p112","number":11,"stem":"Paciente de 48 anos, submetido a laparotomia por peritonite há 6 meses, retorna com dor abdominal em cólica, distensão e vômitos. TC sugere obstrução intestinal sem hérnia evidente. O mecanismo fisiopatológico mais provável é:","options":{"A":"Necrose isquêmica intestinal primária","B":"Formação de aderências por deposição excessiva de fibrina","C":"Deficiência de colágeno na cicatrização","D":"Infecção crônica persistente"},"answer":"B","explanation":"Aderências por deposição de fibrina e falha da fibrinólise são a principal causa de obstrução tardia depois de laparotomia."},{"id":"p112-12","examId":"p112","number":12,"stem":"Você esta no centro cirúrgico acompanhando um procedimento e escuta o cirurgião solicito a circulante que abra um prolene 3-0. Considerando o material solicitado, qual característica define esse fio?","options":{"A":"Absorvível orgânico","B":"Inabsorvível sintético","C":"Inabsorvível orgânico","D":"Absorvível sintética"},"answer":"B","explanation":"Prolene é polipropileno: sintético, monofilamentar e inabsorvível."},{"id":"p112-13","examId":"p112","number":13,"stem":"Assinale a alternativa correta a respeito de excesso de cicatrização:","options":{"A":"Queloide respeita o limite da ferida e tem crescimento limitado","B":"Cicatriz hipertrófica se desenvolve com cerca de 3 meses","C":"Queloide é mais comum em lóbulo da orelha, pré-esternal e deltoide","D":"Cicatrizes hipertróficas são comuns em região da orelha e pré-esternal"},"answer":"C","explanation":"Queloides preferem lóbulo da orelha, deltoide, pré-esternal e dorso. Eles ultrapassam a ferida. Orelha e pré-esternal não são o território típico da hipertrófica."},{"id":"p112-14","examId":"p112","number":14,"stem":"A resposta endócrina, metabólica e imunológica ao trauma se caracteriza por uma reação do organismo a um dano sofrido que gerou uma instabilidade sistêmica e o organismo vai reparar essa injúria. Para isso ocorre uma cascata de eventos que tem como finalidade manter hipermetabolismo, geração de energia e manutenção do volume intravascular. Marque a afirmativa abaixo que estiver correta sobre o tema REMIT:","options":{"A":"Cortisol tem como principal função vasoconstricção, aumento frequência cardíaca e diminuição diurese.","B":"As catecolaminas são responsáveis por regular o sistema circulatório através da vasoconstricção e aumento da frequência cardíaca.","C":"Glucagon age promovendo controle da estabilidade hemodinâmica.","D":"Gliconeogêneseocorre principalmentepor estímulo da aldosterona."},"answer":"B","explanation":"Catecolaminas sustentam a circulação no trauma: vasoconstrição e taquicardia. Vasoconstrição e queda da diurese não são a função principal do cortisol; a gliconeogênese é estimulada por glucagon, cortisol e GH, não pela aldosterona."},{"id":"p112-15","examId":"p112","number":15,"stem":"Paciente submetido a hernioplastia sem abertura de vísceras e sem quebra de técnica asséptica. Essa ferida é classificada como:","options":{"A":"Infectada","B":"Contaminada","C":"Limpa","D":"Potencialmente contaminada"},"answer":"C","explanation":"Sem abrir trato contaminado e sem falha técnica, a ferida é limpa."},{"id":"p112-16","examId":"p112","number":16,"stem":"Paciente de 40 anos sofre ferimento corto-contuso em perna há 12 horas, com sujidade e bordas desvitalizadas. Após limpeza e desbridamento, o cirurgião opta por não fechar a ferida imediatamente. Após 4 dias, sem sinais de infecção, realiza-se sutura. Esse tipo de cicatrização é denominado:","options":{"A":"Segunda intenção","B":"Cicatrização por granulação primária","C":"Primeira intenção","D":"Terceira intenção"},"answer":"D","explanation":"Fechamento primário tardio, depois de controlar a contaminação, é a terceira intenção. Em geral ocorre entre o 3º e o 5º dia."},{"id":"p112-17","examId":"p112","number":17,"stem":"Paciente apresenta quadro compatível com tumor do cólon ascendente e será submetido a procedimento para retirada do cólon. Qual nome desse procedimento ?","options":{"A":"Colectomia esquerda","B":"Colostomia direita","C":"Colectomia direita","D":"Colostomia esquerda"},"answer":"C","explanation":"Retirada do cólon ascendente = colectomia direita. Estomia seria abrir o cólon para o exterior, não retirá-lo."},{"id":"p112-18","examId":"p112","number":18,"stem":"Considere: I. Os tempos cirúrgicos fundamentais são diérese, hemostasia e secção. II. A nomenclatura cirúrgica ajuda na precisão da comunicação. III. O prefixo indica o tipo de intervenção cirúrgica a ser realizada. IV. O sufixo indica o tipo de intervenção cirúrgica a ser realizada. Assinale a alternativa correta:","options":{"A":"II e IV estão corretas","B":"I, II e VI estão corretas","C":"I está correta","D":"I e III estão corretas"},"answer":"A","explanation":"II e IV são verdadeiras: a nomenclatura padroniza a comunicação e o sufixo diz a ação (-ectomia, -tomia, -rafia). Os tempos fundamentais não incluem “secção” como tempo próprio, e o prefixo em geral nomeia o órgão."},{"id":"p112-19","examId":"p112","number":19,"stem":"A cicatrização é uma sequência complexa de eventos moleculares e celulares que interagem com a finalidade de restaurar um tecido que foi danificado. De acordo com descrição abaixo, classifique em qual fase da cicatrização o texto se refere: “ ... responsável pelo aumento da força de tensão e pela diminuição do tamanho da cicatriz...aumentam a síntese e a produção do colágeno do tipo I. Gradativamente, os feixes de fibras colágenas tornam-se mais espessos, resultando em uma configuração mais regular, que está diretamente relacionada às forças mecânicas às quais o tecido está sujeito durante a atividade normal. Assim, a cicatriz torna-se mais resistente após o colágeno ter sofrido maturação...”","options":{"A":"Fase inflamatória.","B":"Fase de epitelização.","C":"Fase de remodelação.","D":"Fase hemostasia."},"answer":"C","explanation":"Remodelação (maturação) é a fase longa em que o colágeno III vira colágeno I, a cicatriz encolhe, perde vasos e ganha força de tensão."},{"id":"p112-20","examId":"p112","number":20,"stem":"Sobre a flora cutânea, assinale a alternativa correta:","options":{"A":"A flora transitória é mais estável e de difícil remoção","B":"A flora residente é composta principalmente por bactérias gram-negativas","C":"A flora residente apresenta alta virulência","D":"A flora transitória é facilmente removida com higiene simples"},"answer":"D","explanation":"A flora transitória é superficial, mais virulenta e sai com água e sabão. A residente é estável, menos virulenta e mais difícil de remover; predomina gram-positivo."},{"id":"feridas-01","examId":"feridas","number":1,"stem":"Paciente masculino, 42 anos, é submetido a uma laparotomia exploradora de urgência por peritonite fecal decorrente de perfuração diverticular. Após meses de evolução clínica satisfatória, retorna ao ambulatório de cirurgia geral queixando-se de dor em cólica e episódios de suboclusão intestinal. Em relação à fisiopatologia da formação de aderências peritoneais nesses pacientes, assinale a alternativa correta:","options":{"A":"A formação de aderências independe da magnitude do processo inflamatório ou da manipulação operatória.","B":"Aderências são formadas exclusivamente por tecido ósseo ectópico após peritonites químicas.","C":"Quanto maior o grau de inflamação peritoneal e de manipulação dos tecidos, maior tende a ser a formação de traves e cordões fibrosos.","D":"Procedimentos laparotômicos por contaminação fecal evitam a formação de aderências devido à lise celular pela acidez bacteriana."},"answer":"C","explanation":"As aderências peritoneais são cicatrizes intra-abdominais cuja magnitude está intimamente ligada à intensidade do trauma cirúrgico e à gravidade da inflamação/peritonite prévia."},{"id":"feridas-02","examId":"feridas","number":2,"stem":"Durante o atendimento inicial de urgência a um paciente vítima de acidente de trabalho com serra elétrica, o médico observa uma lesão puntiforme de aproximadamente 1,5 cm na parede abdominal anterior. Diante da avaliação de feridas potencialmente penetrantes, assinale a afirmativa correta:","options":{"A":"O comprimento externo da ferida é sempre suficiente para descartar lesão cavitária profunda.","B":"A extensão e o tamanho externo da lesão cutânea nem sempre refletem sua profundidade real, sendo necessária avaliação criteriosa e eventual exploração digital sob anestesia.","C":"Deve-se suturar imediatamente a ferida em plano único para conter possíveis eviscerações microscópicas.","D":"Toda ferida puntiforme é superficial e não necessita de analgesia ou exploração."},"answer":"B","explanation":"Feridas puntiformes ou provocadas por fragmentos e armas brancas podem parecer pequenas na superfície externa da pele, mas penetrar profundamente em cavidades ou lesar planos nobres."},{"id":"feridas-03","examId":"feridas","number":3,"stem":"Você está em plantão de emergência e recebe um paciente com laceração traumática extensa que atravessa a pele e atinge planos musculares profundos. O residente orienta o fechamento cirúrgico da lesão. Qual deve ser a conduta e sequência correta na síntese de feridas profundas?","options":{"A":"Fechar a pele com pontos em chuleio e deixar os planos profundos abertos para drenagem espontânea.","B":"Realizar a síntese de dentro para fora, aproximando inicialmente os planos profundos e o tecido subcutâneo antes do fechamento cutâneo.","C":"Realizar sutura da pele de fora para dentro e aproximar os planos profundos por último através de pinçamento cego.","D":"Fechar apenas a camada mais superficial com cola cirúrgica, dispensando o fechamento fascial."},"answer":"B","explanation":"O fechamento de feridas que atingem planos profundos deve ser realizado de dentro para fora, aproximando os planos profundos e o subcutâneo antes do plano cutâneo, reduzindo o espaço morto."},{"id":"feridas-04","examId":"feridas","number":4,"stem":"Paciente de 38 anos comparece ao 7º dia pós-operatório de cesariana apresentando dor intensa, hiperemia que ultrapassa amplamente as margens da incisão, edema e saída de secreção purulenta espessa pela ferida. Ao exame físico, encontra-se febril e taquicárdica. Qual conduta local imediata é prioritária para o caso?","options":{"A":"Manter a ferida sob curativo oclusivo estéril e prescrever apenas antibiótico oral.","B":"Retirar pontos da sutura, abrir a região para permitir ampla drenagem e realizar limpeza local, evitando manter a ferida ocluída.","C":"Ressecar imediatamente toda a incisão em bloco até a cavidade peritoneal.","D":"Aplicar compressão vigorosa com faixa elástica e prescrever corticoide intralesional."},"answer":"B","explanation":"Ferida com infecção ativa e coleção purulenta não pode permanecer ocluída ou fechada; a conduta mandatória é abrir a incisão, permitir ampla drenagem e manter controle local da ferida."},{"id":"feridas-05","examId":"feridas","number":5,"stem":"A cicatrização fisiológica de uma ferida cirúrgica depende diretamente das condições do microambiente local. Sobre o ambiente ideal para a cicatrização das feridas, assinale a alternativa correta:","options":{"A":"A ferida deve ser mantida excessivamente ressecada para evitar o desenvolvimento de germes saprófitas.","B":"A compressão excessiva da ferida é recomendada em todos os casos para acelerar a neovascularização das bordas.","C":"O ambiente ideal deve ser limpo, controladamente úmido, sem excesso de secreção e sem compressão que comprometa a perfusão tecidual.","D":"O acúmulo exagerado de exsudato purulento é benéfico por nutrir os macrófagos durante o remodelamento."},"answer":"C","explanation":"O ambiente cicatricial ótimo exige equilíbrio: hidratação controlada (nem ressecamento excessivo nem maceração por excesso de secreção) e ausência de isquemia induzida por compressão exagerada."},{"id":"feridas-06","examId":"feridas","number":6,"stem":"Um paciente vítima de queda de motocicleta dá entrada na sala de emergência apresentando escoriações extensas e profundas no membro inferior direito com grande quantidade de sujidade e asfalto aderidos. A equipe decide cobrir a área após a higienização. Qual a melhor recomendação para o curativo dessa ferida?","options":{"A":"Utilizar gaze seca comum diretamente sobre o leito da abrasão sem qualquer cobertura intermediária.","B":"Empregar curativo oclusivo impermeável aderente que grude firmemente nas bordas cruentas.","C":"Utilizar curativo não aderente para manter a umidade controlada e evitar sangramento, dor e arrancamento tecidual durante as trocas.","D":"Deixar a lesão exposta ao sol para promover crosta ressecada precoce."},"answer":"C","explanation":"Curativos aderentes comuns arrancam a camada neoepitelizada durante as trocas nas áreas de escoriação, provocando dor e novo sangramento; coberturas não aderentes evitam esse trauma mecânico."},{"id":"feridas-07","examId":"feridas","number":7,"stem":"No que diz respeito às propriedades físicas dos curativos utilizados no manejo pós-operatório e de feridas exsudativas, estabeleça a diferença entre materiais hidrofílicos e hidrofóbicos:","options":{"A":"O curativo hidrofílico repele líquidos, enquanto o hidrofóbico tem grande afinidade e absorve secreções.","B":"O curativo hidrofílico possui afinidade por líquidos e atua absorvendo exsudato; já o curativo hidrofóbico é mais impermeável e dificulta a passagem de fluidos.","C":"Materiais hidrofílicos nunca podem ser combinados com coberturas hidrofóbicas no mesmo paciente.","D":"Todo curativo hidrofóbico é contraindicado em procedimentos cirúrgicos limpos."},"answer":"B","explanation":"Curativos hidrofílicos têm grande avidez por água e secreções (absorventes), enquanto materiais hidrofóbicos são repelentes de líquidos ou impermeáveis (barreiras externas)."},{"id":"feridas-08","examId":"feridas","number":8,"stem":"Paciente idosa, portadora de úlcera venosa crônica com moderada exsudação, é atendida no ambulatório. O residente sugere aplicar uma cobertura de hidrocoloide na lesão. Em relação às características e indicações do hidrocoloide, assinale a afirmativa correta:","options":{"A":"É indicado primariamente para feridas extremamente exsudativas com secreção abundante, pois não sofre saturação precoce.","B":"É uma placa que absorve e favorece a evaporação, sendo útil em feridas crônicas com exsudação leve a moderada, mas que pode saturar rapidamente em feridas muito secretivas.","C":"É um curativo composto exclusivamente por fragmentos de algas marinhas bactericidas.","D":"Trata-se de curativo impermeável indicado apenas para fechamento por primeira intenção de cortes na face."},"answer":"B","explanation":"As placas de hidrocoloide absorvem exsudato e favorecem evaporação em níveis baixos a moderados; em feridas excessivamente exsudativas, elas saturam de forma rápida e vazam."},{"id":"feridas-09","examId":"feridas","number":9,"stem":"Paciente diabético apresenta lesão cavitária em região plantar com grande quantidade de exsudato purulento e contaminação bacteriana local. A equipe opta pelo uso de um curativo à base de alginato. Qual é a principal característica desse tipo de cobertura?","options":{"A":"É um material derivado de algas, com grande capacidade de absorção de exsudato, que pode apresentar ação bacteriostática e ser empregado em feridas muito secretivas.","B":"É uma película plástica impermeável que veda totalmente a ferida, impedindo a saída de secreções.","C":"Atua exclusivamente como desbridante enzimático à base de colagenase sem absorver fluidos.","D":"É contraindicado em feridas com qualquer nível de contaminação bacteriana."},"answer":"A","explanation":"O alginato (derivado de algas) possui alta capacidade hidrofílica de absorção de exsudato e atua como malha bacteriostática em feridas secretivas ou contaminadas."},{"id":"feridas-10","examId":"feridas","number":10,"stem":"Paciente vítima de esmagamento de membro inferior evolui com perda tecidual extensa e ferida profunda de difícil aproximação de bordos. O cirurgião decide indicar terapia por pressão negativa (curativo a vácuo). Quais são os principais mecanismos fisiológicos de ação dessa terapia?","options":{"A":"Ressecamento da ferida e inibição da migração de leucócitos.","B":"Remoção contínua de exsudato e secreções, associada ao estímulo mecânico para formação de tecido de granulação.","C":"Obliteração dos vasos sanguíneos para evitar hemorragias e impedir proliferação de colágeno.","D":"Imunização ativa da ferida com deposição direta de queratinócitos maduros."},"answer":"B","explanation":"O sistema de vácuo contínuo aspira fluidos e exsudato em excesso, diminuindo edema tecidual e exercendo estresse mecânico que estimula ativamente a angiogênese e o tecido de granulação."},{"id":"feridas-11","examId":"feridas","number":11,"stem":"Durante a prescrição dos cuidados locais de um paciente vítima de queimadura térmica de segundo grau em tórax e abdome, o interno sugere aplicar compressas de gelo e soluções extremamente geladas sobre a lesão para alívio álgico. A conduta do interno deve ser corrigida porque:","options":{"A":"O gelo acelera a proliferação bacteriana sistêmica.","B":"O resfriamento excessivo pode induzir hipotermia e perda excessiva de calor pelo paciente.","C":"Substâncias frias inibem a ação bactericida dos macrófagos de maneira irreversível.","D":"O paciente adquire tolerância imediata a opioides se exposto a temperaturas baixas."},"answer":"B","explanation":"Áreas queimadas extensas perdem a barreira térmica natural da epiderme; o uso de soluções excessivamente geladas ou gelo pode induzir hipotermia sistêmica grave."},{"id":"feridas-12","examId":"feridas","number":12,"stem":"Paciente jovem procura atendimento referindo que realizou um piercing na cartilagem auricular há 6 meses e desenvolveu tumoração fibroelástica de crescimento contínuo, que ultrapassou amplamente as bordas do orifício original. Diante do diagnóstico de queloide, assinale a opção correta quanto ao seu manejo:","options":{"A":"A excisão cirúrgica simples e isolada é o tratamento padrão ouro e não apresenta risco de recidiva.","B":"As terapias isoladas possuem eficácia limitada, sendo recomendada a abordagem multimodal combinando ressecção, corticoterapia intralesional e/ou placa de silicone.","C":"Queloides nunca recorrem após remoção cirúrgica de suas bordas ativas.","D":"O queloide tem resolução espontânea completa ao final de 30 dias de evolução clínica."},"answer":"B","explanation":"A excisão cirúrgica simples isolada do queloide cursa com altíssimas taxas de recidiva, sendo indispensável a terapia combinada (corticoide intralesional, placas/gel de silicone, compressão)."},{"id":"feridas-13","examId":"feridas","number":13,"stem":"Mulher de 28 anos sofreu ferimento cortocontuso linear na fronte após colisão leve. Foi submetida à sutura simples com fio monofilamentar. Considerando a localização anatômica na face e o tempo de retirada dos pontos, assinale a afirmativa correta:","options":{"A":"Pontos na face devem ser retirados mais rapidamente do que em regiões de dobras ou sobre articulações, devido à melhor vascularização e cicatrização acelerada.","B":"Suturas faciais devem ser mantidas por pelo menos 21 dias para assegurar maturação completa do colágeno tipo I.","C":"A retirada de pontos sobre superfícies articulares é sempre mais rápida que na face devido à menor tensão mecânica local.","D":"A face não aceita síntese primária por fios monofilamentares."},"answer":"A","explanation":"Devido à farta vascularização facial, o tempo de permanência dos pontos na face é curto para prevenir marcas de sutura; já áreas articulares requerem maior tempo devido à tensão contínua."},{"id":"feridas-14","examId":"feridas","number":14,"stem":"Durante o acompanhamento ambulatorial de feridas cirúrgicas, é fundamental que o médico saiba diferenciar o processo inflamatório fisiológico de um quadro infeccioso ativo. Assinale a alternativa que indica com mais precisão a suspeita de infecção da ferida:","options":{"A":"Presença de hiperemia discreta estritamente limitada aos bordos da incisão no 2º dia pós-operatório.","B":"Leve desconforto à palpação local nas primeiras 24 horas após o procedimento cirúrgico.","C":"Eritema que se expande além dos limites da ferida (celulite), associado a edema progressivo, drenagem purulenta ou repercussões sistêmicas.","D":"Ausência de drenagem em ferida operatória limpa."},"answer":"C","explanation":"Hiperemia fisiológica inicial é delimitada e restrita à borda cirúrgica; eritema expansivo com celulite, calor, secreção purulenta e edema é marcador inequívoco de infecção local."},{"id":"feridas-15","examId":"feridas","number":15,"stem":"No tratamento de feridas crônicas e queimaduras extensas, têm sido utilizados substitutos de pele biológicos (como a pele de tilápia) e materiais sintéticos. A função primordial dessas coberturas em relação aos curativos comuns é:","options":{"A":"Ocluir totalmente a lesão sem permitir nenhuma troca gasosa.","B":"Destruir todo o leito celular subjacente através de lise cáustica.","C":"Além de proteger a ferida, estimular ativamente a cicatrização e favorecer a formação de uma cobertura semelhante à pele.","D":"Substituir permanentemente a necessidade de enxertia autóloga em perdas de espessura total com exposição óssea."},"answer":"C","explanation":"Ao contrário das gazes e coberturas simples, substitutos de pele (biológicos ou bioengenheirados) atuam como arcabouço biológico que estimula proliferação celular e neovascularização estruturada."},{"id":"fases-01","examId":"fases","number":1,"stem":"O restabelecimento da continuidade tissular após um trauma cirúrgico pode se processar por regeneração ou cicatrização. No que diz respeito a esses conceitos biológicos, analise as afirmativas e marque a correta:","options":{"A":"Regeneração consiste na substituição do tecido lesado por tecido fibroso que não mantém a função original.","B":"A cicatrização restaura o órgão através de células idênticas às originais, sem formação de fibrose.","C":"A regeneração repõe o tecido lesionado por outro morfologicamente e funcionalmente idêntico ao original, enquanto a cicatrização substitui a área por tecido conjuntivo fibroso.","D":"Nos seres humanos adultos, todo o sistema nervoso central possui capacidade ilimitada de regeneração tecidual após secção medular."},"answer":"C","explanation":"Regeneração é a recomposição do tecido por células idênticas às originais com restauração funcional; a cicatrização consiste na substituição da área lesada por tecido conjuntivo fibroso (tecido cicatricial)."},{"id":"fases-02","examId":"fases","number":2,"stem":"Um paciente de 40 anos é submetido a uma gastrectomia parcial por laparotomia eletiva. Ao término do procedimento cirúrgico, o cirurgião realiza a aproximação dos bordos da incisão abdominal por planos com pontos cirúrgicos. Esse tipo de fechamento da ferida é denominado cicatrização por:","options":{"A":"Segunda intenção.","B":"Terceira intenção.","C":"Primeira intenção.","D":"Quarta intenção."},"answer":"C","explanation":"O fechamento primário no qual os bordos da ferida são aproximados cirurgicamente (geralmente por sutura) logo após a incisão define a cicatrização por primeira intenção."},{"id":"fases-03","examId":"fases","number":3,"stem":"Paciente de 32 anos dá entrada com ferimento grave em perna por mordedura canina ocorrida há 18 horas, apresentando ferida de bordos lacerados e contaminação grosseira por saliva e sujidade. O cirurgião opta por não fechar a lesão inicialmente, realizando limpeza rigorosa; após 4 dias de curativos e controle do quadro sem infecção, realiza a sutura primária retardada. Esse fechamento é classicamente denominado:","options":{"A":"Primeira intenção precoce.","B":"Segunda intenção.","C":"Terceira intenção (ou primária retardada).","D":"Regeneração anômala tardia."},"answer":"C","explanation":"Feridas mantidas inicialmente abertas para debridamento, limpeza e controle de contaminação e posteriormente fechadas por síntese cirúrgica caracterizam a cicatrização por terceira intenção (ou primária retardada)."},{"id":"fases-04","examId":"fases","number":4,"stem":"Durante a fase inflamatória da cicatrização, ocorre o recrutamento ordenado de diversos elementos celulares no leito da lesão. Sobre o papel dessas células, assinale a afirmativa correta:","options":{"A":"Os neutrófilos são as últimas células a atingir a área lesionada, atuando apenas na remodelação do colágeno.","B":"As plaquetas formam o tampão hemostático inicial e os neutrófilos constituem a linha de frente precoce de defesa, enquanto os macrófagos assumem papel central na orquestração inflamatória e fagocitose.","C":"Os mastócitos são responsáveis diretos pela síntese do colágeno tipo I maduro.","D":"As células de Schwann substituem as plaquetas nas primeiras horas de injúria tecidual."},"answer":"B","explanation":"Na fase inflamatória, as plaquetas asseguram o tampão e hemostasia; neutrófilos fazem a defesa celular imediata e macrófagos limpam a área e liberam citocinas fundamentais para conduzir a reparação."},{"id":"fases-05","examId":"fases","number":5,"stem":"A fase proliferativa da cicatrização é o período responsável pela reconstrução morfológica e recomposição de massa da ferida. Assinale a tríade de eventos biológicos primordiais que caracterizam essa fase:","options":{"A":"Vasoconstricção reflexa, hemostasia e apoptose celular.","B":"Degradação de colágeno, formação de queloide e atrofia epitelial.","C":"Síntese de colágeno por fibroblastos, angiogênese (formação de novos vasos) e epitelização por queratinócitos.","D":"Remodelação fibrilar por miofibroblastos exclusivamente após o sexto mês de pós-operatório."},"answer":"C","explanation":"Os três eixos da fase proliferativa são a síntese de colágeno (fibroblastos), a neovascularização ou angiogênese e a epitelização (migração de queratinócitos)."},{"id":"fases-06","examId":"fases","number":6,"stem":"Ao inspecionar o leito de uma ferida deixada para cicatrização por segunda intenção no 8º dia pós-trauma, o cirurgião observa uma superfície úmida, de coloração avermelhada brilhante, que sangra com facilidade ao toque suave da compressa. Essas características clínicas definem:","options":{"A":"Necrose de liquefação por bactérias anaeróbias.","B":"Tecido de granulação recém-formado na fase proliferativa.","C":"Deiscência fascial oculta com saída de líquido sinovial.","D":"Fase de remodelamento fibrilar maduro."},"answer":"B","explanation":"O tecido de granulação é composto por colágeno imaturo e intensa angiogênese em proliferação; é altamente vascularizado, avermelhado e sangra com facilidade à manipulação mecânica."},{"id":"fases-07","examId":"fases","number":7,"stem":"A fase de maturação é a etapa mais prolongada do processo cicatricial, estendendo-se por meses a até cerca de um ano. A contração fisiológica que reduz a área da ferida nessa fase decorre primariamente da ação dos:","options":{"A":"Queratinócitos basais.","B":"Miofibroblastos.","C":"Neutrófilos polimorfonucleares.","D":"Plasmócitos ativados."},"answer":"B","explanation":"Os fibroblastos sob estímulo diferenciam-se em miofibroblastos, cujas propriedades contráteis aproximam as bordas da ferida e reduzem a área da cicatriz durante o remodelamento."},{"id":"fases-08","examId":"fases","number":8,"stem":"Paciente portador de doença inflamatória intestinal em uso crônico de prednisona 40 mg/dia é submetido a uma enterectomia de urgência. O uso prolongado de altas doses de corticosteroides prejudica o processo de cicatrização porque:","options":{"A":"Estimula a proliferação excessiva de mastócitos e a produção exagerada de colágeno tipo I.","B":"Deprime a resposta inflamatória inicial e interfere negativamente na síntese de colágeno.","C":"Acelera a fase proliferativa de maneira incontrolável, gerando invariavelmente contraturas articulares.","D":"Causa vasodilatação permanente impedindo a hemostasia primária do tampão plaquetário."},"answer":"B","explanation":"Glicocorticoides em doses elevadas possuem potente ação imunossupressora e anti-inflamatória, deprimindo a migração leucocitária inicial e inibindo a síntese e deposição de colágeno."},{"id":"fases-09","examId":"fases","number":9,"stem":"A deficiência de micronutrientes compromete etapas específicas da reparação tissular. A hipovitaminose C afeta clinicamente a cicatrização ao interferir de forma direta no seguinte mecanismo:","options":{"A":"Na migração inicial de polimorfonucleares na fase inflamatória.","B":"Na síntese e hidroxilação das cadeias de colágeno durante a fase proliferativa.","C":"Na ação contrátil dos miofibroblastos na fase de maturação tardia.","D":"Na formação mecânica da fibrina durante a agregação plaquetária inicial."},"answer":"B","explanation":"O ácido ascórbico (vitamina C) é cofator indispensável para a hidroxilação de prolina e lisina na síntese das fibras de colágeno pelos fibroblastos na fase proliferativa."},{"id":"fases-10","examId":"fases","number":10,"stem":"Homem de 22 anos, pardo, procura ambulatório com queixa de lesão cicatricial no lóbulo da orelha após colocação de brinco. A lesão mede cerca de 3 cm, é nodular, firme, avermelhada e ultrapassa largamente o trajeto do furo original. Em relação ao queloide e seu diagnóstico diferencial com a cicatriz hipertrófica, assinale a opção correta:","options":{"A":"A cicatriz hipertrófica ultrapassa os limites da incisão inicial, enquanto o queloide permanece restrito às bordas da lesão.","B":"O queloide respeita os limites da ferida e regride invariavelmente após seis semanas de observação clínica.","C":"O queloide ultrapassa os limites da lesão inicial, cresce de forma contínua/irregular, tem forte correlação genética e raramente involui de forma espontânea.","D":"Ambas as lesões são perfeitamente idênticas e tratadas exclusivamente com ressecção cirúrgica simples em centro ambulatorial."},"answer":"C","explanation":"O queloide é marcado por crescimento excessivo desordenado que ultrapassa os limites da lesão primária, não regride espontaneamente e guarda relação com predisposição individual/genética."},{"id":"fases-11","examId":"fases","number":11,"stem":"Paciente de 45 anos sofreu queimadura térmica profunda na face flexora do punho e antebraço esquerdo tratada conservadoramente sem enxerto. Um ano após o acidente, o paciente apresenta retração severa da pele local que impede a extensão completa do punho e articulações da mão. Essa complicação cicatricial resultante da hiperatividade de miofibroblastos em áreas de flexão é denominada:","options":{"A":"Úlcera de Marjolin.","B":"Queloide séssil.","C":"Contratura cicatricial.","D":"Alargamento cicatricial atrófico."},"answer":"C","explanation":"A contratura cicatricial é uma retração patológica exacerbada mediada por miofibroblastos, típica de grandes queimaduras ou feridas em superfícies articulares/flexoras, gerando limitação funcional."},{"id":"fases-12","examId":"fases","number":12,"stem":"Uma paciente no 30º dia de pós-operatório de mastopexia relata à equipe que sua cicatriz cirúrgica começou a escurecer significativamente após caminhadas matinais ao ar livre sem proteção. Sobre as alterações de pigmentação cicatriciais, é correto afirmar:","options":{"A":"A hiperpigmentação pós-inflamatória pode ser exacerbada pela exposição precoce aos raios solares sobre a cicatriz ainda imatura, recomendando-se proteção solar adequada.","B":"O escurecimento é irreversível e reflete malignização espinocelular imediata.","C":"Toda cicatriz imatura deve receber exposição solar diária para estimular o remodelamento dos melanócitos.","D":"A hipopigmentação com vitiligo é o desfecho universal em pacientes submetidos a fechamento por primeira intenção."},"answer":"A","explanation":"A radiação solar sobre o tecido cicatricial imatura ainda hiperemiado induz hiperpigmentação pós-inflamatória; indica-se rigorosa fotoproteção tópica prolongada."},{"id":"fases-13","examId":"fases","number":13,"stem":"Paciente idoso, 68 anos, apresenta úlcera crônica decorrente de queimadura térmica sofrida há mais de 25 anos na perna. A lesão nunca cicatrizou completamente, mantendo ciclos recorrentes de inflamação e renovação celular. Nos últimos meses, as bordas tornaram-se evertidas, vegetantes e ulceradas com odor fétido. Qual complicação maligna deve ser suspeitada nesse caso?","options":{"A":"Melanoma nodular amelanótico.","B":"Sarcoma de partes moles pós-traumático.","C":"Carcinoma espinocelular (úlcera de Marjolin).","D":"Linfoma cutâneo secundário."},"answer":"C","explanation":"A úlcera de Marjolin corresponde à degeneração maligna (mais comumente carcinoma de células escamosas/espinocelular) que se instala sobre cicatrizes crônicas, úlceras de longa data ou sequelas de queimaduras com renovação celular persistente."},{"id":"fases-14","examId":"fases","number":14,"stem":"A perfusão vascular adequada é um dos pré-requisitos biológicos fundamentais para o sucesso de todas as fases da cicatrização. Assinale a condição clínica que compromete a cicatrização devido à hipóxia tecidual e déficit de aporte arterial crônico:","options":{"A":"Hipertensão venosa com estase pura em maléolo medial.","B":"Doença arterial obstrutiva periférica (isquemia crônica de membro).","C":"Síndrome nefrótica com hipoalbuminemia isolada.","D":"Hipovitaminose D subclínica."},"answer":"B","explanation":"A insuficiência arterial periférica impede o fluxo sanguíneo nutricional, privando o tecido lesado de oxigênio e nutrientes indispensáveis para a reparação, impedindo a cicatrização."},{"id":"fases-15","examId":"fases","number":15,"stem":"Em cirurgia de urgência por trauma abdominal grave com grande contaminação fecal e edema expressivo de alças intestinais, a aproximação forçada da parede abdominal pode desencadear síndrome compartimental abdominal. A estratégia de manter a parede abdominal temporariamente aberta para controle posterior da cavidade é denominada:","options":{"A":"Peritoneostomia.","B":"Laparorrafia simples em massa.","C":"Síntese por primeira intenção imediata.","D":"Gastropexia profilática."},"answer":"A","explanation":"A manutenção voluntária da cavidade peritoneal aberta protegida temporariamente por curativos/bolsas antes da síntese definitiva para prevenir hipertensão intra-abdominal chama-se peritoneostomia."},{"id":"isc-01","examId":"isc","number":1,"stem":"Um paciente do sexo masculino, 58 anos, foi submetido a uma artroplastia total de quadril eletiva sem intercorrências imediatas. Sessenta dias após a cirurgia, ele procura o ambulatório de ortopedia queixando-se de dor local progressiva, calor, hiperemia e dificuldade para deambular. Diante da suspeita de infecção relacionada a implantes, qual é o período preconizado para o acompanhamento e diagnóstico de infecção cirúrgica na presença de corpos estranhos (como próteses ou telas)?","options":{"A":"Até 7 dias de pós-operatório.","B":"Até 30 dias de pós-operatório.","C":"Até 3 meses pós-operatórios.","D":"Exclusivamente durante o período de internação hospitalar."},"answer":"C","explanation":"As infecções do sítio cirúrgico podem se manifestar em até 30 dias após o ato cirúrgico na ausência de implantes; contudo, quando há implantação de corpos estranhos (próteses ortopédicas, vasculares, telas de hérnia), o período de acompanhamento e vigilância estende-se por até 3 meses (ou até 1 ano segundo convenções adicionais)."},{"id":"isc-02","examId":"isc","number":2,"stem":"Durante uma cirurgia de grande porte com cavidade abdominal aberta e duração superior a 5 horas, a equipe cirúrgica e anestésica deve adotar cuidados rigorosos para a manutenção da temperatura corporal do paciente. Em relação à hipotermia e seus efeitos no doente cirúrgico, assinale a afirmativa correta:","options":{"A":"A hipotermia é protetora contra infecções por estimular de forma imediata a fagocitose neutrofílica.","B":"A infusão de grandes volumes de soros não aquecidos e a exposição prolongada ao ambiente cirúrgico favorecem a hipotermia, que prejudica o funcionamento das células de defesa.","C":"O uso de mantas térmicas é contraindicado em cirurgias abdominais pelo risco de queimadura de órgãos internos.","D":"A temperatura corporal não interfere na suscetibilidade a infecções bacterianas pós-operatórias."},"answer":"B","explanation":"A hipotermia prejudica diretamente a resposta imune celular, diminuindo a quimiotaxia e a fagocitose neutrofílica, além de favorecer vasoconstrição reflexa periférica. A infusão de fluidos aquecidos e o uso de mantas térmicas são essenciais para manter a normotermia."},{"id":"isc-03","examId":"isc","number":3,"stem":"Paciente de 45 anos é internado na emergência com quadro de abdome agudo perfurativo após sofrer ferimento por arma de fogo no abdome, apresentando extravasamento maciço de secreção entérica e fezes na cavidade peritoneal. Conforme o grau e o controle da contaminação tecidual, esse procedimento deve ser classificado como cirurgia:","options":{"A":"Limpa.","B":"Potencialmente contaminada.","C":"Contaminada.","D":"Infectada."},"answer":"C","explanation":"Cirurgias contaminadas são aquelas em que ocorre contaminação grosseira e descontrolada de vísceras ocas ou extravasamento entérico/fecal em cavidades estéreis decorrente de trauma agudo."},{"id":"isc-04","examId":"isc","number":4,"stem":"Em relação à classificação das feridas cirúrgicas quanto ao potencial de contaminação na apendicite aguda, assinale a alternativa que apresenta a correlação correta:","options":{"A":"Apendicite aguda não rota com abscesso bloqueado é considerada cirurgia limpa.","B":"Apendicite inflamada sem ruptura e sem pus na cavidade é contaminada; já a apendicite complicada com abscesso ou perfuração é infectada.","C":"Qualquer intervenção no apêndice vermiforme é considerada cirurgia limpa.","D":"Apendicite perfurada com peritonite generalizada enquadra-se como potencialmente contaminada."},"answer":"B","explanation":"A apendicite não perfurada (inflamação aguda sem pus livre ou necrose rompida) é enquadrada como cirurgia contaminada. Ao evoluir com supuração grosseira, abscesso periapendicular ou perfuração com peritonite purulenta, classifica-se como cirurgia infectada."},{"id":"isc-05","examId":"isc","number":5,"stem":"Você está no centro cirúrgico se preparando para instrumentar uma hernioplastia inguinal. Ao inspecionar a caixa cirúrgica fornecida pela Central de Material e Esterilização (CME), você percebe que a embalagem de papel grau cirúrgico encontra-se molhada na base. Diante dessa situação, qual deve ser a conduta correta?","options":{"A":"Secar a embalagem com compressa estéril e utilizar o material normalmente.","B":"Pulverizar álcool a 70% na superfície externa e liberar para o ato cirúrgico.","C":"Rejeitar o material e encaminhá-lo para novo ciclo de esterilização, pois a embalagem molhada viola a barreira asséptica.","D":"Usar o instrumental rapidamente antes que a umidade alcance a parte interna."},"answer":"C","explanation":"Embalagens estéreis com sinais de umidade ou molhadas perdem a capacidade de filtragem e barreira biológica contra microrganismos externos. O material é considerado contaminado e deve retornar à CME para reprocessamento."},{"id":"isc-06","examId":"isc","number":6,"stem":"Paciente do sexo feminino, 32 anos, no 5º dia pós-operatório de cesariana, retorna ao pronto-socorro com queixa de dor e secreção na ferida. Ao exame físico: hiperemia restrita às bordas cutâneas, saída de secreção purulenta e calor local, sem acometimento de fáscia, músculo ou cavidade. O diagnóstico correto é:","options":{"A":"Infecção do sítio cirúrgico superficial.","B":"Infecção do sítio cirúrgico profunda.","C":"Infecção de órgão ou cavidade.","D":"Celulite estéril de planos profundos."},"answer":"A","explanation":"A infecção do sítio cirúrgico incisional superficial restringe-se à pele e tecido celular subcutâneo logo acima da fáscia de revestimento."},{"id":"isc-07","examId":"isc","number":7,"stem":"Diferente das infecções incisionais superficiais, a infecção do sítio cirúrgico profunda atinge planos subjacentes. Quais estruturas anatômicas estão classicamente envolvidas na definição de infecção profunda?","options":{"A":"Apenas derme e epiderme.","B":"Fáscia e plano muscular.","C":"Tecidos de órgãos parenquimatosos exclusivamente.","D":"Pele e folículos pilosos adjacentes."},"answer":"B","explanation":"Por definição clássica de vigilância cirúrgica, as infecções incisionais profundas acometem a aponeurose (fáscia) e os feixes musculares manipulados na via de acesso cirúrgico."},{"id":"isc-08","examId":"isc","number":8,"stem":"Homem de 62 anos foi submetido a uma apendicectomia complicada por via laparoscópica. No 10º dia de pós-operatório, evolui com picos febris diários, dor em hipocôndrio direito e leucocitose com desvio à esquerda. A pele da ferida cirúrgica está sem sinais inflamatórios. Diante da suspeita de infecção de órgão ou espaço (abscesso intra-abdominal residual), qual exame de imagem é fundamental para confirmação e planejamento da drenagem percutânea?","options":{"A":"Radiografia simples de tórax.","B":"Tomografia computadorizada de abdome.","C":"Densitometria óssea.","D":"Eletrocardiograma de esforço."},"answer":"B","explanation":"Abscessos intra-abdominais e pélvicos profundos (infecções de espaço/órgão) demandam tomografia de abdome contrastada para delimitação espacial e auxílio no posicionamento de drenos percutâneos."},{"id":"isc-09","examId":"isc","number":9,"stem":"Paciente diabético tipo 2, 54 anos, é admitido no ambulatório pré-operatório para agendamento de correção de hérnia umbilical eletiva. Traz exames laboratoriais que revelam glicemia de jejum de 290 mg/dL e hemoglobina glicada (HbA1c) de 12%. Qual a conduta cirúrgica adequada quanto à indicação cirúrgica?","options":{"A":"Operar de imediato, pois a hiperglicemia atua estimulando os fibroblastos.","B":"Adiar o procedimento eletivo e otimizar o controle glicêmico, pois níveis tão elevados elevam expressivamente o risco de infecções e crises hiperosmolares.","C":"Realizar o procedimento em caráter de urgência para impedir a piora do quadro metabólico.","D":"Prescrever antibioticoterapia profilática prolongada por 30 dias e liberar a cirurgia no dia seguinte."},"answer":"B","explanation":"Pacientes com hemoglobina glicada muito elevada (como HbA1c de 12%) apresentam disfunção leucocitária marcante e elevado risco de infecção e descompensação ácida metabólica pós-operatória. Em cirurgias eletivas, o procedimento deve ser suspenso até a compensação clínica."},{"id":"isc-10","examId":"isc","number":10,"stem":"A profilaxia antimicrobiana em cirurgia visa garantir concentração tecidual bactericida de antibiótico no momento da incisão e manipulação tecidual. O momento ideal preconizado para a infusão do antibiótico profilático (como a cefazolina) é:","options":{"A":"24 horas antes da internação hospitalar.","B":"Geralmente 60 minutos antes do início do procedimento cirúrgico (incisão).","C":"Apenas após o fechamento da pele (síntese cirúrgica).","D":"No momento da alta hospitalar em formulação oral."},"answer":"B","explanation":"A infusão do antibiótico na profilaxia cirúrgica deve ocorrer tipicamente até 60 minutos antes da incisão da pele, assegurando concentrações teciduais acima da concentração inibitória mínima (CIM) durante todo o ato operatório."},{"id":"isc-11","examId":"isc","number":11,"stem":"Durante uma cirurgia de ressecção hepática complexa, o procedimento se estende por mais de 5 horas e há perda sanguínea estimada de 1.500 mL. Considerando os princípios da profilaxia antimicrobiana, qual a recomendação em relação ao antibiótico administrado no pré-operatório?","options":{"A":"Suspender os antibióticos definitivamente para evitar nefrotoxicidade.","B":"Repetir a dose do antibiótico profilático intraoperatório, considerando a meia-vida da droga, o sangramento volumoso e o tempo cirúrgico estendido.","C":"Substituir por quimioterápicos tópicos diretamente na loja cirúrgica.","D":"Manter apenas bochechos com antisséptico bucal a cada 2 horas."},"answer":"B","explanation":"Cirurgias com tempo cirúrgico que ultrapassa a meia-vida do fármaco ou perdas hemorrágicas expressivas diluem os níveis séricos e teciduais do antibiótico, exigindo doses de repetição intraoperatórias."},{"id":"isc-12","examId":"isc","number":12,"stem":"A tricotomia cirúrgica é uma medida de preparo do paciente que, se executada de forma incorreta, pode aumentar significativamente o risco de infecção de sítio cirúrgico. Sobre a tricotomia correta, assinale a opção correta:","options":{"A":"Deve ser realizada pelo paciente em seu domicílio com lâmina de barbear na véspera da cirurgia.","B":"Não deve ser realizada com lâmina, mas sim com tricotomizador elétrico, imediatamente antes do procedimento e sem lesar a integridade cutânea.","C":"Deve ser realizada de forma ampla com raspagem vigorosa da pele 3 dias antes da internação.","D":"O uso de lâmina é recomendado em todo o corpo para eliminar totalmente a camada córnea."},"answer":"B","explanation":"O uso de lâminas de barbear na véspera produz microlesões epiteliais que servem como porta de entrada e nicho de colonização para germes da pele. A remoção deve ser realizada apenas se estritamente necessária, no bloco cirúrgico, com tricotomizador elétrico sem corte na pele."},{"id":"isc-13","examId":"isc","number":13,"stem":"Um dos objetivos fundamentais das comissões de controle de infecção hospitalar (CCIH) no ambiente cirúrgico é:","options":{"A":"Desestimular a coleta de culturas e o uso de dados de sensibilidade institucional.","B":"Determinar o uso indiscriminado de antibióticos de amplo espectro para todos os pacientes cirúrgicos limpos.","C":"Estabelecer diretrizes, supervisionar o uso racional de antibióticos e vigiar as práticas assépticas com base no perfil bacteriológico institucional.","D":"Impedir a realização de qualquer cirurgia eletiva em pacientes com mais de 40 anos."},"answer":"C","explanation":"A CCIH possui papel estratégico no monitoramento epidemiológico dos germes prevalentes da unidade, criação de protocolos de profilaxia e verificação das rotinas de assepsia da equipe assistencial."},{"id":"isc-14","examId":"isc","number":14,"stem":"Paciente no 6º dia de pós-operatório de drenagem de abscesso perianal procura o pronto-atendimento com tumoração flutuante, hiperemiada, dolorosa e tensa na ferida operatória. Diante da presença de um abscesso na ferida com flutuação evidente, a conduta primária e resolutiva deve ser:","options":{"A":"Manter curativo oclusivo estéril e prescrever corticoterapia sistêmica.","B":"Indicar drenagem imediata da coleção purulenta associada ao desbridamento de tecidos desvitalizados, não sendo o antibiótico isolado suficiente.","C":"Aguardar reabsorção espontânea da coleção sem manipular a região.","D":"Realizar compressas mornas oclusivas por 3 semanas sem abrir os tecidos."},"answer":"B","explanation":"Coleções purulentas fechadas (abscessos) com flutuação exigem drenagem cirúrgica e toalete local para descompressão mecânica do foco infeccioso. Antibióticos tópicos ou sistêmicos não têm penetração efetiva sem a drenagem."},{"id":"isc-15","examId":"isc","number":15,"stem":"Em relação aos conceitos de desbridamento de feridas cirúrgicas infectadas e complicadas, por que a remoção do tecido necrosado e desvitalizado é mandatória?","options":{"A":"Para impedir a entrada de oxigênio gasoso na derme.","B":"Porque o tecido necrosado impede a formação e proliferação do tecido de granulação e perpetua o foco bacteriano.","C":"Porque o tecido desvitalizado substitui os macrófagos na hemostasia.","D":"Para facilitar a formação de biofilme sobre as camadas aponeuróticas."},"answer":"B","explanation":"O tecido necrosado e a escara desvitalizada abrigam biofilmes e bactérias, impedindo a angiogênese tecidual e o surgimento do tecido de granulação saudável para a reparação da ferida."},{"id":"isc-16","examId":"isc","number":16,"stem":"Paciente admitido para hernioplastia inguinal eletiva refere febre há 2 dias, tosse produtiva e coriza intensa compatível com infecção respiratória aguda de vias aéreas. Qual é a conduta preconizada para este paciente?","options":{"A":"Realizar a cirurgia conforme agendado para cumprir a escala do bloco cirúrgico.","B":"Adiar o procedimento cirúrgico eletivo, tratar a infecção intercorrente e reagendar a cirurgia após melhora clínica completa.","C":"Dobrar a dose da profilaxia antimicrobiana e realizar a incisão na virilha.","D":"Operar em sala contaminada sob anestesia local sem proteção de vias aéreas."},"answer":"B","explanation":"Cirurgias eletivas devem ser adiadas na vigência de processos infecciosos agudos não controlados (como infecções de via aérea superior ou sistêmicas) para reduzir o risco de complicações respiratórias e disseminação microbiana hematogênica."},{"id":"isc-17","examId":"isc","number":17,"stem":"O cateterismo vesical de demora é um recurso frequentemente utilizado no intraoperatório para monitorização do débito urinário em cirurgias demoradas. Sobre os cuidados para evitar a infecção do trato urinário associada ao cateter, assinale a opção correta:","options":{"A":"O dispositivo deve ser mantido indefinidamente durante todo o internamento hospitalar por conveniência.","B":"A inserção dispensa técnica asséptica, pois a urina tem propriedades esterilizantes.","C":"O cateter deve ser reavaliado periodicamente e retirado o mais precocemente possível, logo que cessada a necessidade de monitorização.","D":"Deve-se irrigar o cateter vesical diariamente com antibióticos de reserva."},"answer":"C","explanation":"Dispositivos invasivos (sondas vesicais e drenos) são corpos estranhos que formam biofilme e portas de entrada bacteriana retrógrada para a bexiga. Devem ser sacados assim que a indicação de uso for resolvida."},{"id":"isc-18","examId":"isc","number":18,"stem":"A infecção de sítio cirúrgico que acomete próteses vasculares, ortopédicas ou telas cirúrgicas é considerada uma das complicações mais temidas. Isso ocorre primordialmente porque:","options":{"A":"Os materiais aloplásticos não sofrem contaminação bacteriana.","B":"O corpo estranho propicia a aderência bacteriana e a formação de biofilme, tornando a infecção refratária ao tratamento clínico isolado e exigindo frequentemente a retirada do material.","C":"As telas absorvem todo o antibiótico circulante, anulando a circulação sistêmica da droga.","D":"O biofilme acelera o crescimento epitelial normal, fechando a pele precocemente."},"answer":"B","explanation":"Superfícies inorgânicas de próteses propiciam a colonização e adesão de biofilmes polissacarídicos bacterianos. O biofilme impede a ação dos antimicrobianos e das células de defesa, necessitando em muitos casos da remoção cirúrgica do implante."},{"id":"isc-19","examId":"isc","number":19,"stem":"Em relação à classificação dos procedimentos cirúrgicos de acordo com o potencial de contaminação, assinale o exemplo típico de cirurgia considerada potencialmente contaminada:","options":{"A":"Correção primária de hérnia inguinal sem abertura de vísceras.","B":"Ressecção gástrica parcial (gastrectomia) realizada de maneira programada e controlada.","C":"Drenagem de abscesso retrocecal por apendicite perfurada.","D":"Laparotomia exploradora em ferimento por faca com fezes livres no peritônio."},"answer":"B","explanation":"Cirurgias potencialmente contaminadas manipulam tratos colonizados (digestivo, respiratório ou urinário) sob condições previsíveis, assépticas e com abertura mínima/controlada de seu lúmen (ex.: gastrectomia ou colecistectomia eletiva)."},{"id":"isc-20","examId":"isc","number":20,"stem":"A respeito da redução do risco de infecção hospitalar em pacientes cirúrgicos, uma medida organizacional amplamente recomendada é:","options":{"A":"Manter o paciente internado por pelo menos 14 dias antes da cirurgia eletiva para ambientação bacteriológica.","B":"Reduzir o tempo de internação pré-operatória, dando preferência para que o paciente interne no próprio dia do procedimento ou na véspera imediata.","C":"Prescrever antibióticos profiláticos desde a primeira consulta ambulatorial.","D":"Trocar o curativo pós-operatório a cada 30 minutos nas primeiras 48 horas."},"answer":"B","explanation":"Internações hospitalares pré-operatórias longas alteram a flora da pele do paciente, colonizando-a com microrganismos hospitalares multirresistentes. Reduzir o tempo de permanência pré-operatório é medida fundamental de prevenção."},{"id":"nomes-01","examId":"nomes","number":1,"stem":"Um paciente de 48 anos é admitido com abdome agudo perfurativo decorrente de úlcera péptica na parede anterior do estômago. O cirurgião realiza a sutura direta da lesão gástrica com fios inabsorvíveis. De acordo com a composição dos termos cirúrgicos, o procedimento realizado denomina-se:","options":{"A":"Gastrostomia","B":"Gastrotomia","C":"Gastrorrafia","D":"Gastroplastia"},"answer":"C","explanation":"O sufixo -rafia refere-se ao procedimento cirúrgico de sutura. A sutura cirúrgica de uma perfuração na parede gástrica é definida tecnicamente como gastrorrafia."},{"id":"nomes-02","examId":"nomes","number":2,"stem":"Durante o intraoperatório de um paciente com úlcera perfurada, a equipa cirúrgica depara-se com a necessidade de extirpar o grande omento para conseguir adequada visualização e manipulação do sítio lesado. A nomenclatura correta para a remoção cirúrgica desta estrutura anatómica é:","options":{"A":"Omentopexia","B":"Omentectomia","C":"Omentoplastia","D":"Omentociese"},"answer":"B","explanation":"O sufixo -ectomia expressa a extirpação, ablação ou retirada cirúrgica de um órgão ou parte dele. A retirada do grande omento corresponde a uma omentectomia."},{"id":"nomes-03","examId":"nomes","number":3,"stem":"Paciente de 62 anos, com história de úlcera gástrica crónica de pequena curvatura refratária ao tratamento farmacológico e com biópsia sugestiva de transformação neoplásica, é encaminhado para cirurgia. O plano cirúrgico envolve a ressecção parcial do estômago e a sua união direta ao jejuno para restabelecer o trânsito digestivo. Os procedimentos de ressecção e união entre os órgãos denominam-se, respetivamente:","options":{"A":"Gastrotomia e gastropexia","B":"Gastrectomia e gastroenteronanastomose","C":"Gastroplastia e enterorrafia","D":"Gastrostomia e enterocele"},"answer":"B","explanation":"A remoção cirúrgica de parte do estômago corresponde a uma gastrectomia (parcial) e a criação cirúrgica de anastomose direta entre a câmara gástrica e o jejuno denomina-se gastroenteronanastomose."},{"id":"nomes-04","examId":"nomes","number":4,"stem":"Um paciente de 72 anos, vítima de acidente vascular cerebral isquémico há 6 meses, evolui com disfagia grave e episódios repetidos de pneumonia aspirativa. A equipa médica indica a criação cirúrgica de uma abertura na parede gástrica comunicando-a com o meio externo para introdução de sonda de alimentação enteral. A este procedimento dá-se o nome de:","options":{"A":"Gastrostomia","B":"Gastrotomia","C":"Gastrorrafia","D":"Gastropexia"},"answer":"A","explanation":"O sufixo -stomia designa a fistulização, ou seja, a confecção cirúrgica de uma abertura ou boca comunicando um órgão cavitário ao meio externo ou a outro órgão; gastrostomia é a abertura do estômago para fixação de sonda de alimentação."},{"id":"nomes-05","examId":"nomes","number":5,"stem":"Durante a abordagem cirúrgica de um quadro obstrutivo por cálculo biliar intraluminal impactado no duodeno, o cirurgião procede a uma incisão na parede duodenal para extração do cálculo, fechando-a em seguida. O tempo cirúrgico correspondente à incisão simples do duodeno é denominado:","options":{"A":"Duodenostomia","B":"Duodenectomia","C":"Duodenotomia","D":"Duodenopexia"},"answer":"C","explanation":"O elemento terminal -tomia indica a realização de uma incisão ou corte cirúrgico numa estrutura anatómica. Abertura temporária do duodeno para remoção de um corpo estranho/cálculo seguida de sutura é uma duodenotomia."},{"id":"nomes-06","examId":"nomes","number":6,"stem":"Paciente de 58 anos apresenta queixa de astenia, perda ponderal não intencional e hematoquezia há 3 meses. A colonoscopia revelou uma lesão vegetante e ulcerada no cólon descendente. O cirurgião propõe a extirpação do segmento colónico acometido. Qual o termo cirúrgico adequado para a intervenção planeada?","options":{"A":"Colostomia transversa","B":"Colectomia esquerda","C":"Colectomia direita","D":"Sigmoidostomia terminal"},"answer":"B","explanation":"A ressecção operatória do cólon descendente/esquerdo para controle de neoplasia coloretal denomina-se colectomia esquerda."},{"id":"nomes-07","examId":"nomes","number":7,"stem":"Jovem de 21 anos é admitido no serviço de urgência com dor abdominal com 24 horas de evolução, inicialmente difusa e periumbilical, que migrou para a fossa ilíaca direita nas últimas 6 horas, acompanhada de febre e anorexia. Ao exame físico, apresenta sinal de descompressão brusca positivo. A intervenção cirúrgica curativa consiste na extirpação do apêndice cecal inflamado, denominada:","options":{"A":"Apendicotomia","B":"Apendicectomia","C":"Apendicostomia","D":"Apendicorrafia"},"answer":"B","explanation":"A remoção cirúrgica do apêndice vermiforme ou cecal utiliza a raiz que identifica a estrutura (apendic-) associada ao sufixo ablativo -ectomia, compondo o termo apendicectomia."},{"id":"nomes-08","examId":"nomes","number":8,"stem":"Mulher de 45 anos, com índice de massa corporal elevado, queixa-se de episódios recorrentes de dor em cólica no hipocôndrio direito com irradiação para a região escapular homolateral, tipicamente desencadeados após refeições ricas em gordura. O ultrassom de abdome confirma colelitíase sintomática. O procedimento cirúrgico indicado para extirpação da vesícula biliar é a:","options":{"A":"Colecistostomia","B":"Colecistectomia","C":"Colecistotomia","D":"Colangioplastia"},"answer":"B","explanation":"A extirpação cirúrgica da vesícula biliar doente por litíase sintomática recebe a denominação técnica de colecistectomia."},{"id":"nomes-09","examId":"nomes","number":9,"stem":"Paciente de 19 anos, do sexo masculino, é admitido com quadro de torção do cordão espermático direito com evolução de 14 horas. Na exploração cirúrgica por via escrotal, constata-se necrose isquémica irreversível do testículo afetado. O cirurgião realiza a ablação do testículo direito e fixa preventivamente o testículo contralateral à bolsa escrotal. A descrição correta dos procedimentos é, respetivamente:","options":{"A":"Orquidotomia e orquidociese","B":"Orquiectomia e orquidopexia","C":"Orquidostomia e orquidoplastia","D":"Orquidocentese e orquidodese"},"answer":"B","explanation":"A remoção/ablação cirúrgica do testículo inviável chama-se orquiectomia; o procedimento de ancoramento ou fixação cirúrgica preventiva do testículo contralateral à bolsa escrotal denomina-se orquidopexia."},{"id":"nomes-10","examId":"nomes","number":10,"stem":"Mulher de 28 anos, nulípara, dá entrada em choque hemorrágico com diagnóstico de gravidez ectópica rota na trompa uterina esquerda. É submetida a laparotomia exploradora imediata com remoção cirúrgica total da tuba uterina rota. A intervenção cirúrgica denomina-se:","options":{"A":"Ooforectomia","B":"Histerectomia","C":"Salpingectomia","D":"Salpingostomia"},"answer":"C","explanation":"A excisão ou extirpação da tuba uterina acometida (por exemplo, numa gravidez ectópica rota) denomina-se salpingectomia."},{"id":"nomes-11","examId":"nomes","number":11,"stem":"Homem de 67 anos apresenta hematúria macroscópica indolor. A tomografia computadorizada e a cistoscopia evidenciam um carcinoma urotelial invasivo que infiltra a camada muscular da bexiga. O doente é submetido à ablação cirúrgica completa da bexiga urinária. A denominação correta deste procedimento é:","options":{"A":"Cistectomia","B":"Cistostomia","C":"Cistotomia","D":"Nefrorrafia"},"answer":"A","explanation":"A raiz médica para bexiga é cist-. A extirpação cirúrgica completa ou parcial do órgão por neoplasia urotelial invasiva recebe a denominação de cistectomia."},{"id":"nomes-12","examId":"nomes","number":12,"stem":"Paciente internado em unidade de terapia intensiva por choque séptico de foco abdominal evolui com retenção urinária aguda refratária. Diante do insucesso e da impossibilidade anatómica de cateterismo uretral, o urologista decide criar uma comunicação direta e temporária da bexiga com o meio exterior na região suprapúbica por punção orientada, permitindo a descompressão e drenagem da urina. O procedimento cirúrgico realizado é uma:","options":{"A":"Cistectomia","B":"Cistostomia","C":"Cistopexia","D":"Cistoscopia"},"answer":"B","explanation":"A derivação e drenagem do conteúdo urinário da bexiga diretamente para o meio externo através de cateter inserido por punção suprapúbica chama-se cistostomia."},{"id":"nomes-13","examId":"nomes","number":13,"stem":"Um doente é admitido na sala de emergência com dispneia intensa e desvio de traqueia decorrente de pneumotórax hipertensivo. O médico assistente procede a uma punção descompressiva na cavidade pleural com agulha de grosso calibre para aspiração do ar retido. O sufixo utilizado na terminologia médica para designar a punção de uma cavidade ou órgão para aspiração diagnóstica ou terapêutica de fluidos é:","options":{"A":"-tomia","B":"-centese","C":"-stomia","D":"-clase"},"answer":"B","explanation":"O sufixo -centese identifica manobras operatórias de punção diagnóstica ou terapêutica com esvaziamento de coleções fluidas orgânicas em cavidades (ex.: paracentese, toracocentese)."},{"id":"nomes-14","examId":"nomes","number":14,"stem":"Paciente vítima de traumatismo torácico penetrante dá entrada com instabilidade hemodinâmica, estase jugular e abafamento de sons cardíacos (tríade de Beck) decorrentes de hemopericárdio. A equipa de trauma realiza uma punção do saco pericárdico no ângulo subxifoideu com agulha e cateter para alívio imediato. Este procedimento tem como nomenclatura:","options":{"A":"Pericardiotomia de emergência","B":"Pericardiocentese","C":"Pericardiectomia subtotal","D":"Pericardiorrafia percutânea"},"answer":"B","explanation":"A aspiração de sangue ou fluido exsudativo do espaço pericárdico mediante agulha e seringa com o objetivo de descompressão do tamponamento cardíaco é denominada pericardiocentese."},{"id":"nomes-15","examId":"nomes","number":15,"stem":"Em doentes com ascite volumosa hipertensiva e restrição ventilatória por elevação da cúpula diafragmática, a retirada de líquido ascítico da cavidade peritoneal através de punção com agulha denomina-se:","options":{"A":"Paracentese","B":"Laparostomia","C":"Enterocentese","D":"Celiorrafia"},"answer":"A","explanation":"A punção transcutânea da cavidade peritoneal utilizando cânula ou agulha com a finalidade de evacuação ou amostragem de líquido ascítico denomina-se paracentese."},{"id":"nomes-16","examId":"nomes","number":16,"stem":"Na terminologia cirúrgica especializada, o sufixo -dese é empregue de forma precisa para caracterizar intervenções cirúrgicas cujo propósito primordial seja:","options":{"A":"A destruição ou dissolução enzimática de tecidos e aderências viscerais","B":"A imobilização, fixação definitiva ou fusão cirúrgica de uma articulação","C":"A moldagem e reconstrução morfológica e estética de uma estrutura","D":"A incisão simples seguida de sutura contínua de um órgão oco"},"answer":"B","explanation":"O sufixo -dese significa imobilização, artrodese ou fusão cirúrgica de uma articulação, eliminando o seu movimento patológico de forma intencional."},{"id":"nomes-17","examId":"nomes","number":17,"stem":"Um indivíduo de 40 anos apresenta hérnia discal cervical com instabilidade mecânica refratária e dor incoercível. O neurocirurgião realiza a discectomia seguida de fusão óssea articular com placas e parafusos para eliminar a mobilidade dolorosa do segmento cervical afetado. O termo técnico cirúrgico correto para designar esta imobilização articular é:","options":{"A":"Artrotomia cervical","B":"Artrodese","C":"Artroplastia biológica","D":"Osteoclase percutânea"},"answer":"B","explanation":"A fixação cirúrgica com fusão entre superfícies ósseas articulares contíguas (neste caso vértebras cervicais) com placas, enxertos e parafusos para estabilização anatómica definitiva denomina-se artrodese."},{"id":"nomes-18","examId":"nomes","number":18,"stem":"Doente portador de sequelas pleuropulmonares de empiema prévio é submetido a procedimento operatório com o intuito de seccionar e libertar densas aderências fibrosas que aprisionavam a pleura visceral e parietal, restaurando a expansibilidade do pulmão. A libertação de aderências teciduais através do sufixo -lise é tipificada pela:","options":{"A":"Pleurodese química","B":"Pleuroclasia mecânica","C":"Pleurólise","D":"Pleurotomia por punção"},"answer":"C","explanation":"O sufixo -lise traduz dissolução, separação ou libertação de tecidos; pleurólise é a secção meticulosa de traves e aderências pleuropulmonares que mantêm o pulmão encarcerado."},{"id":"nomes-19","examId":"nomes","number":19,"stem":"Durante a resolução de um quadro de obstrução das vias biliares com impactação de cálculo no colédoco distal, recorre-se a uma técnica cirúrgica ou endoscópica que promove o esmagamento e fragmentação intraluminal do cálculo. O sufixo que significa a ação de esmagar, triturar ou fragmentar uma estrutura ou cálculo é:","options":{"A":"-tripsia","B":"-clase","C":"-elise","D":"-plastia"},"answer":"A","explanation":"O elemento de terminação -tripsia representa esmagamento, fragmentação mecânica ou trituração (ex.: litotripsia para cálculos; angiotripsia para vasos sanguíneos)."},{"id":"nomes-20","examId":"nomes","number":20,"stem":"Paciente queixa-se de excesso de pele e flacidez nas pálpebras superiores que comprometem o seu campo visual. É indicada cirurgia plástica reparadora para ressecar o excesso tegumentar e remodelar o contorno palpebral. O termo cirúrgico que define este procedimento é:","options":{"A":"Blefarotomia","B":"Blefaroplastia","C":"Blefarorrafia simples","D":"Blefaropexia medial"},"answer":"B","explanation":"O elemento de composição -plastia indica plastia, modelagem, reconstrução ou reparação da forma anatómica e funcional de uma estrutura; blefaroplastia é a cirurgia de reconstrução/remoção de excesso tecidual palpebral."},{"id":"nomes-21","examId":"nomes","number":21,"stem":"Paciente submetida a fratura óssea diafisária tratada inicialmente de forma conservadora evolui com consolidação viciosa acentuada e deformidade em varo grave. O ortopedista programa uma reintervenção cirúrgica com o objetivo de refraturar ou romper o calo ósseo deformado para restabelecer o alinhamento anatómico. A manobra de fraturar ou romper deliberadamente um tecido ósseo consolidado de forma patológica utiliza o elemento de formação:","options":{"A":"-tripsia","B":"-clase (ou -clasia)","C":"-dese","D":"-pexia"},"answer":"B","explanation":"Os elementos de formação terminológica -clase ou -clasia indicam a fraturação mecânica programada, quebra ou rotura controlada de um tecido ósseo consolidado defeituosamente para correção cirúrgica (ex.: osteoclase)."},{"id":"nomes-22","examId":"nomes","number":22,"stem":"No centro cirúrgico de um hospital universitário, o preceptor questiona o interno de medicina sobre o instrumental utilizado para a remoção e divisão controlada de fatias de pele de espessura parcial ou total para enxertia. O instrumento cirúrgico cortante desenhado especificamente com essa finalidade denomina-se:","options":{"A":"Dermátomo","B":"Histerómetro","C":"Bisturi ultrassónico harmónico","D":"Pinça de Kocher denteada"},"answer":"A","explanation":"O sufixo instrumental -tomo designa aparelhos desenhados para cortar tecidos; o dermátomo é o instrumento mecânico ou elétrico desenhado para obtenção uniforme de lâminas cutâneas para transplante em feridas abertas."},{"id":"nomes-23","examId":"nomes","number":23,"stem":"O instrumentador cirúrgico disponibiliza uma cânula graduada e metálica com ponta romba utilizada pelo ginecologista para mensurar a profundidade da cavidade uterina antes da introdução de dispositivos ou curetagens. O nome específico deste instrumento de medição é:","options":{"A":"Histeroscópio","B":"Histerómetro","C":"Enterótomo","D":"Paquímetro cutâneo"},"answer":"B","explanation":"O sufixo -metro refere-se aos aparelhos ou réguas graduadas para mensuração; o histerómetro afere com precisão em centímetros o eixo e comprimento da cavidade uterina."},{"id":"nomes-24","examId":"nomes","number":24,"stem":"Durante um procedimento operatório no centro cirúrgico, o assistente solicita à equipa uma \"gaze montada\". No jargão da técnica cirúrgica pré e intraoperatória, esse conceito técnico corresponde a:","options":{"A":"Compressas estéreis dobradas e presas por fita adesiva sobre o abdome do paciente","B":"Um chumaço de gaze firmemente fixado na extremidade de uma pinça cirúrgica, utilizado para limpeza da cavidade ou hemostasia por compressão","C":"Um rolo de gaze embebido em antimicrobianos para confecção de curativos compressivos externos","D":"Gazes de pequeno calibre dispostas ao longo da linha de síntese cutânea para remoção de pontos"},"answer":"B","explanation":"Denomina-se gaze montada o pequeno bloco ou chumaço de gaze mantido dobrado e apreendido com firmeza nas pontas de uma pinça longa, destinado a hemostasia compressiva pontual ou secagem de lojas cirúrgicas profundas."},{"id":"nomes-25","examId":"nomes","number":25,"stem":"No tempo de hemostasia e síntese de uma incisão profunda, o cirurgião chefe orienta o acadêmico a \"reparar\" um fio cirúrgico de sutura. Essa terminologia padronizada de tempo operatório significa:","options":{"A":"Cortar rente ao nó cirúrgico a porção terminal do fio de sutura","B":"Segurar as extremidades do fio com uma pinça cirúrgica, mantendo os pontos e cabos tracionados e identificados para segurança e controle","C":"Lavar a sutura com soro fisiológico sob alta pressão estéril","D":"Aplicar cola biológica sobre os nós cirúrgicos para reforço mecânico"},"answer":"B","explanation":"Na técnica cirúrgica, \"reparar\" significa segurar as extremidades de um fio cirúrgico de sutura com uma pinça cirúrgica hemostática sem cortar os seus cabos, facilitando o controle, a identificação dos planos e a tração do campo."},{"id":"nomes-26","examId":"nomes","number":26,"stem":"Ao conduzir uma dissecção meticulosa ao longo dos planos fasciais profundos sem seccionar estruturas nobres adjacentes, o cirurgião recorre ao \"deslocamento\". Na técnica cirúrgica clássica, o deslocamento refere-se a:","options":{"A":"A rotação inadvertida da mesa operatória durante a anestesia","B":"A separação cuidadosa de tecidos com os dedos ou com instrumental rombo para obtenção de acesso preciso às estruturas anatómicas","C":"A tração forçada do tecido celular subcutâneo que provoca deiscência imediata","D":"A exteriorização definitiva de alças intestinais através de laparostomias cirúrgicas"},"answer":"B","explanation":"Deslocamento cirúrgico é a manobra delicada de separação romba dos planos teciduais através da manipulação digital ou instrumental atraumático, permitindo criar corredores de acesso visual e tátil com mínima lesão vascular."},{"id":"nomes-27","examId":"nomes","number":27,"stem":"Em cirurgia de transplante e reparação tecidual, a obtenção de tecidos transferidos de um local para outro no próprio paciente recebe a denominação de enxerto autólogo (ou autoenxerto). Quando o tecido provém de outro doador da mesma espécie biológica, a nomenclatura cirúrgica sinónima consagrada é:","options":{"A":"Heteroenxerto","B":"Aloenxerto (ou enxerto homólogo)","C":"Xenoenxerto tecidual","D":"Autoimplante microvascular"},"answer":"B","explanation":"O tecido colhido de um indivíduo doador da mesma espécie biológica do recetor recebe a denominação técnica de enxerto homólogo ou aloenxerto (distinguindo-se do autoenxerto autólogo originado do próprio indivíduo)."},{"id":"nomes-28","examId":"nomes","number":28,"stem":"Paciente com neoplasia de cólon distal obstrutiva é submetido à ablação cirúrgica completa do cólon (colectomia total). Diante da impossibilidade de restabelecimento imediato do trânsito com o reto, o cirurgião decide exteriorizar a terminação do íleo distal através da parede abdominal. Essa fistulização intencional e temporária do íleo à pele denomina-se:","options":{"A":"Jejunostomia","B":"Cecostomia de alívio","C":"Ileostomia","D":"Ileotomia de descompressão"},"answer":"C","explanation":"O procedimento cirúrgico de abertura e fixação da luz do íleo distal à pele da parede abdominal para desvio do fluxo fecal denomina-se ileostomia."},{"id":"nomes-29","examId":"nomes","number":29,"stem":"Paciente vítima de ferimento por arma de fogo no abdome é admitido em choque hemorrágico. Na laparotomia exploradora, identifica-se uma laceração sangrante de 6 cm no lobo direito do fígado que não demanda ressecção hepática, sendo controlada exclusivamente com sutura hemostática do parênquima com fio absorvível. O termo correto para a sutura do tecido hepático é:","options":{"A":"Hepatectomia parcial","B":"Hepatorrafia","C":"Hepatostomia transcutânea","D":"Hepatotomia de drenagem"},"answer":"B","explanation":"A síntese ou sutura direta de ferimento do parênquima hepático com finalidade hemostática é denominada hepatorrafia."},{"id":"nomes-30","examId":"nomes","number":30,"stem":"Paciente portadora de endometriose profunda acometendo o reto e o cólon sigmoide com oclusão do lúmen intestinal é submetida à ressecção operatória do segmento colónico sigmoide afetado. O nome técnico e padronizado conferido a essa ressecção intestinal é:","options":{"A":"Sigmoidotomia com descompressão","B":"Sigmoidopexia parietal","C":"Sigmoidectomia","D":"Sigmoidociese laparoscópica"},"answer":"C","explanation":"A extirpação ou ressecção de um segmento acometido do cólon sigmoide compõe a intervenção técnica denominada sigmoidectomia."},{"id":"assepsia-01","examId":"assepsia","number":1,"stem":"Durante a discussão de casos clínicos no internato de cirurgia, o preceptor debate os conceitos biológicos fundamentais que diferenciam os processos de contaminação, colonização e infecção nos doentes operados. De acordo com a cadeia microbiológica cirúrgica, considera-se infeção quando há:","options":{"A":"Presença transitória de bactérias na ferida, sem divisão ou resposta imune.","B":"Presença de bactérias que se multiplicam ativamente e desencadeiam resposta inflamatória no hospedeiro.","C":"Colonização exclusiva por fungos saprófitas restrita ao estrato córneo íntegro.","D":"Presença de microrganismos viáveis com multiplicação in vitro sem quebra tecidual."},"answer":"B","explanation":"Define-se infeção pela presença de microrganismos patogénicos que se multiplicam ativamente nos tecidos e despertam uma resposta inflamatória e imunológica clínica do hospedeiro (diferenciando-se da contaminação transitória e da colonização sem resposta inflamatória)."},{"id":"assepsia-02","examId":"assepsia","number":2,"stem":"A pele humana alberga microrganismos agrupados em flora transitória e residente (permanente). Em relação à dinâmica de colonização e eliminação dessas duas populações bacterianas, assinale a opção correta:","options":{"A":"A flora residente aloja-se nas camadas superficiais da derme e é eliminada facilmente com água e sabão comum.","B":"A flora transitória coloniza camadas profundas da epiderme e só pode ser removida por radiação ionizante.","C":"A flora transitória ocupa as camadas superficiais da pele e é prontamente removível por lavagem com água e sabão ou fricção antisséptica.","D":"A flora permanente é totalmente erradicada de forma definitiva após a primeira escovação cirúrgica com clorexidina."},"answer":"C","explanation":"A flora transitória coloniza a camada mais superficial da derme e epiderme, sendo eliminada de forma rápida através da higiene simples com água e sabão comum ou por soluções antissépticas."},{"id":"assepsia-03","examId":"assepsia","number":3,"stem":"Um aluno do internato médico questiona a circulante sobre o tempo necessário de espera após a aplicação da solução tópica de iodopovidona (PVPI) antes da realização da diérese cutânea. Para assegurar a libertação gradativa do iodo ativo e a sua ação bactericida e bacteriostática plena, deve-se aguardar um tempo de contacto de:","options":{"A":"30 segundos","B":"1 minuto","C":"3 minutos","D":"15 minutos"},"answer":"C","explanation":"Os compostos iodados tópicos (iodóforos como o PVPI) requerem um tempo mínimo de contacto com a pele de cerca de 3 minutos para secagem e libertação gradual do iodo livre, garantindo ação antimicrobiana bactericida."},{"id":"assepsia-04","examId":"assepsia","number":4,"stem":"Na escolha da solução antisséptica para a preparação do campo operatório de pacientes submetidos a cirurgias prolongadas, o gluconato de clorexidina destaca-se em relação aos compostos iodados principalmente por:","options":{"A":"Apresentar excelente ação residual (efeito residual por até cerca de 4 horas) e raramente causar reações alérgicas cutâneas.","B":"Ser um gás incolor com alto potencial esporicida em meio aquoso frio.","C":"Evaporar instantaneamente sem necessidade de secagem prévia.","D":"Atuar exclusivamente sobre bactérias anaeróbias estritas mediante desnaturação de lípidos."},"answer":"A","explanation":"O gluconato de clorexidina liga-se às proteínas do estrato córneo e apresenta elevada substantividade e ação residual (mantendo atividade bactericida residual por até 4 horas), associado a um baixo índice de alergias cutâneas."},{"id":"assepsia-05","examId":"assepsia","number":5,"stem":"O álcool etílico ou isopropílico é amplamente utilizado nos serviços de saúde hospitalares na concentração ideal de 70% a 90%. O mecanismo primordial de ação germicida do álcool sobre os microrganismos consiste em:","options":{"A":"Desidratação óssea por radiação fotoquímica focal.","B":"Desnaturação de proteínas da membrana plasmática acompanhada de lise celular rápida.","C":"Efeito residual prolongado de até 24 horas por evaporação lenta.","D":"Oxidação direta de esporos bacterianos pela formação de ozono."},"answer":"B","explanation":"O álcool (a 70%-90%) atua desnaturando as proteínas das membranas biológicas e da parede celular, provocando a lise bacteriana rápida; como evapora rapidamente, apresenta ação residual nula ou muito reduzida."},{"id":"assepsia-06","examId":"assepsia","number":6,"stem":"A esterilização é o processo que culmina na destruição de todas as formas de vida microscópica viáveis, incluindo os esporos bacterianos altamente resistentes. No bloco cirúrgico, o método físico de esterilização mais utilizado e acessível, que atua por meio do calor húmido, é o processo por:","options":{"A":"Estufa de ar quente estático (calor seco)","B":"Autoclave a vapor d'água sob pressão","C":"Flambagem direta em bico de Bunsen","D":"Radiação ultravioleta não ionizante"},"answer":"B","explanation":"A esterilização em autoclave que utiliza vapor de água sob pressão e alta temperatura constitui o método físico mais difundido, económico e seguro para artigos termorresistentes hospitalares."},{"id":"assepsia-07","examId":"assepsia","number":7,"stem":"A esterilização de materiais plásticos termossensíveis (como cateteres finos, óticas e componentes eletrónicos delicados) não pode ser realizada por autoclavação térmica convencional. Entre as alternativas gasosas e a baixa temperatura que não danificam materiais termossensíveis e não deixam resíduos tóxicos ambientais, destaca-se o uso do:","options":{"A":"Vapor de formol a quente","B":"Plasma de peróxido de hidrogénio (Sterrad)","C":"Gás mostarda ativado","D":"Dicromato de potássio diluído em autoclave"},"answer":"B","explanation":"O plasma de peróxido de hidrogénio opera a baixas temperaturas, apresenta alta capacidade bactericida e esporicida rápida e decompõe-se em água e oxigénio, não gerando emissões de resíduos tóxicos ambientais."},{"id":"assepsia-08","examId":"assepsia","number":8,"stem":"O óxido de etileno é um gás amplamente empregue nas Centrais de Material e Esterilização para artigos termossensíveis. Uma limitação crítica no manuseamento hospitalar deste gás reside no facto de:","options":{"A":"Destruir completamente qualquer instrumento metálico de aço inoxidável.","B":"Ser um gás incolor, inflamável e tóxico, exigindo cuidados rigorosos e aeração prolongada.","C":"Funcionar apenas a temperaturas acima de 180°C sob alta pressão.","D":"Atuar apenas como bacteriostático fraco incapaz de inativar vírus."},"answer":"B","explanation":"O óxido de etileno é um gás altamente eficaz para artigos plásticos termossensíveis, porém é inflamável, volátil, irritante e mutagénico/cancerígeno, necessitando de períodos mandatórios de aeração antes do contacto com o doente."},{"id":"assepsia-09","examId":"assepsia","number":9,"stem":"Nas unidades hospitalares, o ácido peracético tem sido empregue como método químico alternativo para reprocessamento rápido. Constitui uma característica técnica vantajosa do ácido peracético:","options":{"A":"Não oxidar ou danificar nenhum tipo de instrumental metálico.","B":"Apresentar ação rápida (esterilização em cerca de 30 minutos), baixa toxicidade, ser biodegradável e manter-se efetivo mesmo na presença de matéria orgânica.","C":"Exigir 24 horas contínuas de imersão estática para obter ação desinfetante.","D":"Ser um método físico dependente de radiação gama de cobalto."},"answer":"B","explanation":"O ácido peracético atua em ciclos rápidos (cerca de 30 minutos), é biodegradável, não produz subprodutos tóxicos persistentes e mantém boa eficácia antimicrobiana mesmo com resíduos orgânicos, embora tenha ação oxidante sobre certos metais."},{"id":"assepsia-10","examId":"assepsia","number":10,"stem":"Com o objetivo de disciplinar a circulação e mitigar os riscos de infeção cruzada, o centro cirúrgico é estruturado em três zonas de barreira com níveis crescentes de assepsia. A sala de expurgo — onde se processa a lavagem inicial dos instrumentais e o descarte de fluidos corporais — localiza-se na:","options":{"A":"Zona de proteção (não crítica / irrestrita)","B":"Zona limpa (semicrítica / semirrestrita)","C":"Zona asséptica (estéril / crítica)","D":"Zona neutra ultralimpa"},"answer":"A","explanation":"A sala de expurgo, o vestiário e a área de transferência de pacientes integram a chamada zona de proteção (não crítica ou irrestrita), que faz a transição entre a circulação hospitalar geral e o ambiente cirúrgico interno."},{"id":"assepsia-11","examId":"assepsia","number":11,"stem":"Um acadêmico precisa de aceder aos lavabos cirúrgicos e à sala de acondicionamento de material esterilizado para acompanhar a abertura das caixas. Essas dependências estão situadas na:","options":{"A":"Zona de proteção (irrestrita)","B":"Zona limpa (semicrítica ou semirrestrita)","C":"Zona estéril restrita de isolamento absoluto","D":"Área pública hospitalar externa"},"answer":"B","explanation":"Os lavabos cirúrgicos para degermação das mãos, o conforto médico, as salas de acondicionamento estéril e a RPA enquadram-se na zona limpa (semicrítica ou semirrestrita) do bloco."},{"id":"assepsia-12","examId":"assepsia","number":12,"stem":"A respeito da circulação nas dependências operatórias, a sala cirúrgica propriamente dita pertence à zona estéril (crítica ou restrita). Quais são os Equipamentos de Proteção Individual (EPIs) e barreiras obrigatórios para a permanência de qualquer pessoa na sala durante um procedimento cirúrgico?","options":{"A":"Roupa de uso pessoal da rua, bata plástica e óculos escuros.","B":"Pijama cirúrgico privativo, touca e máscara cirúrgica cobrindo nariz e boca.","C":"Luvas estéreis de látex e avental cirúrgico impermeável obrigatoriamente para todos os presentes na sala.","D":"Máscara N95 e propés estéreis descartáveis duplos sem pijama privativo."},"answer":"B","explanation":"Para adentrar e circular na zona estéril (sala cirúrgica), todo profissional deve obrigatoriamente trajar pijama cirúrgico privativo fornecido pela instituição, gorro protegendo os cabelos e máscara cobrindo boca e fossas nasais."},{"id":"assepsia-13","examId":"assepsia","number":13,"stem":"Um doente é admitido na véspera para correção eletiva de volumosa hérnia incisional. No que concerne aos cuidados de banho pré-operatório para redução da carga de microrganismos cutâneos antes do procedimento, a conduta recomendada inclui:","options":{"A":"Banho na véspera da cirurgia utilizando sabão com degermante, com higiene oral adequada e atenção especial às dobras cutâneas.","B":"Imersão corporal contínua em solução pura de iodopovidona alcoólica durante 4 horas antes da incisão.","C":"Não tomar banho nas 48 horas antecedentes para evitar a descamação acelerada da pele.","D":"Aplicação direta de pomadas com antibióticos de amplo espectro em toda a superfície do tronco."},"answer":"A","explanation":"Recomenda-se o banho pré-operatório com solução antisséptica ou sabão degermante na véspera do procedimento para redução da microbiota transitória da pele, com ênfase nas pregas e dobras corporais e higiene bucal."},{"id":"assepsia-14","examId":"assepsia","number":14,"stem":"A realização inadequada da tricotomia pré-operatória é uma das causas frequentes de colonização patológica e infeção incisional. Para prevenir complicações, a tricotomia deve ser executada:","options":{"A":"Em ambiente domiciliar pelo próprio doente, utilizando lâmina descartável de barbear cerca de 3 dias antes da cirurgia.","B":"No dia da intervenção cirúrgica, preferencialmente imediatamente antes do ato e com recurso a tricotomizador elétrico, evitando microlesões dérmicas.","C":"Com lâminas cirúrgicas afiadas tipo bisturi 24 horas antes do internamento.","D":"De forma ampla abrangendo os quatro membros, independentemente da área operatória."},"answer":"B","explanation":"A remoção de pelos deve ser evitada; se necessária, deve ser feita imediatamente antes da incisão, dentro do bloco, utilizando tricotomizadores elétricos que não causem microabrasões cutâneas."},{"id":"assepsia-15","examId":"assepsia","number":15,"stem":"Durante a antissepsia do sítio operatório no bloco cirúrgico, o assistente utiliza compressas estéreis embebidas em solução degermante. A técnica e a direção dos movimentos da degermação mecânica da pele devem seguir o sentido:","options":{"A":"Da periferia para o centro, trazendo os microrganismos periféricos para a linha de incisão.","B":"Do centro para a periferia da área cirúrgica, sendo que a gaze ou compressa utilizada nas extremidades não retorna à cuba ou ao centro.","C":"Circular e aleatório em vai-e-vem contínuo sem troca das gazes.","D":"Sentido cranial-caudal exclusivo através de fricção a seco sem enxaguamento prévio."},"answer":"B","explanation":"A antissepsia mecânica da pele deve obedecer rigorosamente à direção centrífuga (do ponto onde será feita a incisão em direção às margens periféricas), evitando contaminar o centro com gazes que já tocaram a periferia."},{"id":"assepsia-16","examId":"assepsia","number":16,"stem":"Para a realização de antissepsia pré-operatória das mucosas genital ou oral em pacientes que serão submetidos a intervenções ginecológicas ou orofaciais, a solução tópica de escolha não deve ser irritante aos tecidos. Nesse cenário, deve-se empregar:","options":{"A":"Álcool puro a 90% com fricção vigorosa.","B":"Solução tópica aquosa (não alcoólica) de clorexidina ou iodopovidona.","C":"Solução alcoólica de clorexidina a 2% diretamente sobre a mucosa exposta.","D":"Solução concentrada de ácido peracético a quente."},"answer":"B","explanation":"Em mucosas e genitália devem-se utilizar estritamente formulações aquosas tópicas (de clorexidina ou iodopovidona), pois as bases alcoólicas provocam queimaduras químicas, irritação e dor acentuada."},{"id":"assepsia-17","examId":"assepsia","number":17,"stem":"A colocação dos campos cirúrgicos estéreis delimitando o sítio operatório visa isolar as áreas não esterilizadas do corpo do paciente e criar uma barreira estéril de trabalho. Em relação à classificação dos tempos e técnicas cirúrgicas, a aposição dos campos estéreis é definida como uma medida de:","options":{"A":"Degermação química de contato.","B":"Assepsia cirúrgica profilática.","C":"Antissepsia mecânica por fricção.","D":"Esterilização tissular in vivo."},"answer":"B","explanation":"Assepsia compreende o conjunto de medidas adotadas para impedir a introdução de microrganismos em locais que não os contêm; a aposição de campos operatórios estéreis é um procedimento de barreira física que cumpre esse princípio."},{"id":"assepsia-18","examId":"assepsia","number":18,"stem":"Na escovação/degermação cirúrgica das mãos e antebraços, a correta aplicação do protocolo temporal e de direção mecânica é essencial para a remoção da flora transitória e redução da residente. As recomendações técnicas para a escovação cirúrgica incluem:","options":{"A":"Escovação no sentido proximal para distal (dos cotovelos para as mãos) durante 30 segundos.","B":"Escovação rigorosa das mãos e antebraços no sentido distal para proximal (mãos para os cotovelos) com duração de 3 a 5 minutos na primeira cirurgia.","C":"Lavagem rápida das mãos exclusivamente com soro fisiológico aquecido sem detergente.","D":"Escovação estática das unhas e palmas por 15 minutos contínuos com escovas de aço rígidas."},"answer":"B","explanation":"A escovação cirúrgica manual dura entre 3 e 5 minutos no primeiro procedimento operatório do dia e deve ser realizada das mãos para os antebraços e cotovelos (distal para proximal), para que a água e os resíduos fluam das áreas mais limpas para as menos limpas."},{"id":"assepsia-19","examId":"assepsia","number":19,"stem":"O uso de calçado de proteção e propés no centro cirúrgico sofreu revisões nas diretrizes de controlo de infeção hospitalar. De acordo com as normas contemporâneas do ambiente cirúrgico:","options":{"A":"O uso de propés descartáveis é o fator mais determinante para erradicar a infeção do sítio cirúrgico profundo.","B":"O propé já não é estritamente indicado de forma universal, preconizando-se o uso de calçado privativo e de uso exclusivo no bloco cirúrgico.","C":"O cirurgião deve calçar os propés diretamente sobre a pele despida sem sapatos.","D":"É obrigatório trocar os propés a cada 10 minutos durante o ato operatório."},"answer":"B","explanation":"Estudos demonstraram que o uso indiscriminado de propés não altera a taxa de infeção da ferida e pode dispersar bactérias pelas mãos durante a sua colocação e remoção; preconiza-se o uso de calçado fechado e lavável de uso exclusivo dentro do centro cirúrgico."},{"id":"assepsia-20","examId":"assepsia","number":20,"stem":"Após a correta escovação e secagem asséptica das mãos com compressa estéril, o cirurgião e o instrumentador procedem à paramentação cirúrgica estéril. A utilização de avental (capote) cirúrgico e de luvas estéreis constitui uma medida de:","options":{"A":"Antissepsia química por absorção dérmica continuada.","B":"Assepsia, funcionando como barreira mecânica estéril entre os membros da equipa cirúrgica e o doente.","C":"Desinfeção de alto nível por contacto tecidual fechado.","D":"Esterilização ativa da flora residente do cirurgião durante o ato cirúrgico."},"answer":"B","explanation":"Aventais e luvas estéreis constituem equipamentos de barreira de assepsia para proteger o campo cirúrgico da contaminação pela microbiota da equipa e, simultaneamente, proteger os profissionais de contacto com fluidos biológicos do doente."},{"id":"tempos-01","examId":"tempos","number":1,"stem":"Durante uma intervenção laparoscópica para colecistectomia eletiva, o cirurgião necessita de criar o pneumoperitoneu através da insuflação de dióxido de carbono (CO₂) e, de seguida, estabelecer vias de trabalho para a introdução da ótica e das pinças. Quais são os instrumentais indicados, respetivamente, para a punção/insuflação inicial e para a manutenção das vias de acesso laparoscópico?","options":{"A":"Trocarte e agulha de Reverdin","B":"Agulha de Veress e trocarte","C":"Agulha de Jelco e cânula de Yankauer","D":"Agulha hipodérmica e afastador de Doyen"},"answer":"B","explanation":"Na cirurgia laparoscópica, a punção para insuflação peritoneal de dióxido de carbono (CO₂) e criação de pneumoperitoneu é realizada com a agulha de Veress; subsequentemente, a introdução dos trocartes assegura as portas de trabalho para a ótica e os instrumentais."},{"id":"tempos-02","examId":"tempos","number":2,"stem":"Um paciente com traumatismo torácico fechado dá entrada na emergência com quadro de pneumotórax volumoso hipertensivo. O médico decide pela colocação de um dreno tubular de tórax. Para aceder à cavidade pleural através dos espaços intercostais, o cirurgião afasta as fibras da musculatura intercostal sem as cortar, utilizando uma pinça de ponta romba. Esse procedimento mecânico de diérese denomina-se:","options":{"A":"Secção","B":"Descolamento","C":"Divulsão","D":"Curetagem"},"answer":"C","explanation":"Divulsão é a manobra de diérese mecânica que consiste em separar ou afastar os tecidos ao longo dos seus planos anatómicos naturais sem secção ou corte, habitualmente executada com tesouras de ponta romba ou pinças hemostáticas."},{"id":"tempos-03","examId":"tempos","number":3,"stem":"No tempo operatório de diérese mecânica, a escolha adequada do cabo e da lâmina de bisturi é indispensável para a precisão técnica. Para a realização de incisões amplas e profundas no abdómen ou no tronco, empregam-se lâminas cirúrgicas maiores montadas em cabo específico. Assinale a associação correta entre o cabo de bisturi e a sua utilização padronizada:","options":{"A":"Cabo nº 3 para lâminas maiores; cabo nº 4 para lâminas menores.","B":"Cabo nº 4 para lâminas maiores; cabo nº 3 para lâminas menores.","C":"Cabo nº 3 exclusivo para corte ósseo; cabo nº 4 para ressecção de mucosas delicadas.","D":"Cabos nº 3 e nº 4 utilizam indistintamente o mesmo encaixe e os mesmos tamanhos de lâminas."},"answer":"B","explanation":"O cabo de bisturi nº 4 é desenhado para acomodar lâminas cirúrgicas maiores (utilizadas em incisões amplas no abdómen e tronco), enquanto o cabo nº 3 é reservado para lâminas menores destinadas a dissecções e incisões delicadas."},{"id":"tempos-04","examId":"tempos","number":4,"stem":"Durante o ato operatório, o instrumentador deve fornecer as tesouras cirúrgicas de acordo com o tecido ou material manipulado. Se o cirurgião solicita um instrumento para a dissecção delicada de planos teciduais profundos e, em seguida, uma tesoura para cortar fios de sutura cirúrgica, o instrumentador deve passar, respetivamente:","options":{"A":"Tesoura de Mayo curva e tesoura de Metzenbaum reta","B":"Tesoura de Metzenbaum (curva/reta) e tesoura de Mayo reta","C":"Tesoura de Potts e tesoura de Metzenbaum curva","D":"Tesoura de Mayo reta e bisturi elétrico monopolar"},"answer":"B","explanation":"As tesouras de Metzenbaum (curvas ou retas) possuem lâminas finas e hastes longas desenhadas para a dissecção delicada de tecidos orgânicos; as tesouras de Mayo (especialmente a reta) são robustas e destinam-se ao corte de fios cirúrgicos e materiais."},{"id":"tempos-05","examId":"tempos","number":5,"stem":"A manipulação dos tecidos requer pinças de preensão com características anatómicas específicas para minimizar o trauma. Ao realizar a tração de retalhos de pele que serão subsequentemente ressecados numa área lesada, o cirurgião necessita de uma pinça de tração forte e considerada traumática. Qual instrumento corresponde a essa descrição?","options":{"A":"Pinça anatómica de dissecção simples","B":"Pinça de Kelly curva","C":"Pinça de Allis","D":"Pinça de Doyen intestinal"},"answer":"C","explanation":"A pinça de Allis possui dentes miúdos na extremidade que exercem preensão traumática forte, sendo classicamente utilizada na tração de tecidos que serão posteriormente excisados."},{"id":"tempos-06","examId":"tempos","number":6,"stem":"Para a fixação dos campos cirúrgicos estéreis entre si e à pele do paciente, delimitando o campo operatório, utiliza-se classicamente uma pinça de preensão e tração específica. Trata-se da pinça de:","options":{"A":"Kocher","B":"Backhaus","C":"Mixter","D":"Farabeuf"},"answer":"B","explanation":"A pinça de Backhaus é uma pinça de campo pontiaguda e perfurante, desenhada primariamente para apreender e fixar campos operatórios de tecido ou papel à derme do paciente."},{"id":"tempos-07","examId":"tempos","number":7,"stem":"Durante uma laparotomia exploradora mediana infraumbilical, a equipa necessita de afastar a parede abdominal de forma contínua sem depender da tração manual permanente do assistente. Entre os instrumentos abaixo, qual é classificado como um afastador autoestático?","options":{"A":"Afastador de Farabeuf","B":"Afastador de Doyen","C":"Afastador de Balfour (ou Gosset)","D":"Afastador de Roux"},"answer":"C","explanation":"Os afastadores de Balfour e Gosset possuem cremalheiras que mantêm a abertura da parede abdominal fixa de forma autónoma (autoestáticos), dispensando tração manual humana contínua."},{"id":"tempos-08","examId":"tempos","number":8,"stem":"Na técnica cirúrgica, os afastadores são categorizados em dinâmicos e autoestáticos. São exemplos de afastadores dinâmicos, cuja tração depende da força muscular contínua exercida pela equipa cirúrgica:","options":{"A":"Gosset e Balfour","B":"Farabeuf e Roux","C":"Afastador suprapúbico e Gosset","D":"Válvula de Doyen fixa e afastador de Balfour"},"answer":"B","explanation":"Farabeuf e Roux são afastadores manuais ou dinâmicos, que exigem que o assistente cirúrgico mantenha força contínua de tração para manter a exposição operatória."},{"id":"tempos-09","examId":"tempos","number":9,"stem":"A diérese física utiliza diferentes formas de energia para a divisão dos tecidos ou hemostasia concomitante. A modalidade que consiste no arrefecimento brusco e intenso de lesões cutâneas utilizando azoto líquido denomina-se:","options":{"A":"Termocoagulação monopolar","B":"Eletrocautério térmico","C":"Criocirurgia (crioterapia)","D":"Fotocoagulação por Laser CO₂"},"answer":"C","explanation":"A criocirurgia ou crioterapia baseia-se na aplicação de baixas temperaturas extremas (azoto líquido) para causar choque térmico e destruição tecidual localizada de lesões cutâneas."},{"id":"tempos-10","examId":"tempos","number":10,"stem":"Durante uma dissecção hepática ou cirurgia renal com sangramento difuso em toalha sobre o parênquima esponjoso, o cirurgião constata que os vasos seccionados não colapsam por inelasticidade do tecido. Para obter hemostasia definitiva, opta-se por aplicar uma substância exógena sobre a superfície sangrante (como cera óssea) para ocluir a luz vascular. Esta técnica hemostática denomina-se:","options":{"A":"Obturação","B":"Tamponamento","C":"Ligadura cirúrgica","D":"Fotocoagulação"},"answer":"A","explanation":"Obturação é a aplicação de substâncias sólidas ou pastosas insolúveis (como cera de osso cirúrgica) na superfície cruenta de parênquimas ou ossos esponjosos para tamponamento e oclusão direta dos orifícios vasculares."},{"id":"tempos-11","examId":"tempos","number":11,"stem":"A hemostasia é um dos tempos fundamentais da cirurgia, sendo dividida em temporária e definitiva. Assinale a alternativa que contém exclusivamente métodos de hemostasia definitiva:","options":{"A":"Compressão digital, garroteamento com faixa de Smarch e pinçamento vascular.","B":"Ligadura, cauterização térmica, sutura hemostática e grampeamento metálico.","C":"Uso de torniquete pneumático, tamponamento e oclusão endovascular por balão.","D":"Garroteamento proximal, hipotermia induzida e ação farmacológica vasoconstritora."},"answer":"B","explanation":"Métodos definitivos ocluem permanentemente a luz dos vasos através de laçadas cirúrgicas (ligadura), necrose de coagulação (eletrocautério), transfixação com fios (sutura) ou aposição mecânica definitiva (grampos). Garrotes, pinçamentos transitórios e tamponamentos são temporários."},{"id":"tempos-12","examId":"tempos","number":12,"stem":"Num paciente politraumatizado com hemorragia profusa numa extremidade, o cirurgião aplica uma faixa elástica compressiva (faixa de Smarch) na raiz do membro para interromper transitoriamente o aporte sanguíneo até o reparo vascular definitivo. Trata-se de um método de:","options":{"A":"Hemostasia cruenta definitiva","B":"Hemostasia temporária incruenta por garroteamento","C":"Obturação mecânica com tamponamento oclusivo","D":"Diérese física por compressão direta"},"answer":"B","explanation":"A compressão circunferencial da raiz de membros através da faixa elástica de Smarch constitui garroteamento incruento, método hemostático temporário para contenção de fluxos maciços até à abordagem direta do vaso."},{"id":"tempos-13","examId":"tempos","number":13,"stem":"Durante o isolamento e ligadura de vasos do pedículo hepático e renal em locais profundos e de acesso difícil, o cirurgião solicita uma pinça hemostática de ponta curva e ângulo pronunciado. O instrumento clássico indicado para hemostasia e dissecção em pedículos viscerais profundos é a pinça de:","options":{"A":"Kelly reta","B":"Crile","C":"Mixter","D":"Rochester curva"},"answer":"C","explanation":"A pinça de Mixter destaca-se por possuir ponta em ângulo acentuado quase reto em relação às suas hastes, o que permite contornar estruturas anatómicas curvas, pedículos renais e hepáticos em profundidade."},{"id":"tempos-14","examId":"tempos","number":14,"stem":"Diferentes pinças hemostáticas apresentam detalhes morfológicos nas suas ranhuras que determinam a sua indicação cirúrgica. A pinça hemostática que possui ranhuras transversais que ocupam toda a extensão das suas garras preensoras, sendo rotineiramente utilizada para fixar vasos e tecidos antes da cauterização ou ligadura, é a pinça de:","options":{"A":"Kelly (ranhuras em apenas metade da garra)","B":"Crile","C":"Allis denteada","D":"Backhaus"},"answer":"B","explanation":"A pinça de Crile possui ranhuras transversais em toda a extensão ativa das suas mandíbulas, diferindo da pinça de Kelly, cujas ranhuras ocupam apenas a metade distal da garra preensora."},{"id":"tempos-15","examId":"tempos","number":15,"stem":"Para o pinçamento e isolamento de estruturas vasculares mais robustas, pedículos espessos e manobras hemostáticas que exigem instrumentos mais pesados e firmes, a pinça de escolha é a:","options":{"A":"Pinça de Halsted (mosquito)","B":"Pinça de Rochester","C":"Pinça de Metzenbaum","D":"Pinça anatómica de dissecção com serrilha leve"},"answer":"B","explanation":"A pinça de Rochester é um instrumento cirúrgico robusto e espesso, desenhado para pinçar grandes volumes de tecido, vasos calibrosos e pedículos anatómicos volumosos."},{"id":"tempos-16","examId":"tempos","number":16,"stem":"Na abordagem intestinal, quando se objetiva interromper o fluxo intraluminal de conteúdo digestivo ou fezes (ecopostase) sem causar esmagamento isquémico da parede da ansa, utiliza-se:","options":{"A":"Pinça de Rochester curva com dentes de rato","B":"Pinça clamp intestinal atraumática (reto ou curvo)","C":"Pinça de Allis com tração máxima","D":"Pinça de Crile com cremalheira travada"},"answer":"B","explanation":"Os clamps intestinais possuem mandíbulas atraumáticas fenestradas ou elásticas com ranhuras longitudinais suaves, desenhados para comprimir o lúmen intestinal e impedir a passagem de fezes sem esmagar ou isquemiar a parede visceral."},{"id":"tempos-17","examId":"tempos","number":17,"stem":"A absorção dos fios cirúrgicos no organismo ocorre por diferentes mecanismos fisiopatológicos, dependendo da sua origem biológica ou sintética. O fio cirúrgico absorvível de origem biológica que sofre digestão enzimática por reação inflamatória do tipo corpo estranho é o:","options":{"A":"Ácido poliglicólico (Dexon)","B":"Catgut (simples ou cromado)","C":"Ácido poligaláctico (Vicryl)","D":"Polidioxanona (PDS)"},"answer":"B","explanation":"O categute (simples ou cromado) é extraído da submucosa intestinal ovina ou serosa bovina (origem biológica pura), sendo digerido pelas proteases e enzimas lisossómicas do organismo sob resposta de corpo estranho."},{"id":"tempos-18","examId":"tempos","number":18,"stem":"O ácido poliglicólico (Dexon) e o ácido poligaláctico (Vicryl) são amplamente empregues em cirurgia geral. Quanto às suas características de composição e mecanismo de degradação orgânica, ambos são classificados como fios:","options":{"A":"Biológicos, monofilamentares e absorvíveis por fagocitose celular.","B":"Sintéticos, multifilamentares e absorvíveis por hidrólise.","C":"Minerais, inabsorvíveis e degradados por oxidação tisular.","D":"Sintéticos, monofilamentares e degradados por dissolução proteolítica."},"answer":"B","explanation":"Dexon (ácido poliglicólico) e Vicryl (ácido poligaláctico) são polímeros sintéticos trançados (multifilamentares), cuja reabsorção fisiológica decorre do processo de hidrólise química tecidual neutra."},{"id":"tempos-19","examId":"tempos","number":19,"stem":"Em cirurgias intracavitárias na presença de peritonite purulenta e contaminação evidente, o cirurgião opta por um fio de sutura absorvível monofilamentar sintético com absorção lenta (90 a 180 dias), minimizando o risco de perpetuação do processo infecioso no sítio cirúrgico. Esse fio cirúrgico corresponde à:","options":{"A":"Seda trançada","B":"Polidioxanona (PDS)","C":"Linha de algodão multifilamentar","D":"Catgut simples de origem bovina"},"answer":"B","explanation":"A polidioxanona (PDS) é um fio sintético monofilamentar de absorção lenta; por ser de fio único e liso, não retém bactérias nas suas fibras, sendo vantajoso em campos cirúrgicos potencialmente infetados."},{"id":"tempos-20","examId":"tempos","number":20,"stem":"Os fios cirúrgicos inabsorvíveis orgânicos multifilamentares, como o algodão e a seda, possuem grande maleabilidade e excelente segurança nos nós. No entanto, a sua principal desvantagem biológica quando comparados aos fios sintéticos monofilamentares reside no facto de:","options":{"A":"Sofrerem degradação hidrolítica acelerada em menos de 24 horas.","B":"Apresentarem interstícios entre as suas fibras trançadas que abrigam bactérias e podem perpetuar processos infeciosos.","C":"Causarem retração isquémica irreversível de tecidos cartilagíneos.","D":"Não permitirem a passagem de agulhas cilíndricas atraumáticas."},"answer":"B","explanation":"Por serem orgânicos e multifilamentares, fios de algodão e seda retêm fluidos por capilaridade e comportam-se como nichos de acolhimento para bactérias entre os seus microfilamentos trançados."},{"id":"tempos-21","examId":"tempos","number":21,"stem":"Na síntese da pele em áreas de tensão ou em pequenas cirurgias ambulatoriais, a escolha do fio de sutura inabsorvível clássico recai frequentemente sobre o Nylon. As principais características que justificam a sua indicação para suturas cutâneas são:","options":{"A":"Ser monofilamentar, sintético, com grande resistência tênsil e provocar baixa reação tecidual.","B":"Ser multifilamentar biológico com alta absorção em meio aquoso.","C":"Ser absorvível em 7 dias com elasticidade plástica que dispensa nós cirúrgicos.","D":"Ser formado por colágeno puro de serosa animal bovina."},"answer":"A","explanation":"O nylon é o fio monofilamentar inabsorvível sintético de eleição para síntese de pele, pois a sua superfície lisa provoca reação tecidual celular desprezível e oferece alta resistência."},{"id":"tempos-22","examId":"tempos","number":22,"stem":"O polipropileno (Prolene) é um fio inabsorvível monofilamentar amplamente utilizado em cirurgias cardiovasculares e em suturas intradérmicas. Uma propriedade técnica marcante deste fio, associada à sua superfície lisa e memória plástica, é:","options":{"A":"Apresentar alta taxa de absorção por digestão proteolítica enzimática.","B":"Deslizar facilmente pelos tecidos com mínima reação tecidual, sendo de fácil remoção em suturas estéticas intradérmicas.","C":"Formar nós cirúrgicos firmes e definitivos sem risco de desfazimento espontâneo.","D":"Fixar colónias bacterianas permanentes no interior de tranças sintéticas."},"answer":"B","explanation":"O polipropileno (Prolene) é inerte, monofilamentar e possui baixo coeficiente de atrito superficial, deslizando pelos tecidos subcutâneos sem aderência, o que facilita a sua extração em suturas intradérmicas contínuas."},{"id":"tempos-23","examId":"tempos","number":23,"stem":"A escolha do tipo de agulha cirúrgica deve obedecer à consistência e friabilidade do tecido abordado. Ao realizar anastomoses gástricas ou intestinais em tecidos friáveis e nobres, a agulha mais adequada para evitar rasgamento ou trauma tecidual cortante é a agulha:","options":{"A":"Reta triangular com bordo cortante invertido","B":"Traumática cortante de perfil losângico","C":"Atraumática (cilíndrica)","D":"Curva espatulada de grande curvatura"},"answer":"C","explanation":"Agulhas cilíndricas atraumáticas têm secção transversal arredondada e ponta afunilada romba que apenas afasta as fibras teciduais sem cortar, sendo mandatórias na sutura de vísceras moles e parenquimatosas."},{"id":"tempos-24","examId":"tempos","number":24,"stem":"Durante o encerramento de feridas cutâneas superficiais, as suturas em pontos separados apresentam vantagens biomecânicas importantes sobre as suturas contínuas. Uma dessas vantagens consiste em:","options":{"A":"Serem independentes entre si, de modo que a rutura ou afrouxamento de um ponto não compromete a integridade do restante da sutura.","B":"Promoverem maior isquemia nas margens cirúrgicas em comparação com as suturas contínuas.","C":"Introduzirem maior quantidade de corpos estranhos dentro da lesão.","D":"Serem impermeáveis à drenagem espontânea de hematomas serosos."},"answer":"A","explanation":"A individualidade dos nós cirúrgicos nos pontos separados confere segurança mecânica: se um ponto afrouxar, romper-se ou for removido para drenagem de coleção, os demais mantêm a ferida fechada."},{"id":"tempos-25","examId":"tempos","number":25,"stem":"Um paciente jovem dá entrada com ferimento cortocontuso linear no antebraço direito. O médico opta por suturar a ferida em pontos simples separados. O objetivo primordial do ponto simples na síntese cutânea é:","options":{"A":"Provocar inversão deliberada das margens da derme para evitar cicatrizes espessas.","B":"Garantir a coaptação das margens e restaurar a continuidade anatómica da pele com mínima isquemia tecidual.","C":"Promover a necrose programada do estrato córneo epitelial.","D":"Tracionar a musculatura profunda em monobloco com a tela subcutânea."},"answer":"B","explanation":"O ponto simples isolado tem a finalidade mecânica primária de aproximar bordos congruentes sem inversão excessiva, devolvendo a contiguidade anatómica e preservando a vascularização da microcirculação dérmica."},{"id":"tempos-26","examId":"tempos","number":26,"stem":"Na abordagem de feridas sob moderada a alta tensão, ou em regiões que requerem hemostasia cutânea associada à eversão das margens cirúrgicas, costumam-se empregar variantes de pontos em \"U\". O ponto em \"U\" horizontal e o ponto em \"U\" vertical são conhecidos na prática cirúrgica, respetivamente, pelos epónimos:","options":{"A":"Sutura de Lembert e sutura de Halsted","B":"Ponto de Wolff e ponto de Donatti","C":"Ponto de Connell e sutura de Cushing","D":"Ponto de Mayo e chuleio de Reverdin"},"answer":"B","explanation":"O ponto em \"U\" horizontal recebe o epónimo de Wolff e o ponto em \"U\" vertical o de Donatti."},{"id":"tempos-27","examId":"tempos","number":27,"stem":"Paciente é admitido com laceração no couro cabeludo associada a sangramento ativo e tensão para o encerramento das margens. O cirurgião opta por realizar uma sutura vertical que transfixa diferentes profundidades da lesão na sequência \"longe-longe, perto-perto\", promovendo boa coaptação e hemostasia. Esta descrição corresponde ao:","options":{"A":"Ponto simples com nó invertido","B":"Ponto de Donatti (U vertical)","C":"Ponto em \"X\" horizontal","D":"Chuleio ancorado contínuo"},"answer":"B","explanation":"O ponto de Donatti é a sutura em \"U\" vertical que transfixa a lesão na sequência longe-longe, perto-perto, promovendo coaptação e hemostasia em feridas sob tensão, como no couro cabeludo."},{"id":"tempos-28","examId":"tempos","number":28,"stem":"Ao comparar a sutura contínua em chuleio simples com o chuleio ancorado, verifica-se que o chuleio ancorado apresenta como características primordiais:","options":{"A":"Maior potencial isquemiante, elevada ação hemostática e menor resultado estético final.","B":"Menor aposição das bordas e ausência completa de efeito oclusivo tecidual.","C":"Excelente resultado estético, sendo a sutura de eleição na face de pacientes pediátricos.","D":"Baixa capacidade hemostática e facilidade de desarmamento em tecidos edemaciados."},"answer":"A","explanation":"O chuleio ancorado aumenta a tensão sobre as margens, tem maior potencial isquemiante e melhor hemostasia, com resultado estético inferior ao do chuleio simples."},{"id":"tempos-29","examId":"tempos","number":29,"stem":"A retirada atempada dos fios de sutura cutânea é um fator crítico para evitar a formação de marcas inestéticas e garantir a consolidação da cicatriz. Em condições normais de cicatrização, o tempo estimado preconizado para a retirada dos pontos de sutura na face e no pescoço é de, respetivamente:","options":{"A":"14 dias e 10 dias","B":"3 a 4 dias e 5 dias","C":"7 dias e 7 dias","D":"10 dias e 14 dias"},"answer":"B","explanation":"Em condições normais, os pontos da face são retirados em 3 a 4 dias e os do pescoço em cerca de 5 dias, para evitar marcas permanentes da sutura."},{"id":"tempos-30","examId":"tempos","number":30,"stem":"Em cirurgia cutânea e plástica, a correlação entre o calibre métrico dos fios cirúrgicos e a sua espessura dita a sua correta aplicação clínica. Quanto maior o número de zeros, menor é o diâmetro do fio de sutura. Dessa forma, para uma sutura delicada na face com alta exigência estética e para a sutura de áreas de alta tensão no couro cabeludo, utilizam-se habitualmente os calibres de sutura:","options":{"A":"2-0 na face e 6-0 no couro cabeludo","B":"6-0 na face e 2-0 no couro cabeludo","C":"4-0 na face e 5-0 no couro cabeludo","D":"3-0 na face e 4-0 no couro cabeludo"},"answer":"B","explanation":"Quanto maior o número de zeros, mais fino é o fio. Na face usa-se habitualmente 6-0; no couro cabeludo, sob maior tensão, usa-se um fio mais calibroso, como o 2-0."},{"id":"cura-01","examId":"cura","number":1,"stem":"A formação excessiva de tecido cicatricial pode gerar repercussões clínicas e funcionais tão deletérias quanto as falhas na cicatrização. No interior da cavidade peritoneal, a consequência clínica mais comum e temida das cicatrizes peritoneais exuberantes (aderências) após procedimentos cirúrgicos é:","options":{"A":"Pancreatite aguda necro-hemorrágica.","B":"Abdome agudo obstrutivo.","C":"Hérnia diafragmática congénita.","D":"Degeneração carcinomatosa peritoneal imediata."},"answer":"B","explanation":"As aderências peritoneais são traves e cordões fibrosos formados após peritonite ou intervenções cirúrgicas, sendo a causa mais comum de obstrução mecânica do intestino delgado (abdome agudo obstrutivo)."},{"id":"cura-02","examId":"cura","number":2,"stem":"As cicatrizes hipertróficas e os queloides são afecções comuns causadas por alteração na proliferação e remodelação tecidual. Ambas as entidades caracterizam-se do ponto de vista anatomopatológico fundamentalmente pela:","options":{"A":"Escassez de colágeno associada à ausência completa de vascularização dérmica.","B":"Superabundância de fibroblastos no processo de cura da derme após um traumatismo.","C":"Invasão neoplásica do tecido celular subcutâneo por queratinócitos atípicos.","D":"Destruição das fibras elásticas exclusivamente por bactérias patogénicas da flora residente."},"answer":"B","explanation":"As cicatrizes proliferativas (hipertrófica e queloide) ocorrem secundariamente a uma superabundância e hiperproliferação de fibroblastos na derme durante o processo de reparação tecidual pós-trauma."},{"id":"cura-03","examId":"cura","number":3,"stem":"Paciente do sexo masculino, 24 anos, é atendido no ambulatório de cirurgia apresentando uma lesão cicatricial na região pré-esternal com 4 semanas de evolução pós-trauma. A cicatriz mostra-se elevada, eritematosa, pruriginosa, porém mantém-se estritamente dentro dos limites da incisão original. O cirurgião diagnostica cicatriz hipertrófica. Em relação à sua fisiopatologia e evolução natural, é correto afirmar que:","options":{"A":"O risco de desenvolvimento de cicatriz hipertrófica aumenta significativamente quando a epitelização da ferida ultrapassa 21 dias.","B":"A cicatriz hipertrófica expande-se desordenadamente além dos limites da lesão original e não involui com o tempo.","C":"O quadro acomete exclusivamente indivíduos de etnia caucasiana e com padrão de herança autossómica recessiva.","D":"Desenvolve-se habitualmente apenas anos após o evento traumático inicial."},"answer":"A","explanation":"O risco de desenvolvimento de cicatriz hipertrófica aumenta expressivamente caso a epitelização completa da ferida demore mais de 21 dias. Caracteriza-se por permanecer dentro dos limites da lesão original e pode regredir espontaneamente com o tempo."},{"id":"cura-04","examId":"cura","number":4,"stem":"Diferente das cicatrizes hipertróficas, os queloides apresentam características clínicas e epidemiológicas particulares. Assinale a afirmativa que apresenta corretamente uma propriedade dos queloides:","options":{"A":"Respeitam rigorosamente as margens da lesão inicial e regridem de forma espontânea e rápida.","B":"Podem surgir mesmo após traumatismos mínimos, desenvolvem-se tipicamente entre 3 meses a anos após a lesão e ultrapassam as margens da ferida original.","C":"Não guardam nenhuma relação com etnias mais pigmentadas ou predisposição genética individual.","D":"O tratamento cirúrgico isolado por excisão simples confere cura definitiva em praticamente 100% dos casos."},"answer":"B","explanation":"O queloide desenvolve-se classicamente após semanas, meses ou anos do trauma, ultrapassa os limites anatómicos originais da ferida inicial, não regride espontaneamente e tem maior incidência em indivíduos de pele escura e hispânicos."},{"id":"cura-05","examId":"cura","number":5,"stem":"Uma jovem de 19 anos comparece à consulta com queixa de queloide exuberante na face anterior do tórax decorrente de um quadro de varicela prévio. O cirurgião plástico contraindica a excisão cirúrgica simples isolada como primeira opção terapêutica. A justificativa formal para essa contraindicação é que:","options":{"A":"A cirurgia isolada apresenta elevada taxa de recidiva, podendo resultar em lesões ainda mais extensas.","B":"A excisão cirúrgica estimula a metaplasia de miofibroblastos em osteoblastos estromais.","C":"O queloide desaparece invariavelmente até ao primeiro ano sem necessidade de intervenções invasivas.","D":"Não há vasos sanguíneos no queloide, o que impede a cicatrização da sutura operatória."},"answer":"A","explanation":"A excisão cirúrgica simples isolada do queloide cursa com altíssimas taxas de recidiva devido à predisposição biológica tecidual do doente, exigindo associações terapêuticas multimodais (como corticoides ou silicone)."},{"id":"cura-06","examId":"cura","number":6,"stem":"A terapia farmacológica com corticoide intralesional é amplamente utilizada no manejo das cicatrizes anómalas. No tratamento do queloide e da cicatriz hipertrófica, a infiltração intralesional de corticosteroides atua primordialmente através da:","options":{"A":"Estimulação direta da proliferação de fibroblastos e amplificação do TGF-beta.","B":"Redução da proliferação de fibroblastos, diminuição da síntese de colágeno e atenuação do processo inflamatório local.","C":"Necrose química total da derme com reepitelização espontânea em 48 horas.","D":"Destruição exclusiva das terminações nervosas periféricas sem qualquer ação no estroma conjuntivo."},"answer":"B","explanation":"Os corticosteroides intralesionais atenuam o processo inflamatório crónico, inibem a proliferação excessiva de fibroblastos e reduzem a transcrição de citocinas profibróticas (como TGF-beta), diminuindo a síntese de colágeno e glicosaminoglicanos."},{"id":"cura-07","examId":"cura","number":7,"stem":"A radioterapia pode ser utilizada de forma adjuvante no tratamento de cicatrizes anómalas refratárias. Contudo, a sua aplicação envolve potenciais efeitos adversos e riscos que devem ser ponderados. Entre as complicações associadas ao uso da radiação no leito cicatricial, incluem-se:","options":{"A":"Aumento exuberante do número de fibroblastos viáveis com cicatrização imediata.","B":"Risco de hiperpigmentação, prurido, eritema, parestesias, dor local e potencial indução de malignidade secundária.","C":"Reabsorção total dos folículos sebáceos sem interferência no estroma fibroso.","D":"Ausência completa de alterações na pigmentação ou na sensibilidade cutânea."},"answer":"B","explanation":"A radiação ionizante destrói fibroblastos, contudo traz riscos locais significativos, incluindo alterações na pigmentação (hipo ou hiperpigmentação), prurido, eritema, parestesias, dor e potencial de malignização secundária tardia."},{"id":"cura-08","examId":"cura","number":8,"stem":"O uso de malhas ou vestes compressivas elásticas é uma medida mecânica reconhecida para o tratamento de cicatrizes hipertróficas. Os parâmetros técnicos recomendados para a eficácia clínica da terapia por compressão são:","options":{"A":"Pressão tecidual entre 5 e 10 mmHg, aplicada durante 2 horas à noite por um período de 15 dias.","B":"Início precoce com pressões terapêuticas de 24 a 30 mmHg, de uso contínuo (24 horas/dia) durante 1 ano ou mais.","C":"Pressão de 80 mmHg mantida por apenas 10 minutos a cada duas semanas.","D":"Compressão intermitente realizada apenas durante o banho morno com sabão antisséptico."},"answer":"B","explanation":"A terapia compressiva requer início precoce e o emprego de roupas/malhas que exerçam pressão terapêutica contínua entre 24 e 30 mmHg durante 24 horas por dia, ao longo de pelo menos 1 ano, para induzir isquemia local e acelerar a maturação/achatamento do colágeno."},{"id":"cura-09","examId":"cura","number":9,"stem":"As aderências peritoneais decorrem da formação de bandas fibrosas anómalas entre superfícies serosas adjacentes. Na fisiopatologia deste processo, a lesão peritoneal cirúrgica ou infecciosa desencadeia resposta inflamatória caracterizada pelo depósito entre as superfícies serosas lesadas de:","options":{"A":"Gordura marrom subcutânea.","B":"Fibrina.","C":"Queratina madura esfoliativa.","D":"Depósitos de hidroxiapatita cálcica."},"answer":"B","explanation":"O dano às superfícies peritoneais desencadeia exsudação inflamatória rica em fatores de coagulação que culmina no depósito fibrinoso entre alças intestinais e a parede abdominal; a ausência de lise fisiológica dessa fibrina consolida a banda de aderência fibrosa."},{"id":"cura-10","examId":"cura","number":10,"stem":"No atendimento inicial de um paciente vítima de ferimento cortocontuso recente na perna, a abordagem da lesão aguda deve seguir uma sequência lógica e metódica. Assinale a alternativa que descreve a ordem correta das etapas iniciais de manejo:","options":{"A":"Sutura definitiva com pontos simples \\rightarrow desbridamento a seco \\rightarrow infiltração de anestésico \\rightarrow anamnese.","B":"Anamnese detalhada do mecanismo de trauma \\rightarrow exame físico da lesão \\rightarrow anestesia local \\rightarrow exploração, irrigação abundante e desbridamento.","C":"Aplicação de cola tecidual \\rightarrow tricotomia ampla com lâmina de barbear \\rightarrow anestesia troncular.","D":"Exploração digital cruenta sem anestesia \\rightarrow antibioticoterapia empírica \\rightarrow fechamento primário."},"answer":"B","explanation":"O manejo da ferida aguda inicia-se com a anamnese e exame da profundidade da lesão, prosseguindo com anestesia meticulosa que permite exploração anatómica profunda, irrigação salina abundante e desbridamento dos bordos antes da sutura."},{"id":"cura-11","examId":"cura","number":11,"stem":"Para a limpeza e remoção mecânica eficaz de detritos, terra e corpos estranhos do interior de uma ferida cirúrgica ou traumática aberta, a solução recomendada para irrigação pulsada em abundância é:","options":{"A":"Álcool a 70% diluído em glicose a 50%.","B":"Solução salina normal (soro fisiológico a 0,9%) sem aditivos.","C":"Tintura de iodo tópica pura sob pressão manual.","D":"Água oxigenada a 100 volumes associada a ácido peracético concentrado."},"answer":"B","explanation":"A remoção de materiais estranhos e contaminantes da ferida é idealmente realizada com soro fisiológico a 0,9% puro em pressão/pulsação, sem adição de antissépticos cáusticos que retardem a cicatrização celular."},{"id":"cura-12","examId":"cura","number":12,"stem":"Durante o desbridamento de uma ferida traumática grave com margens esmagadas, irregulares ou desvitalizadas, a meta técnica do cirurgião deve ser:","options":{"A":"Manter todo o tecido necrótico para servir de arcabouço celular hemostático.","B":"Ressecar as bordas irregulares, maceradas ou bizeladas até obter margens limpas, viáveis e sangrantes para reaproximação.","C":"Cauterizar extensivamente toda a pele circundante com eletrocautério na potência máxima.","D":"Evitar a realização de hemostasia para não alterar os bordos da lesão."},"answer":"B","explanation":"A margem da ferida deve ser regularizada e desbridada até tecidos sãos, com bordas limpas e sangrantes, eliminando tecidos desvitalizados e bactérias aderidas para viabilizar uma síntese segura."},{"id":"cura-13","examId":"cura","number":13,"stem":"Na síntese por planos de uma laparotomia abdominal extensa, a escolha do fio cirúrgico para a aproximação das camadas fasciais profundas (aponevrose) deve recair sobre fios que garantam suporte tênsil prolongado. O material mais apropriado para o encerramento da fáscia da parede abdominal é:","options":{"A":"Categute simples de absorção ultra-rápida.","B":"Fio monofilamentar inabsorvível ou de absorção lenta.","C":"Linha de algodão multifilamentar fina 6-0.","D":"Fita adesiva microporada simples colocada sobre a musculatura."},"answer":"B","explanation":"O plano aponevrótico profundo da parede abdominal suporta grandes cargas de tensão; por isso, a sua aproximação exige fios monofilamentares inabsorvíveis (como o nylon ou prolene) ou de absorção lenta (como o PDS)."},{"id":"cura-14","examId":"cura","number":14,"stem":"No encerramento do tecido celular subcutâneo, a aposição tem como finalidade reduzir o espaço morto e evitar seromas ou hematomas. A recomendação técnica correta para a síntese do subcutâneo é:","options":{"A":"Utilizar fios absorvíveis trançados, com cuidado para não incluir a gordura de forma exagerada e desnecessária.","B":"Utilizar fios de aço inoxidável multifilamentares apertados com nós volumosos.","C":"Realizar sutura contínua ancorada com fio de seda 0 englobando todos os feixes vasculares.","D":"Não aproximar os tecidos subcutâneos em nenhuma hipótese de ferida limpa."},"answer":"A","explanation":"No subcutâneo são indicados fios absorvíveis sintéticos trançados; o cirurgião deve aproximar a fáscia superficial sem englobar grandes blocos de tecido adiposo, que sofrem necrose por isquemia."},{"id":"cura-15","examId":"cura","number":15,"stem":"Em lacerações cutâneas lineares da face em crianças ou jovens nas quais o resultado estético é primordial, o cirurgião pode optar por suturas dérmicas profundas associadas a dispositivos tópicos. Quando se emprega a técnica de sutura dérmica sepultada para um encerramento cosmético superior, o fio de eleição é:","options":{"A":"Fio trançado absorvível.","B":"Fio metálico de aço inoxidável 1-0.","C":"Fio de nylon monofilamentar 2-0 calibroso com nó externo evertido.","D":"Categute cromado com nós na epiderme."},"answer":"A","explanation":"A técnica de sutura dérmica sepultada para aproximação subepidérmica utiliza fios absorvíveis finos (multifilamentares), permitindo a correta aposição dos bordos sem deixar as marcas transversais das suturas convencionais percutâneas."},{"id":"cura-16","examId":"cura","number":16,"stem":"O uso de adesivo cutâneo tecidual à base de cianoacrilato (octilcianoacrilato) para o encerramento da pele está clinicamente bem indicado em:","options":{"A":"Feridas cavitárias infectadas com saída franca de pus.","B":"Feridas lineares simples com bordas viáveis e facilmente aproximáveis, sem tensão e sem contaminação relevante.","C":"Lacerações articulares complexas com perda de substância e exposição óssea.","D":"Ferimentos provocados por mordeduras de animais domésticos infectadas por anaeróbios."},"answer":"B","explanation":"A cola cirúrgica (octilcianoacrilato) tem indicação em lacerações dérmicas superficiais lineares sob baixa tensão, cujos bordos se aproximem sem tração e sem sinais de infecção ou contaminação grosseira."},{"id":"cura-17","examId":"cura","number":17,"stem":"A remoção de pontos cirúrgicos ou grampos cutâneos deve ser planejada no tempo adequado para evitar marcas inestéticas permanentes causadas pela passagem das agulhas. A retirada de suturas cutâneas na face e nas demais regiões do corpo deve ser realizada habitualmente, respetivamente, em:","options":{"A":"15 a 20 dias na face e 2 dias nas outras áreas.","B":"4 a 5 dias na face e 7 a 10 dias nas demais regiões corporais.","C":"30 dias na face e 1 dia no couro cabeludo.","D":"24 horas na face e 4 semanas nas extremidades."},"answer":"B","explanation":"A face possui farta vascularização e rápida reepitelização, exigindo retirada de pontos precoce (4 a 5 dias) para evitar cicatrizes puntiformes; nas outras regiões corporais com maior tensão mecânica, os pontos costumam permanecer de 7 a 10 dias."},{"id":"cura-18","examId":"cura","number":18,"stem":"Em feridas cirúrgicas ou traumáticas agudas, o uso de antibióticos sistêmicos tem indicação clínica precisa e não deve ser prescrito de forma indiscriminada. A antibioticoterapia sistêmica terapêutica está indicada especificamente diante de:","options":{"A":"Cicatrizes atróficas ou hipertróficas antigas totalmente reepitelizadas.","B":"Sinais evidentes de infecção local ou sistêmica na ferida (como eritema expansivo, celulite, edema e drenagem purulenta).","C":"Qualquer escoriação superficial da epiderme sem sinais flogísticos.","D":"Presença isolada de sutura cutânea com fio monofilamentar inabsorvível."},"answer":"B","explanation":"O uso de antibioticoterapia em feridas agudas reserva-se aos casos com infecção tecidual instalada, evidenciada por sinais clínicos como hiperemia progressiva com celulite, dor desproporcional, edema importante e secreção purulenta."},{"id":"cura-19","examId":"cura","number":19,"stem":"O principal objetivo fisiológico na escolha de uma cobertura ou curativo para feridas abertas é:","options":{"A":"Manter a ferida completamente desidratada e isquêmica para impedir a proliferação bacteriana.","B":"Prover um ambiente ideal para a cicatrização, simulando a barreira epitelial e controlando exsudato e umidade.","C":"Impedir toda e qualquer troca de vapores d'água entre a lesão e a atmosfera.","D":"Favorecer a hemorragia capilar contínua para renovação dos fatores de coagulação."},"answer":"B","explanation":"O curativo serve como uma barreira que reproduz temporariamente as funções protetoras do epitélio íntegro, assegurando meio com temperatura, trocas gasosas e umidade equilibradas para o avanço dos queratinócitos e fibroblastos."},{"id":"cura-20","examId":"cura","number":20,"stem":"A aplicação de curativos oclusivos ou coberturas impermeáveis sobre feridas cirúrgicas requer avaliação clínica cuidadosa. É considerada uma contraindicação formal ao uso de curativos oclusivos a presença de:","options":{"A":"Feridas limpas pós-operatórias com bordos aproximados por sutura intradérmica.","B":"Feridas abertas francamente infectadas e com abundante secreção purulenta.","C":"Pequenas escoriações tratadas com pomada não aderente.","D":"Áreas doadoras de enxerto de espessura parcial sem sinais flogísticos."},"answer":"B","explanation":"Lesões infectadas e excessivamente secretivas não devem ser ocluídas com materiais impermeáveis, pois a retenção de fluidos purulentos intensifica a proliferação bacteriana e dissemina o foco inflamatório para planos mais profundos."},{"id":"cura-21","examId":"cura","number":21,"stem":"Os curativos absorventes possuem grande relevância clínica no manejo pós-operatório e de feridas exsudativas. Entre as funções exercidas por um curativo absorvente adequado, destaca-se:","options":{"A":"Promover a retenção indiscriminada de líquido estagnado sobre a pele levando à maceração tecidual.","B":"Proteger contra o meio externo, exercer compressão hemostática, limitar o edema e controlar a hidratação e a permeabilidade de gases.","C":"Substituir em definitivo a síntese cirúrgica de feridas fascias profundas.","D":"Induzir a formação de aderências entre órgãos peritoneais internos."},"answer":"B","explanation":"Coberturas absorventes drenam o excesso de secreção para fora do leito, previnem a maceração peri-lesão, proporcionam proteção mecânica e compressão que auxilia na hemostasia e redução do edema intersticial."},{"id":"cura-22","examId":"cura","number":22,"stem":"No cuidado de feridas com leito cruento e em fase de granulação ou epitelização ativa, os curativos não aderentes são preferidos para:","options":{"A":"Fixar as bactérias patogênicas à derme profunda através de microfibras de lã.","B":"Evitar que a cobertura adira ao leito da lesão, prevenindo traumas mecânicos, dor e arrancamento tecidual na sua remoção.","C":"Funcionar como agentes desbridantes cáusticos imediatos.","D":"Impedir a colocação de qualquer tipo de cobertura secundária estéril."},"answer":"B","explanation":"Curativos impregnados com parafina ou petrolato evitam a adesão da cobertura à área cruenta da lesão, permitindo que a troca do curativo decorra sem dor e sem o descolamento mecânico da fina camada celular em fase de epitelização."},{"id":"cura-23","examId":"cura","number":23,"stem":"Os curativos compostos podem integrar propriedades hidrofílicas e hidrofóbicas na mesma cobertura. A função específica da camada hidrofílica em contacto com o leito cruento consiste em:","options":{"A":"Repelir qualquer fluido biológico acumulando líquido livre nas margens.","B":"Absorver o exsudato e manter uma hidratação equilibrada e controlada na ferida.","C":"Impermeabilizar a entrada de oxigénio na intimidade tecidual.","D":"Fixar esporos bacterianos no interior da malha de colágeno."},"answer":"B","explanation":"Em coberturas combinadas, a face hidrofílica em contato direto com a ferida absorve o exsudato estagnado, mantendo a humidade basal controlada necessária para a migração celular sem encharcamento da derme."},{"id":"cura-24","examId":"cura","number":24,"stem":"Os curativos à base de hidrogel diferenciam-se das placas clássicas de hidrocoloide por proporcionarem alta taxa de evaporação sem ressecar a lesão. Essa propriedade física torna o hidrogel particularmente útil e indicado no manejo clínico de:","options":{"A":"Feridas profundas em peritônio com evisceração intestinal aguda.","B":"Queimaduras de espessura parcial e lesões com necessidade de hidratação e evaporação equilibradas.","C":"Fístulas urinárias de alto débito com drenagem purulenta franca.","D":"Fraturas ósseas expostas instáveis com sangramento pulsátil."},"answer":"B","explanation":"O hidrogel promove evaporação e resfriamento suave mantendo a hidratação ideal, sendo indicado em queimaduras de espessura parcial para alívio álgico e protecção das terminações sensitivas."},{"id":"cura-25","examId":"cura","number":25,"stem":"O alginato é um curativo bioativo amplamente utilizado em feridas cavitárias ou de espessura total altamente exsudativas. O seu mecanismo de ação baseia-se na troca iónica entre:","options":{"A":"Os íons de ferro da hemoglobina e o sódio das células musculares.","B":"O alginato de cálcio presente no curativo e o sódio contido no exsudato da ferida, formando um gel solúvel que absorve grandes volumes de líquido.","C":"A queratina dérmica e o cloro da solução antisséptica tópica.","D":"Os cristais de ácido fólico e as placas de silicone estéril."},"answer":"B","explanation":"Os alginatos são formulados com sais de cálcio; ao contactarem o sódio presente no exsudato patológico da ferida, ocorre uma troca iónica que transforma o polímero num gel coeso capaz de absorver grande quantidade de fluidos."},{"id":"cura-26","examId":"cura","number":26,"stem":"Materiais absorvíveis aplicados no interior de lojas cirúrgicas e feridas viscerais para promover hemostasia pontual onde a ligadura tradicional é tecnicamente difícil incluem:","options":{"A":"Gaze estéril solta não radiopaca e algodão hidrófilo.","B":"Esponjas de colágeno, gelatina, celulose oxidada e celulose regenerada.","C":"Sulfato de bário com parafina sólida industrializada.","D":"Grânulos de peróxido de benzoíla com nitrato de prata puro."},"answer":"B","explanation":"Substâncias absorvíveis hemostáticas — tais como celulose regenerada oxidada, esponjas de gelatina e colágeno bovino — são concebidas para aplicação no interior das incisões, promovendo hemostasia por contato e sendo reabsorvidas pelo organismo."},{"id":"cura-27","examId":"cura","number":27,"stem":"A terapia por pressão negativa contínua (curativo a vácuo) estabeleceu um avanço no tratamento de feridas complexas e extensas. O benefício biológico primário induzido pela pressão subatmosférica na ferida é:","options":{"A":"A dessecação e necrose isquêmica das margens com inibição de novos capilares.","B":"A remoção contínua e eficaz do excesso de exsudato tecidual associada ao estímulo mecânico à proliferação de tecido de granulação e retração da lesão.","C":"A proliferação imediata de células gigantes de corpo estranho com retenção exsudativa.","D":"A paralisia reversível dos vasos de pequeno calibre periféricos."},"answer":"B","explanation":"O fechamento assistido a vácuo (pressão negativa contínua) reduz o edema tecidual intersticial através da drenagem ativa de fluidos e exsudatos, promovendo microdeformações celulares mecânicas que aceleram o tecido de granulação e aproximam as margens da lesão."},{"id":"cura-28","examId":"cura","number":28,"stem":"No que se refere à classificação dos enxertos cutâneos convencionais empregues no encerramento de lesões agudas e crónicas, os enxertos de pele total compreendem:","options":{"A":"Apenas a camada córnea superficial da epiderme.","B":"A epiderme e a derme em toda a sua espessura, conferindo maior resistência mecânica e melhor resultado cosmético.","C":"A epiderme associada exclusivamente a uma faixa de tela subcutânea adiposa espessa.","D":"A epiderme e uma porção rasa da derme papilar apenas."},"answer":"B","explanation":"O enxerto de pele total engloba toda a epiderme e a derme na sua totalidade anatómica; a preservação da derme profunda garante maior elasticidade, menor contratura secundária tardia e qualidade cosmética superior."},{"id":"cura-29","examId":"cura","number":29,"stem":"A respeito da origem imunológica dos enxertos de pele utilizados na cirurgia reconstrutiva, assinale a correlação técnica e terminológica correta:","options":{"A":"Autoenxerto é aquele obtido de doador cadáver ou de indivíduos geneticamente não idênticos da mesma espécie.","B":"Aloenxerto (ou enxerto alógeno) é o tecido transferido entre indivíduos de espécies biológicas distintas.","C":"Xenoenxerto (ou heteronenxerto) refere-se ao enxerto biológico colhido de uma espécie biológica diferente da do recetor.","D":"Enxerto autólogo é aquele colhido de matriz sintética bioengenheirada de silicone."},"answer":"C","explanation":"O xenoenxerto ou heteronenxerto biológico corresponde àquele colhido de espécimes animais de espécie taxonómica distinta da do paciente receptor (por exemplo, uso de pele de tilápia ou derme acelular porcina)."},{"id":"cura-30","examId":"cura","number":30,"stem":"Para que uma ferida aberta e cruenta esteja apta a receber um enxerto cutâneo livre com sucesso e sem risco de necrose precoce do tecido enxertado, é indispensável que o leito receptor apresente:","options":{"A":"Tecido necrótico com abundante exsudato purulento acumulado.","B":"Desbridamento completo de tecidos inviáveis, bom leito vascularizado (tecido de granulação saudável), controlo do edema, ausência de infecção e baixa carga bacteriana.","C":"Hemorragia arterial pulsátil em jato contínuo sobre a superfície receptora.","D":"Obliteração vascular e isquemia do leito promovidas por ligadura de pedículos periféricos."},"answer":"B","explanation":"Como o enxerto livre depende inicialmente da difusão plasmática para nutrir as suas células, o leito tecidual receptor deve estar isento de crostas necróticas ou infecção ativa, contando com granulação exuberante e rica vascularização."}];

export const introById = new Map(introQuestions.map((question) => [question.id, question]));

export const p1QuestionIds = introQuestions.filter((question) => question.examId.startsWith("p")).map((question) => question.id);

export function questionsForExam(examId: string) {
  return introQuestions
    .filter((question) => question.examId === examId)
    .sort((a, b) => a.number - b.number);
}
